    AS $$
declare v_role_id uuid; reason_text text := btrim(coalesce(p_reason,''));
begin
 perform public._lock_notification_session_gate();
  perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
  perform public.assert_admin_permission('admin_users.manage');
  if p_active is null or length(reason_text) not between 1 and 1000 then
    raise exception 'Active state and reason are required' using errcode='22023';
  end if;
  select id into v_role_id from public.admin_roles where name='platform_owner';
  if v_role_id is null or not exists(select 1 from public.profiles where id=p_user) then
    raise exception 'Admin account unavailable' using errcode='22023';
  end if;
  if p_active then
    perform 1 from auth.users where id=p_user for update;
    if not collect_admin_access.approved_identity(p_user) then
      raise exception 'Pre-approved verified WhatsApp identity required' using errcode='42501';
    end if;
    if not exists(select 1 from public.admin_user_roles ur
      where ur.user_id=p_user and ur.role_id=v_role_id and ur.revoked_at is null) then
      insert into public.admin_user_roles(user_id,role_id,granted_by,reason,created_at)
      values(p_user,v_role_id,auth.uid(),reason_text,clock_timestamp());
      insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata)
      values(auth.uid(),'admin.access.activated','profile',p_user,jsonb_build_object('reason',reason_text));
    end if;
    return jsonb_build_object('ok',true,'status','active');
  end if;
  if p_user=auth.uid() then
    raise exception 'You cannot deactivate your own Admin access' using errcode='42501';
  end if;
  -- The caller is an approved active Admin, so deactivating a different account
  -- cannot remove the last approved Admin. This remains true under the lock.
  update public.admin_user_roles ur set revoked_at=clock_timestamp(),revoked_by=auth.uid(),revoke_reason=reason_text
    where ur.user_id=p_user and ur.revoked_at is null;
  if found then
    insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata)
    values(auth.uid(),'admin.access.deactivated','profile',p_user,jsonb_build_object('reason',reason_text));
  end if;
  return jsonb_build_object('ok',true,'status','revoked');
end;
$$;


--
-- Name: verified_phone(uuid); Type: FUNCTION; Schema: collect_admin_access; Owner: -
--

CREATE FUNCTION collect_admin_access.verified_phone(p_user uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
  select '+' || ltrim(u.phone, '+') from auth.users u
  where u.id = p_user and u.phone ~ '^\+?[1-9][0-9]{7,14}$'
    and u.phone_confirmed_at is not null and u.deleted_at is null
    and not coalesce(u.is_anonymous,false)
    and (u.banned_until is null or u.banned_until <= statement_timestamp());
$_$;


--
-- Name: _create_roster_import_source_v142_guarded_149(uuid, uuid, uuid, text, text, bigint, text, text, text, text, bigint, boolean, text, jsonb); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid._create_roster_import_source_v142_guarded_149(p_actor_id uuid, p_session_id uuid, p_request_id uuid, p_source_kind text, p_original_sha256 text, p_original_size bigint, p_client_filename text, p_declared_mime text, p_detected_type text, p_derived_sha256 text, p_derived_size bigint, p_ai_consent boolean, p_consent_version text, p_ai_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare s collect_hybrid.roster_import_sources; result collect_hybrid.roster_import_results;
 fingerprint text; extraction uuid; replayed boolean:=false; ai boolean:=p_source_kind in ('pdf','image');
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'roster_service_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(p_actor_id,p_session_id);
 if p_request_id is null or p_source_kind is null or p_source_kind not in ('text','csv','txt','xlsx','pdf','image')
   or p_original_sha256 is null or p_original_sha256 !~ '^[a-f0-9]{64}$'
   or p_original_size is null or p_original_size not between 1 and (case when p_source_kind in ('text','csv','txt') then 512000 else 5242880 end)
   or p_client_filename is null or p_client_filename !~ '^[A-Za-z0-9][A-Za-z0-9._ -]{0,159}$'
   or p_declared_mime is null or length(p_declared_mime) not between 1 and 128 or p_declared_mime ~ '[[:cntrl:]]'
   or p_detected_type is null
   or (p_source_kind in ('text','txt') and p_detected_type<>'utf8_text')
   or (p_source_kind='csv' and p_detected_type<>'utf8_csv')
   or (p_source_kind='xlsx' and p_detected_type<>'zip_container')
   or (p_source_kind='pdf' and p_detected_type<>'application/pdf')
   or (p_source_kind='image' and p_detected_type not in ('image/png','image/jpeg','image/webp'))
   or (p_source_kind='xlsx' and (p_derived_sha256 is null or p_derived_sha256 !~ '^[a-f0-9]{64}$' or p_derived_size is null or p_derived_size not between 1 and 512000))
   or (p_source_kind<>'xlsx' and (p_derived_sha256 is not null or p_derived_size is not null))
   or p_ai_consent is distinct from ai
   or (not ai and (p_consent_version is not null or p_ai_metadata is not null)) then
  raise exception 'roster_input_invalid' using errcode='22023'; end if;
 if ai then
  if p_consent_version is distinct from 'roster-ai-extraction-v1' or p_ai_metadata is null
    or jsonb_typeof(p_ai_metadata)<>'object' or p_ai_metadata->>'provider' is distinct from 'openai'
    or p_ai_metadata->>'prompt_version' is distinct from 'roster-extraction-v1'
    or jsonb_typeof(p_ai_metadata->'model') is distinct from 'string'
    or length(btrim(p_ai_metadata->>'model')) not between 1 and 128 or (p_ai_metadata->>'model') ~ '[[:cntrl:]]'
    or exists(select 1 from jsonb_object_keys(p_ai_metadata) k where k not in ('provider','model','prompt_version')) then
   raise exception 'roster_input_invalid' using errcode='22023'; end if;
 end if;
 fingerprint:=collect_hybrid.roster_digest(jsonb_build_array(p_actor_id,p_session_id,p_source_kind,p_original_sha256,p_original_size,
   p_client_filename,p_declared_mime,p_detected_type,p_derived_sha256,p_derived_size,p_ai_consent,p_consent_version,p_ai_metadata));
 select * into s from collect_hybrid.roster_import_sources where request_id=p_request_id;
 if s.id is not null then
  if s.input_sha256<>fingerprint then raise exception 'roster_request_conflict' using errcode='55000'; end if;
  select * into result from collect_hybrid.roster_import_results where import_id=s.id;
  if result.import_id is null then raise exception 'roster_import_in_progress' using errcode='55000'; end if;
  replayed:=true;
 else
  if (select count(*) from collect_hybrid.roster_import_sources where actor_id=p_actor_id and created_at>clock_timestamp()-interval '24 hours')>=100 then
   raise exception 'roster_import_limit' using errcode='55000'; end if;
  insert into collect_hybrid.roster_import_sources(request_id,actor_id,session_id,source_kind,source_sha256,source_size,
   client_filename,declared_mime,detected_type,derived_sha256,derived_size,ai_consent,consent_version,input_sha256)
  values(p_request_id,p_actor_id,p_session_id,p_source_kind,p_original_sha256,p_original_size,p_client_filename,p_declared_mime,
   p_detected_type,p_derived_sha256,p_derived_size,p_ai_consent,p_consent_version,fingerprint) returning * into s;
  if ai then
   insert into collect_hybrid.roster_import_extractions(import_id,actor_id,session_id,provider,model,prompt_version,consent_version)
   values(s.id,p_actor_id,p_session_id,'openai',p_ai_metadata->>'model','roster-extraction-v1',p_consent_version);
  end if;
 end if;
 select id into extraction from collect_hybrid.roster_import_extractions where import_id=s.id;
 return jsonb_build_object('contract_version',1,'ok',true,'request_id',s.request_id,'import_id',s.id,
  'source_sha256',s.source_sha256,'source_size',s.source_size,'source_kind',s.source_kind,'extraction_id',extraction,
  'expires_at',s.expires_at,'derived_sha256',s.derived_sha256,'derived_assurance',case when s.source_kind='xlsx' then 'client_derived_tsv' end,
  'state',coalesce(result.state,'awaiting_preview'),'replayed',replayed,
  'completed_preview',collect_hybrid.roster_revision_receipt(result.revision_id),'error_code',result.error_code);
end $_$;


--
-- Name: add_roster(uuid, jsonb, uuid, text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.add_roster(p_collection_id uuid, p_rows jsonb, p_request_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  row_data jsonb;
  phone text;
  registered_name text;
  display_name text;
  identity_row collect_hybrid.member_momo_identities;
  record_id uuid;
  result_rows jsonb := '[]'::jsonb;
  response jsonb;
  old_batch collect_hybrid.roster_batches;
  input_digest text;
begin
  perform collect_hybrid.assert_onboarding();
  if p_request_id is null
     or p_reason is null
     or char_length(btrim(p_reason)) not between 8 and 500
     or p_rows is null
     or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'Invalid reviewed roster request';
  end if;
  if jsonb_array_length(p_rows) not between 1 and 500 then
    raise exception 'Roster must contain 1 to 500 reviewed rows';
  end if;
  perform 1
  from public.collections collection
  where collection.id = p_collection_id
    and collection.creation_origin = 'admin_assisted'
    and collection.archived_at is null
    and collection.public_status = 'private'
    and not collection.diaspora_enabled
  for update;
  if not found then
    raise exception 'Active private assisted Rwanda group required';
  end if;
  input_digest := encode(extensions.digest(
    p_collection_id::text || p_rows::text || btrim(p_reason),
    'sha256'
  ), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(
    'hybrid-roster:' || p_request_id::text,
    0
  ));
  select batch.* into old_batch
  from collect_hybrid.roster_batches batch
  where batch.request_id = p_request_id;
  if old_batch.request_id is not null then
    if old_batch.input_hash <> input_digest or old_batch.actor_id <> auth.uid() then
      raise exception 'Roster idempotency key conflict';
    end if;
    return old_batch.result || jsonb_build_object('replay', true);
  end if;

  perform pg_advisory_xact_lock(hashtextextended('collect-numeric-member-id', 0));
  for row_data in select value from jsonb_array_elements(p_rows) loop
    if jsonb_typeof(row_data) <> 'object' then
      raise exception 'Invalid roster row';
    end if;
    phone := collect_hybrid.canonical_momo_number(row_data->>'momo_number');
    registered_name := btrim(row_data->>'momo_name');
    display_name := btrim(coalesce(
      nullif(row_data->>'member_name', ''),
      registered_name
    ));
    if phone is null
       or registered_name is null
       or char_length(registered_name) not between 2 and 120
       or display_name is null
       or char_length(display_name) not between 2 and 120
       or registered_name ~ '[[:cntrl:]]'
       or display_name ~ '[[:cntrl:]]' then
      raise exception 'Each row requires a valid full MoMo number and names';
    end if;
    select identity.* into identity_row
    from collect_hybrid.member_momo_identities identity
    where identity.momo_number = phone;
    if identity_row.member_id is not null then
      if identity_row.normalized_name <>
          collect_hybrid.normalize_momo_name(registered_name)
         or identity_row.member_name <> display_name then
        raise exception 'Existing MoMo identity differs; review before updating';
      end if;
      record_id := identity_row.member_id;
      if not exists (
        select 1 from collect_hybrid.member_records member
        where member.id = record_id and member.lifecycle = 'active'
      ) then
        raise exception 'Existing member is inactive';
      end if;
    else
      if exists (
        select 1 from public.profiles profile
        where regexp_replace(coalesce(profile.momo_number, ''), '^0', '+250') = phone
      ) then
        raise exception 'Existing app MoMo number requires reviewed identity linking';
      end if;
      insert into collect_hybrid.member_records(collect_id, origin, created_by)
      values (public.generate_public_id(), 'admin_assisted', auth.uid())
      returning id into record_id;
      insert into collect_hybrid.member_momo_identities(
        member_id,
        member_name,
        momo_name,
        momo_number
      ) values (record_id, display_name, registered_name, phone);
    end if;
    if exists (
      select 1 from public.collection_members membership
      where membership.collection_id = p_collection_id
        and membership.member_record_id = record_id
        and membership.role = 'member'
        and membership.status <> 'active'
    ) then
      raise exception 'Existing membership is not active; review before reactivation';
    end if;
    insert into public.collection_members(
      collection_id,
      member_record_id,
      role,
      status
    ) values (p_collection_id, record_id, 'member', 'active')
    on conflict do nothing;
    result_rows := result_rows || jsonb_build_array(jsonb_build_object(
      'member_id', record_id,
      'collect_id', (
        select member.collect_id
        from collect_hybrid.member_records member
        where member.id = record_id
      )
    ));
  end loop;
  response := jsonb_build_object(
    'ok', true,
    'collection_id', p_collection_id,
    'rows', result_rows,
    'replay', false
  );
  insert into collect_hybrid.roster_batches(
    request_id,
    collection_id,
    actor_id,
    input_hash,
    result
  ) values (p_request_id, p_collection_id, auth.uid(), input_digest, response);
  perform public.create_audit_log(
    'collection.assisted.roster_added',
    'collection',
    p_collection_id,
    jsonb_build_object(
      'reason', btrim(p_reason),
      'request_id', p_request_id,
      'row_count', jsonb_array_length(p_rows)
    )
  );
  return response;
end;
$$;


--
-- Name: admin_commit_roster_import_guarded_149(uuid, uuid, uuid, text, boolean, text, uuid, text, text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.admin_commit_roster_import_guarded_149(p_request_id uuid, p_import_id uuid, p_revision_id uuid, p_reviewed_rows_sha256 text, p_human_affirmed boolean, p_mode text, p_collection_id uuid, p_title text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare sid uuid; s collect_hybrid.roster_import_sources; r collect_hybrid.roster_import_revisions;
 prior collect_hybrid.roster_import_commits; fingerprint text; result jsonb; group_result jsonb; roster_result jsonb;
 group_id uuid; title text:=btrim(p_title); reason text:=btrim(p_reason); validation jsonb;
begin
 sid:=collect_hybrid.require_roster_caller();
 if p_request_id is null or p_import_id is null or p_revision_id is null or p_reviewed_rows_sha256 is null
  or p_reviewed_rows_sha256 !~ '^[a-f0-9]{64}$' or p_human_affirmed is distinct from true
  or p_mode is null or p_mode not in ('create','existing') or reason is null or length(reason) not between 8 and 500 or reason ~ '[[:cntrl:]]'
  or (p_mode='create' and (p_collection_id is not null or title is null or length(title) not between 3 and 120 or title ~ '[[:cntrl:]]'))
  or (p_mode='existing' and (p_collection_id is null or p_title is not null)) then
  raise exception 'roster_input_invalid' using errcode='22023'; end if;
 fingerprint:=collect_hybrid.roster_digest(jsonb_build_array(p_import_id,p_revision_id,p_reviewed_rows_sha256,p_human_affirmed,
  p_mode,p_collection_id,title,reason,auth.uid(),sid));
 select * into prior from collect_hybrid.roster_import_commits where request_id=p_request_id;
 if prior.request_id is not null then
  if prior.input_sha256<>fingerprint then raise exception 'roster_request_conflict' using errcode='55000'; end if;
  return prior.response||jsonb_build_object('replayed',true);
 end if;
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id for update;
 if s.id is null or s.actor_id<>auth.uid() or s.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 if exists(select 1 from collect_hybrid.roster_import_commits where import_id=s.id) then raise exception 'roster_import_committed' using errcode='55000'; end if;
 if s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 select * into r from collect_hybrid.roster_import_revisions where import_id=s.id order by revision_number desc limit 1;
 if r.id is null or r.id<>p_revision_id or r.processing_method<>'human_review' then raise exception 'roster_revision_superseded' using errcode='55000'; end if;
 validation:=collect_hybrid.roster_preview(r.normalized_rows,true);
 if r.reviewed_rows_sha256<>p_reviewed_rows_sha256 or collect_hybrid.roster_digest(validation->'normalized_rows')<>p_reviewed_rows_sha256 then
  raise exception 'roster_request_conflict' using errcode='55000'; end if;
 begin
 if p_mode='create' then
  group_result:=collect_hybrid.create_assisted_group_with_share(title,reason,gen_random_uuid());
  group_id:=(group_result->>'collection_id')::uuid;
 else
  group_id:=p_collection_id;
  perform 1 from public.collections where id=group_id and currency='RWF' and creation_origin='admin_assisted'
   and archived_at is null and visibility='private' and public_status='private' and not diaspora_enabled for update;
  if not found then raise exception 'roster_collection_unavailable' using errcode='22023'; end if;
 end if;
 insert into public.collection_share_secrets(collection_id,rotated_by) values(group_id,auth.uid()) on conflict(collection_id) do nothing;
 roster_result:=collect_hybrid.add_roster(group_id,r.normalized_rows,gen_random_uuid(),reason);
 exception when sqlstate 'P0001' then
  raise exception 'roster_commit_conflict' using errcode='55000';
 end;
 if roster_result->>'ok' is distinct from 'true' or roster_result->>'collection_id' is distinct from group_id::text
   or jsonb_typeof(roster_result->'rows') is distinct from 'array'
   or jsonb_array_length(roster_result->'rows')<>jsonb_array_length(r.normalized_rows) then
  raise exception 'roster_commit_failed' using errcode='55000'; end if;
 result:=jsonb_build_object('contract_version',1,'ok',true,'request_id',p_request_id,'import_id',s.id,'revision_id',r.id,
  'reviewed_rows_sha256',r.reviewed_rows_sha256,'collection_id',group_id,'mode',p_mode,'roster_count',jsonb_array_length(r.normalized_rows),
  'share_code_ready',exists(select 1 from public.collection_share_secrets where collection_id=group_id),'replayed',false);
 insert into collect_hybrid.roster_import_commits(request_id,import_id,revision_id,collection_id,actor_id,session_id,input_sha256,response)
 values(p_request_id,s.id,r.id,group_id,auth.uid(),sid,fingerprint,result);
 perform public.create_audit_log('roster.import.committed','collection',group_id,jsonb_build_object('request_id',p_request_id,
  'import_id',s.id,'revision_id',r.id,'source_sha256',s.source_sha256,'reviewed_rows_sha256',r.reviewed_rows_sha256,
  'human_affirmed',true,'mode',p_mode,'row_count',jsonb_array_length(r.normalized_rows),'reason',reason));
 return result;
end $_$;


--
-- Name: admin_execute_roster_import_intent_guarded_149(uuid, text, boolean); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.admin_execute_roster_import_intent_guarded_149(p_request_id uuid, p_payload_sha256 text, p_human_affirmed boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid; i collect_hybrid.roster_import_recovery_intents; v jsonb; result jsonb; begin
 sid:=collect_hybrid.require_roster_caller();
 if p_human_affirmed is distinct from true then raise exception 'roster_confirmation_required' using errcode='22023'; end if;
 select * into i from collect_hybrid.roster_import_recovery_intents where request_id=p_request_id;
 if i.request_id is null or i.actor_id<>auth.uid() or i.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 if i.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 if i.payload_sha256 is distinct from p_payload_sha256 then raise exception 'roster_request_conflict' using errcode='55000'; end if;
 v:=collect_hybrid.roster_recovery_payload(i.payload,i.payload_sha256,i.kind);
 if i.kind='review' then
  result:=public.admin_review_roster_import(i.import_id,(v->>'p_parent_revision_id')::uuid,v->'p_rows',v->>'p_reason',i.request_id);
 else
  result:=public.admin_commit_roster_import(i.request_id,i.import_id,(v->>'p_revision_id')::uuid,v->>'p_reviewed_rows_sha256',
   (v->>'p_human_affirmed')::boolean,v->>'p_mode',(v->>'p_collection_id')::uuid,v->>'p_title',v->>'p_reason');
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'request_id',i.request_id,'import_id',i.import_id,
  'kind',i.kind,'payload_sha256',i.payload_sha256,'result',result);
end $$;


--
-- Name: admin_get_roster_import_guarded_149(uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.admin_get_roster_import_guarded_149(p_import_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid; s collect_hybrid.roster_import_sources; result collect_hybrid.roster_import_results;
 revision uuid; committed jsonb;
begin
 sid:=collect_hybrid.require_roster_caller();
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id;
 if s.id is null or s.actor_id<>auth.uid() or s.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 select * into result from collect_hybrid.roster_import_results where import_id=s.id;
 select id into revision from collect_hybrid.roster_import_revisions where import_id=s.id order by revision_number desc limit 1;
 select response into committed from collect_hybrid.roster_import_commits where import_id=s.id;
 return jsonb_build_object('contract_version',1,'ok',true,'import_id',s.id,
  'state',case when committed is not null then 'committed' else coalesce(result.state,'awaiting_preview') end,
  'expires_at',s.expires_at,'preview',collect_hybrid.roster_revision_receipt(revision),'commit',committed,'error_code',result.error_code);
end $$;


--
-- Name: admin_recover_roster_import_guarded_149(uuid, uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.admin_recover_roster_import_guarded_149(p_upload_request_id uuid, p_pending_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid; s collect_hybrid.roster_import_sources; i collect_hybrid.roster_import_recovery_intents;
 d collect_hybrid.roster_import_editor_drafts; state jsonb; initial uuid; answer jsonb; intent jsonb; draft jsonb; phase text; begin
 sid:=collect_hybrid.require_roster_caller();
 if p_upload_request_id is null then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 select * into s from collect_hybrid.roster_import_sources where request_id=p_upload_request_id for update;
 if s.id is null then
  -- No file bytes or unsent content can be reconstructed from this reference.
  return jsonb_build_object('contract_version',1,'ok',true,'upload_request_id',p_upload_request_id,
   'import_id',null,'source_sha256',null,'state','missing_source','initial_preview',null,'status',null,
   'requested_intent_id',p_pending_request_id,'intent',null,'draft',null);
 end if;
 if s.actor_id<>auth.uid() or s.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 state:=public.admin_get_roster_import(s.id);
 phase:=state->>'state';
 select id into initial from collect_hybrid.roster_import_revisions where import_id=s.id and revision_number=1;
 if p_pending_request_id is not null then
  select * into i from collect_hybrid.roster_import_recovery_intents where request_id=p_pending_request_id;
  if i.request_id is not null then
   if i.import_id<>s.id or i.actor_id<>auth.uid() or i.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
   if i.kind='review' then select collect_hybrid.roster_revision_receipt(id) into answer from collect_hybrid.roster_import_revisions where request_id=i.request_id;
   else select response into answer from collect_hybrid.roster_import_commits where request_id=i.request_id; end if;
   intent:=jsonb_build_object('request_id',i.request_id,'kind',i.kind,'payload_sha256',i.payload_sha256,
    'payload',case when i.expires_at>clock_timestamp() then i.payload else null end,'result',answer,
    'expired',i.expires_at<=clock_timestamp());
  end if;
 end if;
 if s.expires_at<=clock_timestamp() and phase<>'committed' then
  -- Original142 provenance remains intact, but expired recovery must not reopen editor rows.
  phase:='expired'; state:=null; initial:=null; intent:=null;
 else
  select * into d from collect_hybrid.roster_import_editor_drafts where import_id=s.id and expires_at>clock_timestamp();
  if d.import_id is not null then
   draft:=jsonb_build_object('checkpoint_id',d.checkpoint_id,'payload_sha256',d.payload_sha256,'payload',d.payload);
  end if;
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'upload_request_id',s.request_id,'import_id',s.id,
  'source_sha256',s.source_sha256,'state',phase,'initial_preview',collect_hybrid.roster_revision_receipt(initial),'status',state,
  'requested_intent_id',p_pending_request_id,'intent',intent,'draft',draft);
end $$;


--
-- Name: admin_review_roster_import_guarded_149(uuid, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.admin_review_roster_import_guarded_149(p_import_id uuid, p_parent_revision_id uuid, p_rows jsonb, p_reason text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid; s collect_hybrid.roster_import_sources; parent collect_hybrid.roster_import_revisions;
 prior collect_hybrid.roster_import_revisions; preview jsonb; fingerprint text; revision uuid; reason text:=btrim(p_reason);
begin
 sid:=collect_hybrid.require_roster_caller();
 if p_request_id is null or p_parent_revision_id is null or reason is null or length(reason) not between 8 and 500 or reason ~ '[[:cntrl:]]' then
  raise exception 'roster_input_invalid' using errcode='22023'; end if;
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id for update;
 if s.id is null or s.actor_id<>auth.uid() or s.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 preview:=collect_hybrid.roster_preview(p_rows,true);
 fingerprint:=collect_hybrid.roster_digest(jsonb_build_array(s.id,p_parent_revision_id,preview->'normalized_rows',reason,auth.uid(),sid));
 select * into prior from collect_hybrid.roster_import_revisions where request_id=p_request_id;
 if prior.id is not null then
  if prior.input_sha256<>fingerprint then raise exception 'roster_request_conflict' using errcode='55000'; end if;
  return collect_hybrid.roster_revision_receipt(prior.id);
 end if;
 if exists(select 1 from collect_hybrid.roster_import_commits where import_id=s.id) then raise exception 'roster_import_committed' using errcode='55000'; end if;
 if s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 select * into parent from collect_hybrid.roster_import_revisions where import_id=s.id order by revision_number desc limit 1;
 if parent.id is null or parent.id<>p_parent_revision_id then raise exception 'roster_revision_superseded' using errcode='55000'; end if;
 if parent.revision_number>=20 then raise exception 'roster_revision_limit' using errcode='55000'; end if;
 insert into collect_hybrid.roster_import_revisions(import_id,parent_revision_id,extraction_id,revision_number,request_id,
  actor_id,session_id,processing_method,preview,normalized_rows,reviewed_rows_sha256,input_sha256,reason)
 values(s.id,parent.id,parent.extraction_id,parent.revision_number+1,p_request_id,auth.uid(),sid,'human_review',preview,
  preview->'normalized_rows',collect_hybrid.roster_digest(preview->'normalized_rows'),fingerprint,reason) returning id into revision;
 perform public.create_audit_log('roster.import.reviewed','roster_import',s.id,
  jsonb_build_object('revision_id',revision,'parent_revision_id',parent.id,'request_id',p_request_id,'row_count',preview->'row_count','reason',reason));
 return collect_hybrid.roster_revision_receipt(revision);
end $$;


--
-- Name: admin_save_roster_import_draft_guarded_149(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.admin_save_roster_import_draft_guarded_149(p_import_id uuid, p_checkpoint_id uuid, p_previous_checkpoint_id uuid, p_payload text, p_payload_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid; s collect_hybrid.roster_import_sources; d collect_hybrid.roster_import_editor_drafts; v jsonb; latest uuid; begin
 sid:=collect_hybrid.require_roster_caller();
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id for update;
 if s.id is null or s.actor_id<>auth.uid() or s.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 if s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 if p_checkpoint_id is null then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 v:=collect_hybrid.roster_recovery_payload(p_payload,p_payload_sha256,'draft');
 select * into d from collect_hybrid.roster_import_editor_drafts where import_id=s.id for update;
 if d.checkpoint_id=p_checkpoint_id then
  if d.payload<>p_payload or d.payload_sha256<>p_payload_sha256 then raise exception 'roster_request_conflict' using errcode='55000'; end if;
 else
  if d.checkpoint_id is distinct from p_previous_checkpoint_id then raise exception 'roster_draft_superseded' using errcode='55000'; end if;
  if exists(select 1 from collect_hybrid.roster_import_commits where import_id=s.id) then raise exception 'roster_import_committed' using errcode='55000'; end if;
  if d.import_id is null and ((select count(*) from collect_hybrid.roster_import_editor_drafts where actor_id=auth.uid() and expires_at>clock_timestamp())>=40
    or (select count(*) from collect_hybrid.roster_import_editor_drafts where session_id=sid and expires_at>clock_timestamp())>=20) then raise exception 'roster_recovery_limit' using errcode='55000'; end if;
  select id into latest from collect_hybrid.roster_import_revisions where import_id=s.id order by revision_number desc limit 1;
  if latest is null or latest::text<>v->>'parent_revision_id' then raise exception 'roster_revision_superseded' using errcode='55000'; end if;
  insert into collect_hybrid.roster_import_editor_drafts(import_id,checkpoint_id,actor_id,session_id,payload,payload_sha256,expires_at)
   values(s.id,p_checkpoint_id,auth.uid(),sid,p_payload,p_payload_sha256,s.expires_at)
   on conflict(import_id) do update set checkpoint_id=excluded.checkpoint_id,payload=excluded.payload,
    payload_sha256=excluded.payload_sha256,updated_at=clock_timestamp();
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'import_id',s.id,'checkpoint_id',p_checkpoint_id,
  'payload_sha256',p_payload_sha256,'expires_at',s.expires_at);
end $$;


--
-- Name: admin_stage_roster_import_intent_guarded_149(uuid, uuid, text, text, text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.admin_stage_roster_import_intent_guarded_149(p_request_id uuid, p_import_id uuid, p_kind text, p_payload text, p_payload_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid; s collect_hybrid.roster_import_sources; prior collect_hybrid.roster_import_recovery_intents; v jsonb; begin
 sid:=collect_hybrid.require_roster_caller();
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id for update;
 if s.id is null or s.actor_id<>auth.uid() or s.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 if p_request_id is null or p_kind not in ('review','commit') or p_kind is null then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 v:=collect_hybrid.roster_recovery_payload(p_payload,p_payload_sha256,p_kind);
 if v->>'p_request_id' is distinct from p_request_id::text or v->>'p_import_id' is distinct from s.id::text then
  raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 select * into prior from collect_hybrid.roster_import_recovery_intents where request_id=p_request_id;
 if s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 if prior.request_id is not null then
  if prior.actor_id<>auth.uid() or prior.session_id<>sid or prior.import_id<>s.id or prior.kind<>p_kind
   or prior.payload<>p_payload or prior.payload_sha256<>p_payload_sha256 then raise exception 'roster_request_conflict' using errcode='55000'; end if;
 else
  if s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
  if exists(select 1 from collect_hybrid.roster_import_commits where import_id=s.id) then raise exception 'roster_import_committed' using errcode='55000'; end if;
  if (select count(*) from collect_hybrid.roster_import_recovery_intents where import_id=s.id)>=40
   or (select count(*) from collect_hybrid.roster_import_recovery_intents where actor_id=auth.uid() and expires_at>clock_timestamp())>=200
   or (select count(*) from collect_hybrid.roster_import_recovery_intents where session_id=sid and expires_at>clock_timestamp())>=100 then raise exception 'roster_recovery_limit' using errcode='55000'; end if;
  -- Staging is storage only. Frozen142 validates all authority and rows at execution.
  insert into collect_hybrid.roster_import_recovery_intents(request_id,import_id,actor_id,session_id,kind,payload,payload_sha256,expires_at)
   values(p_request_id,s.id,auth.uid(),sid,p_kind,p_payload,p_payload_sha256,s.expires_at);
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'import_id',s.id,'request_id',p_request_id,'kind',p_kind,
  'payload_sha256',p_payload_sha256,'expires_at',s.expires_at);
end $$;


--
-- Name: assert_momo_journal_balanced(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.assert_momo_journal_balanced() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_entry_id uuid;
  entry_amount bigint;
  debit_total bigint;
  credit_total bigint;
  line_count integer;
begin
  if tg_table_name = 'momo_journal_entries' then
    target_entry_id := new.id;
  else
    target_entry_id := new.journal_entry_id;
  end if;
  select entry.amount_rwf into entry_amount
  from collect_hybrid.momo_journal_entries entry
  where entry.id = target_entry_id;
  select
    coalesce(sum(line.amount_rwf) filter (where line.direction = 'debit'), 0),
    coalesce(sum(line.amount_rwf) filter (where line.direction = 'credit'), 0),
    count(*)
  into debit_total, credit_total, line_count
  from collect_hybrid.momo_journal_lines line
  where line.journal_entry_id = target_entry_id;
  if line_count <> 2 or debit_total <> entry_amount or credit_total <> entry_amount then
    raise exception 'MoMo journal entry must contain exactly one balanced debit and credit';
  end if;
  return new;
end;
$$;


--
-- Name: assert_onboarding(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.assert_onboarding() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.assert_admin_permission('collections.moderate');
  perform public.assert_admin_permission('users.read');
  if not coalesce((select enabled from public.feature_flags where key='hybrid_member_onboarding'), false) then
    raise exception 'Hybrid onboarding is disabled pending controlled rollout';
  end if;
end; $$;


--
-- Name: attach_claimed_payment_account(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.attach_claimed_payment_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.member_record_id is not null and new.contributor_user_id is null then
    select claim.user_id into new.contributor_user_id
    from collect_hybrid.member_account_claims claim
    where claim.member_record_id = new.member_record_id
      and claim.user_id is not null;
  end if;
  return new;
end;
$$;


--
-- Name: bank_scheduler_retirement_readback(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.bank_scheduler_retirement_readback() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  canonical_command constant text := $command$select public.run_daily_bank_reconciliation(current_date, 'scheduled daily reconciliation');$command$;
  candidate record;
  launcher record;
  history_count bigint;
  history_hash text;
  nonterminal bigint;
  live_commands bigint;
  cron_zone text := current_setting('cron.timezone', true);
  observed timestamptz := clock_timestamp();
  local_time time;
begin
  if current_user not in ('postgres', 'supabase_admin')
    or not exists (select 1 from pg_catalog.pg_roles where rolname = current_user and (rolsuper or rolbypassrls)) then
    raise exception 'bank_scheduler_owner_required' using errcode = '42501';
  end if;
  if current_setting('transaction_isolation') <> 'serializable' then
    raise exception 'bank_scheduler_serializable_required' using errcode = '25001';
  end if;
  if not pg_catalog.pg_has_role(current_user, 'pg_read_all_stats', 'USAGE')
    and not exists (select 1 from pg_catalog.pg_roles where rolname = current_user and rolsuper) then
    raise exception 'bank_scheduler_stats_visibility_required' using errcode = '42501';
  end if;
  perform pg_catalog.set_config('row_security', 'off', true);
  if (select extversion from pg_catalog.pg_extension where extname = 'pg_cron') is distinct from '1.6.4'
    or current_setting('cron.log_run', true) is distinct from 'on'
    or cron_zone is null or cron_zone not in ('GMT', 'UTC', 'Etc/UTC') then
    raise exception 'bank_scheduler_runtime_review_required' using errcode = '55000';
  end if;
  -- Daily fixed UTC schedule. A five-minute margin excludes launch/catch-up
  -- boundaries. No canonical run can still be recent, queued or executing.
  local_time := (observed at time zone cron_zone)::time;
  if local_time >= time '21:25:00' and local_time <= time '21:35:00' then
    raise exception 'bank_scheduler_schedule_window' using errcode = '55000';
  end if;
  if (select count(*) from cron.job where jobname = 'collect-daily-bank-reconciliation') <> 1 then
    raise exception 'bank_scheduler_identity_review_required' using errcode = '55000';
  end if;
  select * into strict candidate from cron.job where jobname = 'collect-daily-bank-reconciliation';
  if candidate.command is distinct from canonical_command
    or candidate.schedule is distinct from '30 21 * * *'
    or candidate.username is distinct from current_user::text
    or candidate.database is distinct from current_database()
    or candidate.nodename is distinct from 'localhost'
    or candidate.nodeport is distinct from current_setting('port')::integer then
    raise exception 'bank_scheduler_identity_review_required' using errcode = '55000';
  end if;
  if (select count(*) from pg_catalog.pg_stat_activity where backend_type = 'pg_cron launcher') <> 1 then
    raise exception 'bank_scheduler_launcher_review_required' using errcode = '55000';
  end if;
  select pid, backend_start into strict launcher from pg_catalog.pg_stat_activity where backend_type = 'pg_cron launcher';
  select count(*), encode(extensions.digest(coalesce(string_agg(hashes.h, '' order by hashes.h), ''), 'sha256'), 'hex')
    into history_count, history_hash
    from (select encode(extensions.digest(to_jsonb(d)::text, 'sha256'), 'hex') h from cron.job_run_details d where d.jobid = candidate.jobid) hashes;
  select count(*) into nonterminal from cron.job_run_details d where d.jobid = candidate.jobid
    and (d.end_time is null or d.status is null or d.status not in ('succeeded', 'failed'));
  select count(*) into live_commands from pg_catalog.pg_stat_activity a
    where a.pid <> pg_catalog.pg_backend_pid() and a.datname = current_database()
      and a.state is distinct from 'idle' and a.query ~* '^\s*(select|call)\s+(public\.)?run_daily_bank_reconciliation\s*\(';
  if nonterminal <> 0 or live_commands <> 0 or exists (
    select 1 from cron.job_run_details d where d.jobid = candidate.jobid
      and greatest(d.start_time, d.end_time) > observed - interval '5 minutes'
  ) then
    raise exception 'bank_scheduler_drain_required' using errcode = '55000';
  end if;
  return jsonb_build_object('contract_version', 2, 'job_id', candidate.jobid,
    'active', candidate.active, 'job_owner', candidate.username,
    'metadata_sha256', encode(extensions.digest(to_jsonb(candidate)::text, 'sha256'), 'hex'),
    'observed_at', observed, 'observed_by', current_user,
    'cron_timezone', cron_zone, 'log_run', true,
    'launcher_pid', launcher.pid, 'launcher_started_at', launcher.backend_start,
    'history_rows', history_count, 'history_sha256', history_hash,
    'nonterminal_runs', nonterminal, 'live_bank_commands', live_commands);
end;
$_$;


--
-- Name: bind_app_membership(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.bind_app_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare registered_id uuid;
begin
  if new.user_id is not null then
    select id into registered_id from collect_hybrid.member_records where linked_user_id = new.user_id;
    if registered_id is null or (new.member_record_id is not null and new.member_record_id <> registered_id) then
      raise exception 'Membership account and record do not match';
    end if;
    new.member_record_id := registered_id;
  end if;
  return new;
end; $$;


--
-- Name: bind_payment_child_member_record(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.bind_payment_child_member_record() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare expected_member_id uuid;
begin
  select payment.member_record_id into expected_member_id
  from public.payments payment
  where payment.id = new.payment_id;
  if not found then raise exception 'Payment required'; end if;
  if new.member_record_id is not null
     and new.member_record_id is distinct from expected_member_id then
    raise exception 'Payment child member record does not match payment';
  end if;
  new.member_record_id := expected_member_id;
  return new;
end;
$$;


--
-- Name: bind_payment_member_record(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.bind_payment_member_record() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  resolved_member_id uuid;
  resolved_collect_id char(6);
begin
  if new.member_record_id is null and new.contributor_user_id is not null then
    select member.id, member.collect_id
    into resolved_member_id, resolved_collect_id
    from collect_hybrid.member_records member
    where member.linked_user_id = new.contributor_user_id
      and member.lifecycle = 'active';
  elsif new.member_record_id is null and new.contributor_public_id is not null then
    select member.id, member.collect_id
    into resolved_member_id, resolved_collect_id
    from collect_hybrid.member_records member
    where member.collect_id = new.contributor_public_id
      and member.lifecycle = 'active';
  elsif new.member_record_id is not null then
    select member.id, member.collect_id
    into resolved_member_id, resolved_collect_id
    from collect_hybrid.member_records member
    where member.id = new.member_record_id
      and member.lifecycle = 'active';
  end if;

  if new.member_record_id is not null and resolved_member_id is null then
    raise exception 'Active member record required';
  end if;
  if resolved_member_id is not null then
    if new.contributor_user_id is not null
       and not collect_hybrid.member_record_belongs_to_user(
         resolved_member_id, new.contributor_user_id
       ) then
      raise exception 'Payment account and member record do not match';
    end if;
    if new.contributor_public_id is not null
       and new.contributor_public_id <> resolved_collect_id then
      raise exception 'Payment Collect ID and member record do not match';
    end if;
    new.member_record_id := resolved_member_id;
    new.contributor_public_id := coalesce(
      new.contributor_public_id, resolved_collect_id
    );
  end if;
  return new;
end;
$$;


--
-- Name: canonical_momo_number(text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.canonical_momo_number(value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
declare clean text := regexp_replace(btrim(value), '[[:space:]-]', '', 'g');
begin
  if clean ~ '^07[2389][0-9]{7}$' then return '+250' || substr(clean, 2); end if;
  if clean ~ '^\+2507[2389][0-9]{7}$' then return clean; end if;
  raise exception 'Invalid Rwanda MoMo number';
end; $_$;


--
-- Name: claim_verified_current_account(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.claim_verified_current_account() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor uuid := auth.uid();
  verified_phone text;
  phone_hash text;
  identity collect_hybrid.member_momo_identities;
  member collect_hybrid.member_records;
  existing collect_hybrid.member_account_claims;
  updated_payments integer := 0;
  suppressed_jobs integer := 0;
begin
  if actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if not coalesce((
    select flag.enabled from public.feature_flags flag
    where flag.key = 'hybrid_verified_account_claim'
  ), false) then
    raise exception 'Verified offline-member account claiming is disabled';
  end if;
  verified_phone := collect_admin_access.verified_phone(actor);
  if verified_phone is null
     or verified_phone !~ '^\+2507[2389][0-9]{7}$' then
    return jsonb_build_object('ok', true, 'status', 'no_match');
  end if;
  phone_hash := encode(extensions.digest(verified_phone, 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(
    'hybrid-account-claim:' || phone_hash, 0
  ));
  select item.* into identity
  from collect_hybrid.member_momo_identities item
  where item.momo_number = verified_phone
  for update;
  if identity.member_id is null then
    return jsonb_build_object('ok', true, 'status', 'no_match');
  end if;
  select item.* into member
  from collect_hybrid.member_records item
  where item.id = identity.member_id
  for update;
  if member.id is null or member.lifecycle <> 'active' then
    raise exception 'Matching member record requires review';
  end if;
  if member.linked_user_id = actor then
    return jsonb_build_object(
      'ok', true, 'status', 'already_linked', 'collect_id', member.collect_id
    );
  end if;
  if member.linked_user_id is not null then
    raise exception 'Matching member record is linked to another account';
  end if;
  select claim.* into existing
  from collect_hybrid.member_account_claims claim
  where claim.member_record_id = member.id
  for update;
  if existing.user_id = actor
     and existing.identity_revision = identity.revision
     and existing.verified_phone_sha256 = phone_hash then
    return jsonb_build_object(
      'ok', true, 'status', 'already_claimed',
      'member_record_id', member.id, 'collect_id', member.collect_id
    );
  end if;
  if existing.user_id is not null then
    raise exception 'Matching member record is claimed by another account';
  end if;
  if exists (
    select 1 from collect_hybrid.member_account_claims claim
    where claim.user_id = actor and claim.member_record_id <> member.id
  ) then
    raise exception 'Account already claims another member record';
  end if;
  insert into collect_hybrid.member_account_claims(
    member_record_id, user_id, verified_phone_sha256, identity_revision
  ) values (
    member.id, actor, phone_hash, identity.revision
  )
  on conflict (member_record_id) do update
  set user_id = excluded.user_id,
      verified_phone_sha256 = excluded.verified_phone_sha256,
      identity_revision = excluded.identity_revision,
      claim_revision = collect_hybrid.member_account_claims.claim_revision + 1,
      last_claimed_at = clock_timestamp();

  -- Linking identity is not a financial posting. Existing immutable payment,
  -- journal and balance rows stay in place; only their nullable account pointer
  -- is attached so app notifications and own-history privacy work normally.
  update public.payments payment
  set contributor_user_id = actor
  where payment.member_record_id = member.id
    and payment.contributor_user_id is null;
  get diagnostics updated_payments = row_count;

  update collect_hybrid.sms_notification_outbox job
  set state = 'suppressed',
      suppression_reason = 'Member authenticated the app with the exact verified MoMo number',
      claim_token = null,
      claimed_by = null,
      claim_expires_at = null
  where job.member_record_id = member.id
    and job.state in ('queued', 'awaiting_confirmation');
  get diagnostics suppressed_jobs = row_count;

  perform public.create_audit_log(
    'member.offline_account.claimed', 'member_record', member.id,
    jsonb_build_object(
      'collect_id', member.collect_id,
      'identity_revision', identity.revision,
      'verified_phone_sha256', phone_hash,
      'payments_attached', updated_payments,
      'sms_jobs_suppressed', suppressed_jobs
    ),
    actor
  );
  return jsonb_build_object(
    'ok', true, 'status', 'claimed',
    'member_record_id', member.id, 'collect_id', member.collect_id,
    'payments_attached', updated_payments,
    'sms_jobs_suppressed', suppressed_jobs
  );
end;
$_$;


--
-- Name: complete_roster_import_preview_guarded_149(uuid, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.complete_roster_import_preview_guarded_149(p_import_id uuid, p_actor_id uuid, p_session_id uuid, p_candidates jsonb, p_processing_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare s collect_hybrid.roster_import_sources; prior collect_hybrid.roster_import_results; preview jsonb;
 fingerprint text; revision uuid; extraction uuid; method text;
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'roster_service_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(p_actor_id,p_session_id);
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id for update;
 if s.id is null or s.actor_id<>p_actor_id or s.session_id<>p_session_id then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 method:=case when s.ai_consent then 'openai_structured_extraction' else 'deterministic' end;
 if p_processing_metadata is null or jsonb_typeof(p_processing_metadata)<>'object'
  or p_processing_metadata->>'processing_method' is distinct from method
  or not (p_processing_metadata ?& array['processing_method','provider_response_sha256','provider_response_id'])
  or exists(select 1 from jsonb_object_keys(p_processing_metadata) k where k not in ('processing_method','provider_response_sha256','provider_response_id'))
  or (not s.ai_consent and (p_processing_metadata->>'provider_response_sha256' is not null or p_processing_metadata->>'provider_response_id' is not null))
  or (s.ai_consent and (jsonb_typeof(p_processing_metadata->'provider_response_sha256') is distinct from 'string'
    or (p_processing_metadata->>'provider_response_sha256') !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_processing_metadata->'provider_response_id') is distinct from 'string'
    or length(p_processing_metadata->>'provider_response_id') not between 1 and 256
    or (p_processing_metadata->>'provider_response_id') ~ '[[:cntrl:]]')) then
  raise exception 'roster_input_invalid' using errcode='22023'; end if;
 preview:=collect_hybrid.roster_preview(p_candidates,false);
 fingerprint:=collect_hybrid.roster_digest(jsonb_build_array(p_candidates,p_processing_metadata));
 select * into prior from collect_hybrid.roster_import_results where import_id=s.id;
 if prior.import_id is not null then
  if prior.state<>'preview_ready' or prior.input_sha256<>fingerprint then raise exception 'roster_request_conflict' using errcode='55000'; end if;
  return collect_hybrid.roster_revision_receipt(prior.revision_id);
 end if;
 if s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 select id into extraction from collect_hybrid.roster_import_extractions where import_id=s.id;
 insert into collect_hybrid.roster_import_revisions(import_id,extraction_id,revision_number,actor_id,session_id,processing_method,
  preview,normalized_rows,reviewed_rows_sha256,input_sha256)
 values(s.id,extraction,1,p_actor_id,p_session_id,method,preview,preview->'normalized_rows',
  collect_hybrid.roster_digest(preview->'normalized_rows'),fingerprint) returning id into revision;
 insert into collect_hybrid.roster_import_results(import_id,actor_id,session_id,state,revision_id,processing_metadata,input_sha256)
 values(s.id,p_actor_id,p_session_id,'preview_ready',revision,p_processing_metadata,fingerprint);
 return collect_hybrid.roster_revision_receipt(revision);
end $_$;


--
-- Name: create_assisted_group(text, text, uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.create_assisted_group(p_title text, p_reason text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  group_id uuid; clean_title text := btrim(p_title); input_digest text; response jsonb;
  prior collect_hybrid.group_creation_requests;
begin
  perform collect_hybrid.assert_onboarding();
  if p_request_id is null or clean_title is null or char_length(clean_title) not between 3 and 120
    or p_reason is null or char_length(btrim(p_reason)) not between 8 and 500 then
    raise exception 'Invalid group name or audit reason';
  end if;
  input_digest := encode(extensions.digest(jsonb_build_array(clean_title, btrim(p_reason))::text, 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended('hybrid-group-create:' || p_request_id::text, 0));
  select * into prior from collect_hybrid.group_creation_requests where request_id=p_request_id;
  if prior.request_id is not null then
    if prior.actor_id <> auth.uid() or prior.input_hash <> input_digest then raise exception 'Group idempotency key conflict'; end if;
    return prior.result || jsonb_build_object('replay', true);
  end if;
  -- Draft private savings group; no guessed/default payee and no fake owner account.
  insert into public.collections(slug, creator_user_id, title, category, visibility, public_status,
    collection_type, contribution_visibility, allow_anonymous, diaspora_enabled, creation_origin)
  values ('assisted-' || replace(gen_random_uuid()::text, '-', ''), auth.uid(), clean_title,
    'Family / friends', 'private', 'private', 'ikimina', 'members', false, false, 'admin_assisted')
  returning id into group_id;
  insert into public.collection_members(collection_id, user_id, role, status)
  values (group_id, auth.uid(), 'owner', 'active');
  perform public.create_audit_log('collection.assisted.created', 'collection', group_id,
    jsonb_build_object('reason', btrim(p_reason), 'route_ready', false));
  response := jsonb_build_object('ok', true, 'collection_id', group_id, 'visibility', 'private', 'route_ready', false, 'replay', false);
  insert into collect_hybrid.group_creation_requests(request_id, actor_id, input_hash, collection_id, result)
  values (p_request_id, auth.uid(), input_digest, group_id, response);
  return response;
end; $$;


--
-- Name: create_assisted_group_with_share(text, text, uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.create_assisted_group_with_share(p_title text, p_reason text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  result jsonb;
  group_id uuid;
begin
  result := collect_hybrid.create_assisted_group(
    p_title,
    p_reason,
    p_request_id
  );
  group_id := (result->>'collection_id')::uuid;
  insert into public.collection_share_secrets(collection_id, rotated_by)
  values (group_id, auth.uid())
  on conflict (collection_id) do nothing;
  return result || jsonb_build_object('share_code_ready', true);
end;
$$;


--
-- Name: create_roster_import_source_guarded_149(uuid, uuid, uuid, text, text, bigint, text, text, text, text, bigint, boolean, text, jsonb); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.create_roster_import_source_guarded_149(p_actor_id uuid, p_session_id uuid, p_request_id uuid, p_source_kind text, p_original_sha256 text, p_original_size bigint, p_client_filename text, p_declared_mime text, p_detected_type text, p_derived_sha256 text, p_derived_size bigint, p_ai_consent boolean, p_consent_version text, p_ai_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r collect_hybrid.roster_resource_reservations;
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'roster_service_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(p_actor_id,p_session_id);
 if not exists(select 1 from collect_hybrid.roster_import_sources where request_id=p_request_id) then
  select * into r from collect_hybrid.roster_resource_reservations where request_id=p_request_id for update;
  if r.id is null or r.actor_id<>p_actor_id or r.session_id<>p_session_id or r.source_sha256<>p_original_sha256
   or r.source_kind<>p_source_kind or r.source_bytes<>p_original_size or r.derived_sha256 is distinct from p_derived_sha256
   or r.expires_at<=clock_timestamp() or exists(select 1 from collect_hybrid.roster_resource_completions where reservation_id=r.id) then
   raise exception 'roster_resource_unavailable' using errcode='42501'; end if;
  if p_source_kind in ('xlsx','image','pdf') and not exists(select 1 from collect_hybrid.roster_source_verifications where reservation_id=r.id) then
   raise exception 'roster_source_unverified' using errcode='42501'; end if;
 end if;
 return public._create_roster_import_source_v142(p_actor_id,p_session_id,p_request_id,p_source_kind,p_original_sha256,p_original_size,
  p_client_filename,p_declared_mime,p_detected_type,p_derived_sha256,p_derived_size,p_ai_consent,p_consent_version,p_ai_metadata);
end $$;


--
-- Name: enqueue_sms_receipt_from_snapshot(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.enqueue_sms_receipt_from_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  payment public.payments;
  member collect_hybrid.member_records;
  identity collect_hybrid.member_momo_identities;
  policy collect_hybrid.sms_receipt_policies;
  consent collect_hybrid.sms_receipt_member_consents;
  message text;
  reference_value text;
begin
  if new.event_type <> 'receipt' or new.member_record_id is null
     or new.member_balance_after_rwf is null then
    return new;
  end if;
  if not coalesce((
    select flag.enabled from public.feature_flags flag
    where flag.key = 'hybrid_sms_notifications'
  ), false) then
    return new;
  end if;
  select item.* into policy
  from collect_hybrid.sms_receipt_policies item
  where item.collection_id = new.collection_id and item.enabled;
  if policy.collection_id is null then return new; end if;
  select item.* into payment from public.payments item where item.id = new.payment_id;
  select item.* into member
  from collect_hybrid.member_records item
  where item.id = new.member_record_id and item.lifecycle = 'active';
  if payment.id is null or payment.status <> 'posted' or member.id is null then
    return new;
  end if;
  -- App-linked members already use the existing contribution-confirmed push
  -- pipeline. SMS is reserved for account-independent members.
  if member.linked_user_id is not null then return new; end if;
  select item.* into identity
  from collect_hybrid.member_momo_identities item
  where item.member_id = member.id;
  if identity.member_id is null then return new; end if;
  select item.* into consent
  from collect_hybrid.sms_receipt_member_consents item
  where item.member_record_id = member.id and item.enabled;
  if consent.member_record_id is null then return new; end if;
  reference_value := btrim(coalesce(payment.transaction_id, ''));
  if reference_value !~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$' then
    insert into collect_hybrid.sms_notification_outbox(
      payment_id, snapshot_id, collection_id, member_record_id,
      destination_e164, destination_sha256, destination_revision,
      policy_revision, consent_revision, template_key, template_version, amount_rwf,
      member_balance_rwf, group_balance_rwf, reference, state,
      suppression_reason
    ) values (
      payment.id, new.id, new.collection_id, member.id,
      identity.momo_number,
      encode(extensions.digest(identity.momo_number, 'sha256'), 'hex'),
      identity.revision, policy.revision, consent.revision, policy.template_key,
      policy.template_version, payment.amount_rwf,
      new.member_balance_after_rwf, new.group_balance_after_rwf,
      coalesce(nullif(reference_value, ''), 'invalid'), 'suppressed',
      'Provider reference is not safe for the canonical receipt template'
    ) on conflict (payment_id, template_key) do nothing;
    return new;
  end if;
  message := collect_hybrid.render_buri_munsi_receipt(
    payment.amount_rwf, new.member_balance_after_rwf,
    new.group_balance_after_rwf, reference_value
  );
  insert into collect_hybrid.sms_notification_outbox(
    payment_id, snapshot_id, collection_id, member_record_id,
    destination_e164, destination_sha256, destination_revision,
    policy_revision, consent_revision, template_key, template_version, amount_rwf,
    member_balance_rwf, group_balance_rwf, reference,
    message_body, body_sha256
  ) values (
    payment.id, new.id, new.collection_id, member.id,
    identity.momo_number,
    encode(extensions.digest(identity.momo_number, 'sha256'), 'hex'),
    identity.revision, policy.revision, consent.revision, policy.template_key,
    policy.template_version, payment.amount_rwf,
    new.member_balance_after_rwf, new.group_balance_after_rwf,
    reference_value, message,
    encode(extensions.digest(message, 'sha256'), 'hex')
  ) on conflict (payment_id, template_key) do nothing;
  return new;
end;
$_$;


--
-- Name: fail_roster_import_preview_guarded_149(uuid, uuid, uuid, text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.fail_roster_import_preview_guarded_149(p_import_id uuid, p_actor_id uuid, p_session_id uuid, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s collect_hybrid.roster_import_sources; prior collect_hybrid.roster_import_results; replayed boolean:=false;
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'roster_service_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(p_actor_id,p_session_id);
 if p_error_code is null or p_error_code not in ('roster_extraction_failed','roster_extraction_timeout','roster_extraction_refused',
  'roster_extraction_incomplete','roster_provider_response_invalid','roster_provider_response_too_large','roster_preview_invalid','roster_extraction_unavailable') then
  raise exception 'roster_input_invalid' using errcode='22023'; end if;
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id for update;
 if s.id is null or s.actor_id<>p_actor_id or s.session_id<>p_session_id then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 select * into prior from collect_hybrid.roster_import_results where import_id=s.id;
 if prior.import_id is not null then
  if prior.state<>'failed' or prior.error_code<>p_error_code then raise exception 'roster_request_conflict' using errcode='55000'; end if;
  replayed:=true;
 else
  insert into collect_hybrid.roster_import_results(import_id,actor_id,session_id,state,error_code,input_sha256)
  values(s.id,p_actor_id,p_session_id,'failed',p_error_code,collect_hybrid.roster_digest(to_jsonb(p_error_code)));
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'import_id',s.id,'state','failed','error_code',p_error_code,'replayed',replayed);
end $$;


--
-- Name: finish_roster_resources_guarded_149(uuid, uuid, uuid, text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.finish_roster_resources_guarded_149(p_reservation_id uuid, p_actor_id uuid, p_session_id uuid, p_outcome text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r collect_hybrid.roster_resource_reservations; c collect_hybrid.roster_resource_completions;
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'roster_service_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(p_actor_id,p_session_id);
 select * into r from collect_hybrid.roster_resource_reservations where id=p_reservation_id for update;
 if r.id is null or r.actor_id<>p_actor_id or r.session_id<>p_session_id then raise exception 'roster_resource_unavailable' using errcode='42501'; end if;
 if p_outcome is null or p_outcome not in ('preview_ready','failed','ambiguous') then raise exception 'roster_input_invalid' using errcode='22023'; end if;
 select * into c from collect_hybrid.roster_resource_completions where reservation_id=r.id;
 if c.reservation_id is not null then
  if c.outcome<>p_outcome then raise exception 'roster_request_conflict' using errcode='55000'; end if;
 else
  insert into collect_hybrid.roster_resource_completions values(r.id,p_outcome,clock_timestamp());
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'reservation_id',r.id,'outcome',p_outcome,'charged',true);
end $$;


