--
-- Name: guard_roster_recovery_descendant(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.guard_roster_recovery_descendant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare import_uuid uuid; root_uuid uuid; s collect_hybrid.roster_import_sources;
 t collect_hybrid.roster_recovery_transfers; original collect_hybrid.roster_import_sources; begin
 perform public._lock_notification_session_gate();
 perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
 perform collect_hybrid.lock_roster_recovery_budget();
 if tg_table_name='roster_import_sources' then
  select * into t from collect_hybrid.roster_recovery_transfers where to_import_id=new.id;
  if t.request_id is not null then
   select * into original from collect_hybrid.roster_import_sources where id=t.root_import_id;
   if new.request_id<>t.destination_reference_id or new.actor_id<>t.actor_id or new.session_id<>t.to_session_id
    or new.expires_at<>original.expires_at or new.source_sha256<>original.source_sha256
    or new.input_sha256<>original.input_sha256
    or (to_jsonb(new)-array['id','request_id','session_id','created_at']) is distinct from
       (to_jsonb(original)-array['id','request_id','session_id','created_at']) then
    raise exception 'roster_recovery_lineage_invalid' using errcode='55000'; end if;
  end if;
  if new.expires_at<=clock_timestamp() or new.created_at>clock_timestamp()
   or (select count(*) from collect_hybrid.roster_import_sources where actor_id=new.actor_id
    and created_at>clock_timestamp()-interval '24 hours')>=100 then
   raise exception 'roster_recovery_limit' using errcode='55000'; end if;
  return new;
 end if;
 import_uuid:=new.import_id;
 perform collect_hybrid.roster_recovery_leaf(import_uuid,true);
 select * into s from collect_hybrid.roster_import_sources where id=import_uuid;
 if s.id is null or new.actor_id<>s.actor_id or new.session_id<>s.session_id then
  raise exception 'roster_recovery_lineage_invalid' using errcode='55000'; end if;
 root_uuid:=collect_hybrid.roster_recovery_root(import_uuid);
 select * into t from collect_hybrid.roster_recovery_transfers where to_import_id=import_uuid;
 if tg_table_name='roster_import_revisions' then
  if new.processing_method='human_review' and
   (select count(*) from collect_hybrid.roster_import_revisions where processing_method='human_review'
    and collect_hybrid.roster_recovery_root(import_id)=root_uuid)>=19 then
   raise exception 'roster_revision_limit' using errcode='55000'; end if;
  if t.request_id is not null and new.revision_number=1 and
   (new.id<>t.initial_revision_id or new.processing_method='human_review' or new.request_id is not null
    or new.parent_revision_id is not null or new.extraction_id is distinct from
      (select extraction_id from collect_hybrid.roster_import_revisions where import_id=root_uuid and revision_number=1)) then
   raise exception 'roster_recovery_lineage_invalid' using errcode='55000'; end if;
 elsif tg_table_name='roster_import_recovery_intents' then
  if new.expires_at<>s.expires_at or
    (select count(*) from collect_hybrid.roster_import_recovery_intents where collect_hybrid.roster_recovery_root(import_id)=root_uuid)>=40
    or (select count(*) from collect_hybrid.roster_import_recovery_intents where actor_id=new.actor_id and expires_at>clock_timestamp())>=200
    or (select count(*) from collect_hybrid.roster_import_recovery_intents where session_id=new.session_id and expires_at>clock_timestamp())>=100 then
   raise exception 'roster_recovery_limit' using errcode='55000'; end if;
  perform collect_hybrid.roster_recovery_payload(new.payload,new.payload_sha256,new.kind);
 elsif tg_table_name='roster_import_editor_drafts' then
  if new.expires_at<>s.expires_at or (tg_op='INSERT' and
   ((select count(*) from collect_hybrid.roster_import_editor_drafts where actor_id=new.actor_id and expires_at>clock_timestamp())>=40
    or (select count(*) from collect_hybrid.roster_import_editor_drafts where session_id=new.session_id and expires_at>clock_timestamp())>=20)) then
   raise exception 'roster_recovery_limit' using errcode='55000'; end if;
  perform collect_hybrid.roster_recovery_payload(new.payload,new.payload_sha256,'draft');
 elsif tg_table_name='roster_import_extractions' then
  if t.request_id is not null then raise exception 'roster_recovery_lineage_invalid' using errcode='55000'; end if;
 elsif tg_table_name='roster_import_results' and t.request_id is not null then
  if new.state<>'preview_ready' or new.revision_id<>t.initial_revision_id or
    not exists(select 1 from collect_hybrid.roster_import_results where import_id=root_uuid and state='preview_ready'
     and processing_metadata=new.processing_metadata and input_sha256=new.input_sha256) then
   raise exception 'roster_recovery_lineage_invalid' using errcode='55000'; end if;
 elsif tg_table_name='roster_import_commits' then
  if exists(select 1 from collect_hybrid.roster_import_commits c where collect_hybrid.roster_recovery_root(c.import_id)=root_uuid) then
   raise exception 'roster_import_committed' using errcode='55000'; end if;
 end if;
 -- Final insertion expiry includes the financial commit: an exception rolls
 -- back preceding group/member writes atomically, not merely its receipt.
 if s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 return new;
end $$;


--
-- Name: guard_roster_recovery_intent(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.guard_roster_recovery_intent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ begin
 if tg_op='DELETE' and old.expires_at<=clock_timestamp() then return old; end if;
 raise exception 'roster_recovery_intent_immutable' using errcode='55000';
end $$;


--
-- Name: guard_roster_service_recovery(uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.guard_roster_service_recovery(p_import uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 perform collect_hybrid.roster_recovery_leaf(p_import,true);
 if exists(select 1 from collect_hybrid.roster_recovery_transfers where to_import_id=p_import) then
  raise exception 'roster_recovery_provider_replay_forbidden' using errcode='55000'; end if;
end $$;


--
-- Name: lock_roster_recovery_budget(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.lock_roster_recovery_budget() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 perform public._lock_notification_session_gate();
 perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
 update collect_hybrid.roster_recovery_budget set version=version where id;
 if not found then raise exception 'roster_recovery_budget_unavailable' using errcode='55000'; end if;
end $$;


--
-- Name: member_record_belongs_to_user(uuid, uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.member_record_belongs_to_user(p_member_record_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_member_record_id is not null
    and p_user_id is not null
    and exists (
      select 1
      from collect_hybrid.member_records member
      left join collect_hybrid.member_account_claims claim
        on claim.member_record_id = member.id
      where member.id = p_member_record_id
        and member.lifecycle = 'active'
        and (
          member.linked_user_id = p_user_id
          or claim.user_id = p_user_id
        )
    );
$$;


--
-- Name: member_record_has_account(uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.member_record_has_account(p_member_record_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from collect_hybrid.member_records member
    left join collect_hybrid.member_account_claims claim
      on claim.member_record_id = member.id
    where member.id = p_member_record_id
      and member.lifecycle = 'active'
      and coalesce(member.linked_user_id, claim.user_id) is not null
  );
$$;


--
-- Name: normalize_momo_name(text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.normalize_momo_name(value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$ select upper(btrim(regexp_replace(value, '[[:space:]]+', ' ', 'g'))); $$;


--
-- Name: operator_authorized(uuid, text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.operator_authorized(p_operator_user_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(auth.role() = 'service_role'
    and collect_admin_access.permission_allowed(p_permission, p_operator_user_id), false);
$$;


--
-- Name: post_direct_ussd_payment(uuid, uuid, text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.post_direct_ussd_payment(p_event_id uuid, p_assignment_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  event_row public.parsed_payment_events;
  assignment collect_hybrid.member_receiving_assignments;
  route public.collection_receivers;
  member collect_hybrid.member_records;
  raw_row public.raw_payment_sms;
  candidate_payment_id uuid;
begin
  if not coalesce((select flag.enabled from public.feature_flags flag
    where flag.key = 'hybrid_direct_ussd_allocation'), false) then
    raise exception 'Hybrid direct USSD allocation is disabled';
  end if;
  select event.* into event_row
  from public.parsed_payment_events event
  where event.id = p_event_id
  for update;
  if event_row.id is null then raise exception 'Parsed event not found'; end if;
  select payment.id
  into candidate_payment_id
  from public.payments payment
  where payment.parsed_event_id = p_event_id;
  if candidate_payment_id is not null then
    return candidate_payment_id;
  end if;
  if not event_row.is_mobile_money_payment
     or event_row.direction <> 'incoming'
     or event_row.currency <> 'RWF'
     or event_row.amount_rwf is null or event_row.amount_rwf <= 0
     or event_row.transaction_id is null
     or event_row.receiver_phone_hash is null
     or event_row.payer_match_key is null
     or event_row.confidence < 0.90 then
    raise exception 'Direct USSD evidence is incomplete or below the candidate threshold';
  end if;
  select assignment_row.* into assignment
  from collect_hybrid.member_receiving_assignments assignment_row
  where assignment_row.id = p_assignment_id
    and assignment_row.status = 'active'
  for update;
  if assignment.id is null then raise exception 'Active receiving assignment required'; end if;
  select receiver.* into route
  from public.collection_receivers receiver
  where receiver.id = assignment.collection_receiver_id
    and receiver.collection_id = assignment.collection_id
    and receiver.is_active;
  if route.id is null then raise exception 'Assigned receiving route is no longer active'; end if;
  if route.receiver_user_id <> event_row.receiver_user_id
     or route.momo_number_hash <> event_row.receiver_phone_hash
     or route.network <> event_row.network
     or assignment.route_key <> encode(extensions.digest(
       route.receiver_user_id::text || '|' || route.momo_number_hash || '|' || route.network,
       'sha256'
     ), 'hex') then
    raise exception 'Assigned receiving route does not match the receipt';
  end if;
  select member_row.* into member
  from collect_hybrid.member_records member_row
  join collect_hybrid.member_momo_identities identity
    on identity.member_id = member_row.id
   and identity.match_key = event_row.payer_match_key
  join public.collection_members membership
    on membership.member_record_id = member_row.id
   and membership.collection_id = assignment.collection_id
   and membership.status = 'active'
  where member_row.id = assignment.member_record_id
    and member_row.lifecycle = 'active';
  if member.id is null then raise exception 'Assigned payer identity or membership no longer matches'; end if;
  select raw.* into raw_row from public.raw_payment_sms raw where raw.id = event_row.raw_sms_id;
  if raw_row.id is null
     or raw_row.native_action_capability_id is null
     or raw_row.attestation_request_hash is null
     or raw_row.device_attested_at is null then
    raise exception 'Device-attested SMS evidence is required';
  end if;
  if coalesce(raw_row.received_at_device, raw_row.ingested_at) < assignment.starts_at
     or (assignment.ended_at is not null
       and coalesce(raw_row.received_at_device, raw_row.ingested_at) > assignment.ended_at) then
    raise exception 'Receipt falls outside the receiving assignment period';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    event_row.network || ':' || upper(btrim(event_row.transaction_id)), 0
  ));
  if exists (
    select 1 from public.payments payment
    where payment.provider_network = event_row.network
      and upper(btrim(payment.transaction_id)) = upper(btrim(event_row.transaction_id))
  ) then
    select payment.id into candidate_payment_id from public.payments payment
    where payment.provider_network = event_row.network
      and upper(btrim(payment.transaction_id)) = upper(btrim(event_row.transaction_id))
    order by payment.created_at limit 1;
    update public.parsed_payment_events
    set allocation_status = 'ignored',
        review_reason = 'Provider transaction evidence was already consumed'
    where id = p_event_id;
    return candidate_payment_id;
  end if;

  insert into public.payments(
    parsed_event_id, payment_intent_id, collection_id, member_record_id,
    contributor_user_id, contributor_public_id, receiver_user_id,
    receiver_momo_number_hash, amount_rwf, transaction_id, provider_network,
    source, status, anonymity_choice, posted_at
  ) values (
    event_row.id, null, assignment.collection_id, member.id,
    member.linked_user_id, member.collect_id, route.receiver_user_id,
    route.momo_number_hash, event_row.amount_rwf, event_row.transaction_id,
    event_row.network, 'sms_auto', 'review', 'public_id', null
  ) returning id into candidate_payment_id;

  insert into public.payment_allocations(
    payment_id, parsed_event_id, collection_id, payment_intent_id,
    member_record_id, allocated_by, allocation_method, confidence, reason
  ) values (
    candidate_payment_id, event_row.id, assignment.collection_id, null,
    member.id, null, 'auto_native_sms', event_row.confidence,
    p_reason || '; awaiting independent provider confirmation'
  );
  update public.parsed_payment_events
  set collection_id = assignment.collection_id,
      allocation_status = 'needs_review',
      review_reason = 'Matched to one direct receiving assignment; awaiting independent provider confirmation'
  where id = event_row.id;
  perform collect_hybrid.record_momo_exception(
    event_row.id, 'provider_confirmation_pending',
    jsonb_build_object(
      'payment_id', candidate_payment_id,
      'member_record_id', member.id,
      'assignment_id', assignment.id
    )
  );
  perform public.create_audit_log(
    'payment.awaiting_provider_confirmation', 'payment', candidate_payment_id,
    jsonb_build_object(
      'parsed_event_id', event_row.id,
      'member_record_id', member.id,
      'assignment_id', assignment.id,
      'method', 'direct_ussd_assignment',
      'reason', p_reason,
      'ledger_posted', false
    ),
    null
  );
  return candidate_payment_id;
end;
$$;


--
-- Name: post_momo_receipt(uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.post_momo_receipt(p_payment_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payment_row public.payments;
  raw_id uuid;
  journal_id uuid;
  was_inserted boolean := false;
  group_balance bigint;
  member_balance bigint;
begin
  select payment.* into payment_row
  from public.payments payment
  where payment.id = p_payment_id
  for update;
  if payment_row.id is null then raise exception 'Payment not found'; end if;
  if payment_row.status <> 'posted' or payment_row.currency <> 'RWF' then
    raise exception 'Posted RWF payment required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'hybrid-momo-group-balance:' || payment_row.collection_id::text, 0
  ));
  if payment_row.member_record_id is not null then
    perform pg_advisory_xact_lock(hashtextextended(
      'hybrid-momo-member-balance:' || payment_row.collection_id::text || ':' || payment_row.member_record_id::text,
      0
    ));
  end if;
  select event.raw_sms_id into raw_id
  from public.parsed_payment_events event
  where event.id = payment_row.parsed_event_id;

  insert into collect_hybrid.momo_journal_entries(
    payment_id, parsed_event_id, collection_id, member_record_id,
    entry_type, amount_rwf, external_reference
  ) values (
    payment_row.id, payment_row.parsed_event_id, payment_row.collection_id,
    payment_row.member_record_id, 'receipt', payment_row.amount_rwf,
    coalesce(
      nullif(btrim(payment_row.transaction_id), ''),
      case when raw_id is not null then 'raw-sms:' || raw_id::text end,
      'payment:' || payment_row.id::text
    )
  )
  on conflict (payment_id, entry_type) do nothing
  returning id into journal_id;
  was_inserted := journal_id is not null;
  if not was_inserted then
    select entry.id into journal_id
    from collect_hybrid.momo_journal_entries entry
    where entry.payment_id = payment_row.id and entry.entry_type = 'receipt';
    return journal_id;
  end if;

  insert into collect_hybrid.momo_journal_lines(
    journal_entry_id, account_code, direction, amount_rwf
  ) values
    (journal_id, 'momo_receiving_asset:RWF', 'debit', payment_row.amount_rwf),
    (journal_id, 'member_savings_liability:RWF', 'credit', payment_row.amount_rwf);

  insert into collect_hybrid.collection_balances(collection_id, confirmed_rwf)
  values (payment_row.collection_id, payment_row.amount_rwf)
  on conflict (collection_id) do update
  set confirmed_rwf = collect_hybrid.collection_balances.confirmed_rwf + excluded.confirmed_rwf,
      updated_at = now()
  returning confirmed_rwf into group_balance;

  if payment_row.member_record_id is not null then
    insert into collect_hybrid.member_balances(collection_id, member_record_id, confirmed_rwf)
    values (payment_row.collection_id, payment_row.member_record_id, payment_row.amount_rwf)
    on conflict (collection_id, member_record_id) do update
    set confirmed_rwf = collect_hybrid.member_balances.confirmed_rwf + excluded.confirmed_rwf,
        updated_at = now()
    returning confirmed_rwf into member_balance;
  else
    insert into collect_hybrid.momo_reconciliation_exceptions(parsed_event_id, code, details)
    select payment_row.parsed_event_id, 'member_identity_missing',
      jsonb_build_object('payment_id', payment_row.id, 'collection_id', payment_row.collection_id)
    where payment_row.parsed_event_id is not null;
  end if;

  insert into collect_hybrid.momo_balance_snapshots(
    journal_entry_id, payment_id, collection_id, member_record_id,
    event_type, delta_rwf, member_balance_after_rwf, group_balance_after_rwf
  ) values (
    journal_id, payment_row.id, payment_row.collection_id, payment_row.member_record_id,
    'receipt', payment_row.amount_rwf, member_balance, group_balance
  );
  return journal_id;
end;
$$;


--
-- Name: post_momo_receipt_trigger(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.post_momo_receipt_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status = 'posted'
     and new.currency = 'RWF'
     and (tg_op = 'INSERT' or old.status is distinct from 'posted') then
    perform collect_hybrid.post_momo_receipt(new.id);
    update collect_hybrid.momo_reconciliation_exceptions exception
    set status = 'resolved', resolved_at = now()
    where exception.parsed_event_id = new.parsed_event_id
      and exception.status = 'open';
  end if;
  return new;
end;
$$;


--
-- Name: prevent_account_linked_sms_enqueue(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.prevent_account_linked_sms_enqueue() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if collect_hybrid.member_record_has_account(new.member_record_id) then
    return null;
  end if;
  return new;
end;
$$;


--
-- Name: prevent_momo_financial_mutation(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.prevent_momo_financial_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'Posted MoMo journals and snapshots are immutable; post a compensating reversal';
end;
$$;


--
-- Name: protect_sms_attempt_history(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.protect_sms_attempt_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then raise exception 'SMS attempt evidence is retained'; end if;
  if new.outbox_id is distinct from old.outbox_id
     or new.confirmation_id is distinct from old.confirmation_id
     or new.operator_user_id is distinct from old.operator_user_id
     or new.worker_id is distinct from old.worker_id
     or new.claim_token is distinct from old.claim_token
     or new.fence_version is distinct from old.fence_version
     or new.attempt_number is distinct from old.attempt_number
     or new.destination_sha256 is distinct from old.destination_sha256
     or new.destination_revision is distinct from old.destination_revision
     or new.body_sha256 is distinct from old.body_sha256
     or new.send_started_at is distinct from old.send_started_at then
    raise exception 'SMS send-start evidence is immutable';
  end if;
  if old.state <> 'send_started' then
    raise exception 'SMS attempt outcome is final';
  end if;
  return new;
end;
$$;


--
-- Name: protect_sms_outbox_core(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.protect_sms_outbox_core() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'SMS notification evidence is retained';
  end if;
  if new.payment_id is distinct from old.payment_id
     or new.snapshot_id is distinct from old.snapshot_id
     or new.collection_id is distinct from old.collection_id
     or new.member_record_id is distinct from old.member_record_id
     or new.destination_e164 is distinct from old.destination_e164
     or new.destination_sha256 is distinct from old.destination_sha256
     or new.destination_revision is distinct from old.destination_revision
     or new.policy_revision is distinct from old.policy_revision
     or new.consent_revision is distinct from old.consent_revision
     or new.template_key is distinct from old.template_key
     or new.template_version is distinct from old.template_version
     or new.amount_rwf is distinct from old.amount_rwf
     or new.member_balance_rwf is distinct from old.member_balance_rwf
     or new.group_balance_rwf is distinct from old.group_balance_rwf
     or new.reference is distinct from old.reference
     or new.message_body is distinct from old.message_body
     or new.body_sha256 is distinct from old.body_sha256
     or (
       new.suppression_reason is distinct from old.suppression_reason
       and not (
         old.suppression_reason is null
         and new.state = 'suppressed'
         and char_length(btrim(coalesce(new.suppression_reason, ''))) between 8 and 500
       )
     )
     or new.created_at is distinct from old.created_at then
    raise exception 'SMS notification payload and ledger snapshot are immutable';
  end if;
  new.updated_at := clock_timestamp();
  return new;
end;
$$;


--
-- Name: purge_expired_roster_recovery(integer); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.purge_expired_roster_recovery(p_limit integer) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ declare n integer; m integer; begin
 if current_user not in ('postgres','supabase_admin') or p_limit is null or p_limit not between 1 and 1000 then
  raise exception 'roster_recovery_owner_required' using errcode='42501'; end if;
 with removed as (delete from collect_hybrid.roster_import_editor_drafts where import_id in
  (select import_id from collect_hybrid.roster_import_editor_drafts where expires_at<=clock_timestamp() order by expires_at limit p_limit for update skip locked) returning 1)
 select count(*) into n from removed;
 with removed as (delete from collect_hybrid.roster_import_recovery_intents where request_id in
  (select request_id from collect_hybrid.roster_import_recovery_intents where expires_at<=clock_timestamp() order by expires_at limit p_limit for update skip locked) returning 1)
 select count(*) into m from removed;
 return n+m;
end $$;


--
-- Name: record_momo_exception(uuid, text, jsonb); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.record_momo_exception(p_event_id uuid, p_code text, p_details jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update collect_hybrid.momo_reconciliation_exceptions exception
  set details = coalesce(p_details, '{}'::jsonb)
  where exception.parsed_event_id = p_event_id
    and exception.code = p_code
    and exception.status = 'open';
  if not found then
    insert into collect_hybrid.momo_reconciliation_exceptions(parsed_event_id, code, details)
    values (p_event_id, p_code, coalesce(p_details, '{}'::jsonb));
  end if;
end;
$$;


--
-- Name: register_app_member(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.register_app_member() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into collect_hybrid.member_records(id, collect_id, linked_user_id, origin)
  values (new.id, new.public_id, new.id, 'app');
  return new;
end; $$;


--
-- Name: reject_bound_provider_payment(uuid, text, text, text, bigint, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.reject_bound_provider_payment(p_payment_id uuid, p_provider_network text, p_transaction_id text, p_receiver_momo_number_hash text, p_amount_rwf bigint, p_occurred_at timestamp with time zone, p_evidence_sha256 text, p_reason text, p_provider_reference text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  payment_row public.payments;
  prior collect_hybrid.payment_provider_rejections;
  clean_network text := lower(btrim(coalesce(p_provider_network, '')));
  clean_transaction text := upper(btrim(coalesce(p_transaction_id, '')));
  clean_receiver text := lower(btrim(coalesce(p_receiver_momo_number_hash, '')));
  clean_evidence text := nullif(lower(btrim(coalesce(p_evidence_sha256, ''))), '');
  clean_reason text := btrim(coalesce(p_reason, ''));
  clean_reference text := btrim(coalesce(p_provider_reference, ''));
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'Service role required'; end if;
  if p_payment_id is null or char_length(clean_network) not between 2 and 32
     or clean_network !~ '^[a-z0-9_]+$'
     or char_length(clean_transaction) not between 3 and 128
     or clean_receiver !~ '^[0-9a-f]{64}$'
     or p_amount_rwf is null or p_amount_rwf <= 0
     or p_occurred_at is null or not isfinite(p_occurred_at)
     or p_occurred_at > now() + interval '5 minutes'
     or (clean_evidence is not null and clean_evidence !~ '^[0-9a-f]{64}$')
     or char_length(clean_reason) not between 3 and 500
     or char_length(clean_reference) not between 1 and 128 then
    raise exception 'Invalid provider rejection';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('provider-finality-payment:' || p_payment_id::text, 0));
  select payment.* into payment_row from public.payments payment
    where payment.id = p_payment_id for update;
  if payment_row.id is null then raise exception 'Payment not found'; end if;
  if lower(btrim(payment_row.provider_network)) is distinct from clean_network
     or upper(btrim(payment_row.transaction_id)) is distinct from clean_transaction
     or payment_row.receiver_momo_number_hash is distinct from clean_receiver
     or payment_row.amount_rwf is distinct from p_amount_rwf then
    raise exception 'Provider rejection does not match the payment candidate';
  end if;
  if payment_row.status = 'reversed' then
    select rejection.* into prior from collect_hybrid.payment_provider_rejections rejection
      where rejection.payment_id = payment_row.id;
    if prior.payment_id is not null
       and prior.provider_network = clean_network
       and prior.transaction_id = clean_transaction
       and prior.receiver_momo_number_hash = clean_receiver
       and prior.amount_rwf = p_amount_rwf
       and prior.occurred_at = p_occurred_at
       and prior.evidence_sha256 is not distinct from clean_evidence
       and prior.reason = clean_reason and prior.provider_reference = clean_reference then
      return payment_row.id;
    end if;
    raise exception 'Payment was reversed without this provider rejection';
  end if;
  if payment_row.status <> 'review' then raise exception 'Only a review payment can be rejected'; end if;
  if exists(select 1 from public.payment_provider_confirmations where payment_id = payment_row.id)
     or exists(select 1 from public.ledger_entries where payment_id = payment_row.id) then
    raise exception 'Provider rejection cannot compensate posted financial evidence';
  end if;
  insert into collect_hybrid.payment_provider_rejections(
    payment_id, provider_network, transaction_id, receiver_momo_number_hash,
    amount_rwf, occurred_at, evidence_sha256, reason, provider_reference
  ) values (payment_row.id, clean_network, clean_transaction, clean_receiver,
    p_amount_rwf, p_occurred_at, clean_evidence, clean_reason, clean_reference);
  update public.payments set status = 'reversed', posted_at = null where id = payment_row.id;
  update public.parsed_payment_events set allocation_status = 'needs_review',
    review_reason = 'Provider rejected payment candidate: ' || clean_reason
    where id = payment_row.parsed_event_id;
  update public.payment_intents set status = 'cancelled' where id = payment_row.payment_intent_id;
  update collect_hybrid.momo_reconciliation_exceptions set status = 'resolved', resolved_at = now()
    where parsed_event_id = payment_row.parsed_event_id and status = 'open';
  perform public.create_audit_log('payment.provider_rejected', 'payment', payment_row.id,
    jsonb_build_object('reason', clean_reason, 'provider_reference', clean_reference,
      'provider_network', clean_network, 'transaction_id', clean_transaction,
      'occurred_at', p_occurred_at, 'evidence_sha256', clean_evidence, 'ledger_posted', false), null);
  return payment_row.id;
end;
$_$;


--
-- Name: render_buri_munsi_receipt(bigint, bigint, bigint, text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.render_buri_munsi_receipt(p_amount_rwf bigint, p_member_balance_rwf bigint, p_group_balance_rwf bigint, p_reference text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  clean_reference text := btrim(coalesce(p_reference, ''));
begin
  if p_amount_rwf is null or p_amount_rwf <= 0
     or p_member_balance_rwf is null or p_member_balance_rwf < 0
     or p_group_balance_rwf is null or p_group_balance_rwf < 0
     or clean_reference !~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$' then
    raise exception 'Invalid Buri Munsi receipt snapshot';
  end if;
  return 'BuriMunsi: Twakiriye ubwizigame bwawe bwa '
    || to_char(p_amount_rwf, 'FM999,999,999,999,999,990')
    || ' RWF. Balance yawe: '
    || to_char(p_member_balance_rwf, 'FM999,999,999,999,999,990')
    || ' RWF; balance y''itsinda: '
    || to_char(p_group_balance_rwf, 'FM999,999,999,999,999,990')
    || ' RWF. Ref: ' || clean_reference || '.';
end;
$_$;


--
-- Name: require_confirmed_intent_payer(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.require_confirmed_intent_payer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  intent_row public.payment_intents;
  verified_payer_hash text;
  observed_payer_hash text;
begin
  if tg_op = 'UPDATE' then
    if old.payment_intent_id is not null or new.payment_intent_id is not null then
      if new.payment_intent_id is distinct from old.payment_intent_id
         or new.parsed_event_id is distinct from old.parsed_event_id
         or new.contributor_user_id is distinct from old.contributor_user_id
         or new.collection_id is distinct from old.collection_id
         or new.receiver_user_id is distinct from old.receiver_user_id
         or new.receiver_momo_number_hash is distinct from old.receiver_momo_number_hash
         or new.amount_rwf is distinct from old.amount_rwf
         or new.currency is distinct from old.currency
         or new.transaction_id is distinct from old.transaction_id
         or new.provider_network is distinct from old.provider_network
         or new.member_record_id is distinct from old.member_record_id then
        raise exception 'Intent-backed payment attribution is immutable'
          using errcode = '23514';
      end if;
    end if;
  end if;

  if new.status <> 'posted' or new.payment_intent_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if old.status = 'posted' then return new; end if;
  end if;

  select * into intent_row
  from public.payment_intents
  where id = new.payment_intent_id
  for share;
  if intent_row.id is null
     or new.contributor_user_id is distinct from intent_row.contributor_user_id
     or new.collection_id is distinct from intent_row.collection_id then
    raise exception 'Payment intent attribution requires reconciliation'
      using errcode = '23514';
  end if;

  verified_payer_hash :=
    public._authenticated_momo_phone_hash(intent_row.contributor_user_id);
  select event.sender_phone_hash into observed_payer_hash
  from public.parsed_payment_events event
  where event.id = new.parsed_event_id;
  if verified_payer_hash is null
     or intent_row.sender_phone_hash is distinct from verified_payer_hash
     or observed_payer_hash is distinct from verified_payer_hash
     or exists (
       select 1
       from collect_hybrid.payer_identity_reconciliation review
       where review.payment_id = new.id and review.review_status = 'open'
     ) then
    raise exception 'Confirmed payer identity and SMS sender evidence are required'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: require_fresh_roster_auth(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.require_fresh_roster_auth() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid; s auth.sessions; exp_epoch numeric; begin
 sid:=collect_hybrid.require_roster_caller();
 select * into s from auth.sessions where id=sid and user_id=auth.uid() for share;
 if s.id is null or s.created_at<clock_timestamp()-interval '10 minutes' or s.created_at>clock_timestamp()
  or jsonb_typeof(auth.jwt()->'exp') is distinct from 'number' then
  raise exception 'roster_fresh_auth_required' using errcode='42501'; end if;
 begin exp_epoch:=(auth.jwt()->>'exp')::numeric; exception when others then
  raise exception 'roster_fresh_auth_required' using errcode='42501'; end;
 if exp_epoch<=extract(epoch from clock_timestamp()) or exp_epoch>253402300799 then
  raise exception 'roster_fresh_auth_required' using errcode='42501'; end if;
 return sid;
end $$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: roster_import_sources; Type: TABLE; Schema: collect_hybrid; Owner: -
--

CREATE TABLE collect_hybrid.roster_import_sources (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    session_id uuid NOT NULL,
    source_kind text NOT NULL,
    source_sha256 text NOT NULL,
    source_size bigint NOT NULL,
    client_filename text NOT NULL,
    declared_mime text NOT NULL,
    detected_type text NOT NULL,
    derived_sha256 text,
    derived_size bigint,
    ai_consent boolean NOT NULL,
    consent_version text,
    parser_version text DEFAULT 'collect-roster-parser-v1'::text NOT NULL,
    schema_version text DEFAULT 'collect-roster-rows-v1'::text NOT NULL,
    input_sha256 text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    expires_at timestamp with time zone DEFAULT (clock_timestamp() + '24:00:00'::interval) NOT NULL,
    CONSTRAINT roster_import_sources_check CHECK ((isfinite(created_at) AND isfinite(expires_at) AND (expires_at > created_at))),
    CONSTRAINT roster_import_sources_check1 CHECK ((((source_kind = 'xlsx'::text) AND (derived_sha256 ~ '^[a-f0-9]{64}$'::text) AND ((derived_size >= 1) AND (derived_size <= 512000))) OR ((source_kind <> 'xlsx'::text) AND (derived_sha256 IS NULL) AND (derived_size IS NULL)))),
    CONSTRAINT roster_import_sources_input_sha256_check CHECK ((input_sha256 ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT roster_import_sources_source_kind_check CHECK ((source_kind = ANY (ARRAY['text'::text, 'csv'::text, 'txt'::text, 'xlsx'::text, 'pdf'::text, 'image'::text]))),
    CONSTRAINT roster_import_sources_source_sha256_check CHECK ((source_sha256 ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT roster_import_sources_source_size_check CHECK (((source_size >= 1) AND (source_size <= 5242880)))
);


--
-- Name: require_interrupted_roster(uuid, uuid, text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.require_interrupted_roster(p_import uuid, p_destination uuid, p_etag text DEFAULT NULL::text) RETURNS collect_hybrid.roster_import_sources
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare s collect_hybrid.roster_import_sources; new_auth auth.sessions;
 root_source collect_hybrid.roster_import_sources; begin
 select * into s from collect_hybrid.roster_import_sources where id=p_import for update;
 if s.id is null or s.actor_id<>auth.uid() or s.session_id=p_destination then
  raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 perform collect_hybrid.roster_recovery_leaf(s.id,true);
 perform collect_hybrid.require_roster_actor(s.actor_id,p_destination);
 select * into root_source from collect_hybrid.roster_import_sources where id=collect_hybrid.roster_recovery_root(s.id);
 select * into new_auth from auth.sessions where id=p_destination and user_id=s.actor_id;
 if new_auth.id is null or new_auth.created_at<=s.created_at or new_auth.created_at<=root_source.created_at then
  raise exception 'roster_fresh_auth_required' using errcode='42501'; end if;
 if exists(select 1 from collect_hybrid.roster_import_commits where import_id=s.id) then
  raise exception 'roster_import_committed' using errcode='55000'; end if;
 if not exists(select 1 from collect_hybrid.roster_import_revisions where import_id=s.id and revision_number=1) then
  raise exception 'roster_preview_unacknowledged' using errcode='55000'; end if;
 if p_etag is not null and (p_etag !~ '^[a-f0-9]{64}$' or p_etag<>collect_hybrid.roster_interrupted_etag(s.id,p_destination)) then
  raise exception 'roster_draft_superseded' using errcode='55000'; end if;
 return s;
end $_$;


--
-- Name: require_roster_actor(uuid, uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.require_roster_actor(p_actor uuid, p_session uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare enabled_flag boolean; begin
 perform collect_hybrid.require_roster_actor_authority(p_actor,p_session,'platform_owner',array['collections.moderate','users.read']);
 select enabled into enabled_flag from public.feature_flags where key='hybrid_member_onboarding' for share;
 if enabled_flag is distinct from true then raise exception 'roster_feature_disabled' using errcode='55000'; end if;
end $$;


--
-- Name: require_roster_actor_authority(uuid, uuid, text, text[]); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.require_roster_actor_authority(p_actor uuid, p_session uuid, p_role_name text, p_permission_names text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare u auth.users; s auth.sessions; role_uuid uuid; permission text; begin
 perform public._lock_notification_session_gate();
 perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
 if p_actor is null or p_session is null then raise exception 'roster_session_required' using errcode='42501'; end if;
 if p_role_name is null or p_role_name !~ '^[a-z_]+$' or p_permission_names is null
  or cardinality(p_permission_names) not between 1 and 30
  or exists(select 1 from unnest(p_permission_names) n where n is null or n !~ '^[a-z_]+(\.[a-z_]+)+$') then
  raise exception 'roster_actor_unavailable' using errcode='42501'; end if;
 select * into u from auth.users where id=p_actor for share;
 select * into s from auth.sessions where id=p_session and user_id=p_actor for share;
 if u.id is null or s.id is null or s.created_at is null or not isfinite(s.created_at) or s.created_at>clock_timestamp()
  or s.aal::text not in ('aal1','aal2') or s.aal is null
  or (s.not_after is not null and (not isfinite(s.not_after) or s.not_after<=clock_timestamp()))
  or u.deleted_at is not null or u.phone_confirmed_at is null or coalesce(u.is_anonymous,false)
  or (u.banned_until is not null and u.banned_until>clock_timestamp()) then
  raise exception 'roster_actor_unavailable' using errcode='42501'; end if;
 select r.id into role_uuid from collect_admin_access.whatsapp_approvals a
  join public.admin_user_roles ur on ur.user_id=a.user_id and ur.revoked_at is null
  join public.admin_roles r on r.id=ur.role_id and r.name=p_role_name
  where a.user_id=p_actor and a.revoked_at is null and a.phone_e164='+'||ltrim(u.phone,'+')
   and (a.expires_at is null or a.expires_at>clock_timestamp())
   and s.created_at>=a.approved_at and s.created_at>=ur.created_at
  order by ur.created_at for share of a,ur,r;
 if role_uuid is null then raise exception 'roster_actor_unavailable' using errcode='42501'; end if;
 -- Sorted locks avoid opposite permission-row orders between authority users.
 for permission in select distinct n from unnest(p_permission_names) n order by n loop
  perform 1 from public.admin_role_permissions where role_id=role_uuid and permission_name=permission for share;
  if not found then raise exception 'roster_actor_unavailable' using errcode='42501'; end if;
 end loop;
end $_$;


--
-- Name: require_roster_caller(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.require_roster_caller() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare sid text:=auth.jwt()->>'session_id';
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'authenticated' or auth.uid() is null or sid is null
  or sid !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
  raise exception 'roster_session_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(auth.uid(),sid::uuid);
 return sid::uuid;
end $_$;


--
-- Name: reserve_roster_resources_guarded_149(uuid, uuid, uuid, text, text, bigint, text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.reserve_roster_resources_guarded_149(p_actor_id uuid, p_session_id uuid, p_request_id uuid, p_source_sha256 text, p_source_kind text, p_source_bytes bigint, p_derived_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare r collect_hybrid.roster_resource_reservations; policy collect_hybrid.roster_resource_policy;
 fingerprint text; replayed boolean:=false; finished boolean; cost bigint; boundary timestamptz:=clock_timestamp()-interval '24 hours';
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'roster_service_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(p_actor_id,p_session_id);
 if p_request_id is null or p_source_sha256 is null or p_source_sha256 !~ '^[a-f0-9]{64}$' or p_source_kind is null
  or p_source_kind not in ('text','csv','txt','xlsx','pdf','image') or p_source_bytes is null or p_source_bytes not between 1 and
  (case when p_source_kind in ('text','csv','txt') then 512000 else 5242880 end)
  or (p_source_kind='xlsx' and (p_derived_sha256 is null or p_derived_sha256 !~ '^[a-f0-9]{64}$'))
  or (p_source_kind<>'xlsx' and p_derived_sha256 is not null) then raise exception 'roster_input_invalid' using errcode='22023'; end if;
 -- Serialize the entire quota decision, not a SELECT followed by a racy insert.
 -- Same Auth-first order as all roster operations. A singleton policy row makes
 -- concurrent actor/global changes atomic and auditable at policy_version.
 -- Same-value UPDATE creates a row-version fence. Under REPEATABLE READ
 -- an old waiter receives40001 instead of counting quota from a stale snapshot.
 update collect_hybrid.roster_resource_policy set version=version where id returning * into strict policy;
 fingerprint:=collect_hybrid.roster_digest(jsonb_build_array(p_actor_id,p_session_id,p_source_sha256,p_source_kind,p_source_bytes,p_derived_sha256));
 select * into r from collect_hybrid.roster_resource_reservations where request_id=p_request_id;
 if r.id is not null then
  if r.input_sha256<>fingerprint then raise exception 'roster_request_conflict' using errcode='55000'; end if;
  select exists(select 1 from collect_hybrid.roster_resource_completions where reservation_id=r.id) into finished;
  if not finished then
   -- Repair a lost cleanup ACK from an already durable preview/failure; never
   -- reacquire or redispatch an unknown decoder/provider attempt.
   insert into collect_hybrid.roster_resource_completions(reservation_id,outcome)
   select r.id,result.state from collect_hybrid.roster_import_sources source
    join collect_hybrid.roster_import_results result on result.import_id=source.id
    where source.request_id=r.request_id and source.actor_id=r.actor_id and source.session_id=r.session_id;
   select exists(select 1 from collect_hybrid.roster_resource_completions where reservation_id=r.id) into finished;
  end if;
  if not finished then
   raise exception 'roster_resource_in_progress' using errcode='55000';
  end if;
  replayed:=true;
 else
  cost:=case when p_source_kind in ('image','pdf') then policy.ai_attempt_cost_units else 0 end;
  if (select count(*) from collect_hybrid.roster_resource_reservations where actor_id=p_actor_id and reserved_at>boundary)>=policy.actor_daily_requests
   or (select coalesce(sum(source_bytes),0) from collect_hybrid.roster_resource_reservations where actor_id=p_actor_id and reserved_at>boundary)+p_source_bytes>policy.actor_daily_bytes
   or (select coalesce(sum(cost_units),0) from collect_hybrid.roster_resource_reservations where actor_id=p_actor_id and reserved_at>boundary)+cost>policy.actor_daily_cost_units
   or (select count(*) from collect_hybrid.roster_resource_reservations where reserved_at>boundary)>=policy.global_daily_requests
   or (select coalesce(sum(source_bytes),0) from collect_hybrid.roster_resource_reservations where reserved_at>boundary)+p_source_bytes>policy.global_daily_bytes
   or (select coalesce(sum(cost_units),0) from collect_hybrid.roster_resource_reservations where reserved_at>boundary)+cost>policy.global_daily_cost_units then
   raise exception 'roster_resource_limit' using errcode='55000'; end if;
  if (select count(*) from collect_hybrid.roster_resource_reservations a where a.actor_id=p_actor_id and a.expires_at>clock_timestamp()
   and not exists(select 1 from collect_hybrid.roster_resource_completions c where c.reservation_id=a.id and c.outcome<>'ambiguous'))>=policy.actor_active
   or (select count(*) from collect_hybrid.roster_resource_reservations a where a.expires_at>clock_timestamp()
   and not exists(select 1 from collect_hybrid.roster_resource_completions c where c.reservation_id=a.id and c.outcome<>'ambiguous'))>=policy.global_active then
   raise exception 'roster_resource_limit' using errcode='55000'; end if;
  insert into collect_hybrid.roster_resource_reservations(request_id,actor_id,session_id,source_sha256,source_kind,source_bytes,
   derived_sha256,input_sha256,cost_units,policy_version,expires_at)
  values(p_request_id,p_actor_id,p_session_id,p_source_sha256,p_source_kind,p_source_bytes,p_derived_sha256,fingerprint,cost,policy.version,
   clock_timestamp()+interval '180 seconds') returning * into r;
  finished:=false;
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'reservation_id',r.id,'request_id',r.request_id,'actor_id',r.actor_id,
  'session_id',r.session_id,'source_sha256',r.source_sha256,'state',case when finished then 'finished' else 'reserved' end,
  'replayed',replayed,'expires_at',r.expires_at);
end $_$;


--
-- Name: retire_legacy_bank_scheduler(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.retire_legacy_bank_scheduler() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  before_readback jsonb;
  after_readback jsonb;
  receipt collect_hybrid.legacy_bank_scheduler_retirements%rowtype;
  candidate record;
begin
  perform pg_catalog.pg_advisory_xact_lock(143, 20260930);
  before_readback := collect_hybrid.bank_scheduler_retirement_readback();
  -- Row lock through owner API, never cron DML/table locking. A changed row
  -- after the transaction snapshot causes 40001 and rolls the whole call back.
  perform cron.alter_job((before_readback->>'job_id')::bigint, schedule := '30 21 * * *');
  after_readback := collect_hybrid.bank_scheduler_retirement_readback();
  if before_readback->>'metadata_sha256' is distinct from after_readback->>'metadata_sha256'
    or before_readback->>'history_sha256' is distinct from after_readback->>'history_sha256' then
    raise exception 'bank_scheduler_snapshot_changed' using errcode = '40001';
  end if;
  select * into receipt from collect_hybrid.legacy_bank_scheduler_retirements where job_id = (before_readback->>'job_id')::bigint;
  if found then
    if (after_readback->>'active')::boolean is distinct from false
      or receipt.inactive_metadata_sha256 is distinct from after_readback->>'metadata_sha256'
      or receipt.history_rows is distinct from (after_readback->>'history_rows')::bigint
      or receipt.history_sha256 is distinct from after_readback->>'history_sha256'
      or receipt.cron_timezone is distinct from after_readback->>'cron_timezone'
      or receipt.launcher_pid is distinct from (after_readback->>'launcher_pid')::integer
      or receipt.launcher_started_at is distinct from (after_readback->>'launcher_started_at')::timestamptz then
      raise exception 'bank_scheduler_retirement_drift' using errcode = '55000';
    end if;
    return jsonb_build_object('contract_version', 2, 'job_id', receipt.job_id,
      'state', case when exists (select 1 from collect_hybrid.legacy_bank_scheduler_verifications where job_id = receipt.job_id) then 'retired_verified' else 'paused_pending_verification' end,
      'replayed', true, 'active_jobs', 0);
  end if;
  perform cron.alter_job((before_readback->>'job_id')::bigint, active := false);
  after_readback := collect_hybrid.bank_scheduler_retirement_readback();
  if (after_readback->>'active')::boolean is distinct from false
    or before_readback->>'history_sha256' is distinct from after_readback->>'history_sha256' then
    raise exception 'bank_scheduler_retirement_failed' using errcode = '55000';
  end if;
  select * into strict candidate from cron.job where jobid = (after_readback->>'job_id')::bigint;
  insert into collect_hybrid.legacy_bank_scheduler_retirements (
    job_id, job_name, job_owner, database_name, schedule, command_sha256,
    inactive_metadata_sha256, was_active, retirement_version, retirement_reason,
    state, paused_at, paused_by, paused_xid, cron_timezone, launcher_pid,
    launcher_started_at, history_rows, history_sha256
  ) values (candidate.jobid, candidate.jobname, candidate.username, candidate.database,
    candidate.schedule, encode(extensions.digest(candidate.command, 'sha256'), 'hex'),
    after_readback->>'metadata_sha256', (before_readback->>'active')::boolean,
    '20260930110000', 'rwanda_momo_only_bank_scheduler_retired',
    'paused_pending_verification', clock_timestamp(), current_user, pg_catalog.txid_current(),
    after_readback->>'cron_timezone', (after_readback->>'launcher_pid')::integer,
    (after_readback->>'launcher_started_at')::timestamptz,
    (after_readback->>'history_rows')::bigint, after_readback->>'history_sha256');
  return jsonb_build_object('contract_version', 2, 'job_id', candidate.jobid,
    'state', 'paused_pending_verification', 'replayed', false, 'active_jobs', 0);
end;
$$;


--
-- Name: roster_clean_text(text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.roster_clean_text(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
 select btrim(regexp_replace(translate(p_value,
  chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288)||chr(65279),
  repeat(' ',19)), '[[:space:]]+',' ','g'))
$$;


--
-- Name: roster_compact_recovery_draft(jsonb, uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.roster_compact_recovery_draft(p_value jsonb, p_parent uuid) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
 select '{"parent_revision_id":'||to_json(p_parent::text)::text||',"rows":['||
  (select string_agg('{"member_name":'||to_json(x->>'member_name')::text||
    ',"momo_name":'||to_json(x->>'momo_name')::text||
    ',"momo_number":'||to_json(x->>'momo_number')::text||'}',',' order by ord)
   from jsonb_array_elements(p_value->'rows') with ordinality a(x,ord))||
  '],"title":'||to_json(p_value->>'title')::text||',"reason":'||to_json(p_value->>'reason')::text||'}'
$$;


--
-- Name: roster_digest(jsonb); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.roster_digest(p_value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
 select encode(extensions.digest(p_value::text,'sha256'),'hex')
$$;


--
-- Name: roster_interrupted_draft(uuid, uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.roster_interrupted_draft(p_import uuid, p_parent uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare d collect_hybrid.roster_import_editor_drafts; r collect_hybrid.roster_import_revisions; v jsonb; begin
 select * into r from collect_hybrid.roster_import_revisions where import_id=p_import order by revision_number desc limit 1;
 select * into d from collect_hybrid.roster_import_editor_drafts where import_id=p_import and expires_at>statement_timestamp();
 if d.import_id is not null then
  v:=collect_hybrid.roster_recovery_payload(d.payload,d.payload_sha256,'draft');
  if not exists(select 1 from collect_hybrid.roster_import_revisions where import_id=p_import
   and id=(v->>'parent_revision_id')::uuid) then
   raise exception 'roster_recovery_lineage_invalid' using errcode='55000'; end if;
  if v->>'parent_revision_id'=r.id::text then
   if p_parent=r.id then return d.payload; end if; -- Inspection preserves exact acknowledged bytes/SHA.
   return collect_hybrid.roster_compact_recovery_draft(v,p_parent);
  end if;
 else v:=jsonb_build_object('title','','reason',''); end if;
 -- An acknowledged review supersedes stale editor rows. Preserve its saved
 -- title/reason, but never reapply those older rows or their approval state.
 v:=v||jsonb_build_object('rows',(select jsonb_agg(jsonb_build_object('member_name',x->>'member_name',
  'momo_name',x->>'momo_name','momo_number',x->>'momo_number') order by ord)
  from jsonb_array_elements(r.preview->'rows') with ordinality a(x,ord)));
 return collect_hybrid.roster_compact_recovery_draft(v,p_parent);
end $$;


--
-- Name: roster_interrupted_etag(uuid, uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.roster_interrupted_etag(p_import uuid, p_destination_session uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select collect_hybrid.roster_digest(jsonb_build_object('actor',s.actor_id,'destination_session',p_destination_session,
  'root',collect_hybrid.roster_recovery_root(s.id),'leaf',s.id,'input_sha256',s.input_sha256,'expiry',extract(epoch from s.expires_at),
  'revision',(select id from collect_hybrid.roster_import_revisions where import_id=s.id order by revision_number desc limit 1),
  'draft',(select jsonb_build_array(checkpoint_id,payload_sha256) from collect_hybrid.roster_import_editor_drafts where import_id=s.id),
  'intents',(select coalesce(jsonb_agg(jsonb_build_array(request_id,kind,payload_sha256,expires_at) order by request_id),'[]')
    from collect_hybrid.roster_import_recovery_intents where import_id=s.id),
  'commit',(select request_id from collect_hybrid.roster_import_commits where import_id=s.id),
  'transfer',(select request_id from collect_hybrid.roster_recovery_transfers where from_import_id=s.id)))
 from collect_hybrid.roster_import_sources s where s.id=p_import
$$;


--
-- Name: roster_original_proof(uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.roster_original_proof(p_root uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select jsonb_build_object('contract_version',1,'root_import_id',s.id,'upload_request_id',s.request_id,
  'actor_id',s.actor_id,'session_id',s.session_id,'source_kind',s.source_kind,'source_sha256',s.source_sha256,
  'input_sha256',s.input_sha256,'expires_at',to_char(s.expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'source_receipt',collect_hybrid.roster_revision_receipt_v149_frozen(r.id)->'source_receipt',
  'resource_reservation_id',res.id,'decoder_receipt_sha256',v.decoder_receipt_sha256,
  'decoder_build_sha256',v.decoder_build_sha256)::text
 from collect_hybrid.roster_import_sources s
 join collect_hybrid.roster_import_revisions r on r.import_id=s.id and r.revision_number=1
 left join collect_hybrid.roster_resource_reservations res on res.request_id=s.request_id
 left join collect_hybrid.roster_source_verifications v on v.reservation_id=res.id where s.id=p_root
$$;


--
-- Name: roster_preview(jsonb, boolean); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.roster_preview(p_candidates jsonb, p_human boolean) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare raw jsonb; n integer:=0; sr integer; confidence numeric; member_name text; momo_name text;
 phone text; compact text; issues jsonb; seen jsonb:='{}'; rows jsonb:='[]'; normalized jsonb:='[]'; ready integer:=0;
begin
 if p_human is null or p_candidates is null or jsonb_typeof(p_candidates)<>'array'
   or jsonb_array_length(p_candidates) not between 1 and 500 or octet_length(p_candidates::text)>512000 then
  raise exception 'roster_input_invalid' using errcode='22023'; end if;
 for raw in select value from jsonb_array_elements(p_candidates) loop
  n:=n+1;
  if jsonb_typeof(raw)<>'object' or jsonb_typeof(raw->'member_name') is distinct from 'string'
    or jsonb_typeof(raw->'momo_name') is distinct from 'string' or jsonb_typeof(raw->'momo_number') is distinct from 'string'
    or length(raw->>'member_name')>480 or length(raw->>'momo_name')>480 or length(raw->>'momo_number')>32
    or exists(select 1 from jsonb_object_keys(raw) k where k not in ('member_name','momo_name','momo_number','source_row','confidence'))
    or (p_human and (raw ? 'source_row' or raw ? 'confidence')) then
   raise exception 'roster_input_invalid' using errcode='22023'; end if;
  if p_human then sr:=n; confidence:=1;
  else
   if jsonb_typeof(raw->'source_row') is distinct from 'number' or (raw->>'source_row') !~ '^[0-9]+$'
     or (raw->>'source_row')::numeric not between 1 and 2147483647
     or jsonb_typeof(raw->'confidence') is distinct from 'number'
     or (raw->>'confidence')::numeric not between 0 and 1 then
    raise exception 'roster_input_invalid' using errcode='22023'; end if;
   sr:=(raw->>'source_row')::integer; confidence:=(raw->>'confidence')::numeric;
  end if;
  member_name:=collect_hybrid.roster_clean_text(raw->>'member_name');
  momo_name:=collect_hybrid.roster_clean_text(raw->>'momo_name');
  compact:=regexp_replace(collect_hybrid.roster_clean_text(raw->>'momo_number'),'[ ().-]','','g');
  if compact ~ '^250' then compact:='+'||compact; end if;
  phone:=null;
  if compact ~ '^07[2389][0-9]{7}$' or compact ~ '^\+2507[2389][0-9]{7}$' then
   phone:=collect_hybrid.canonical_momo_number(compact); end if;
  issues:='[]';
  if length(member_name) not between 2 and 120 then issues:=issues||jsonb_build_array('Member name must contain 2 to 120 characters'); end if;
  if length(momo_name) not between 2 and 120 then issues:=issues||jsonb_build_array('Registered MoMo name must contain 2 to 120 characters'); end if;
  if (member_name||momo_name) ~ '[[:cntrl:]]' then issues:=issues||jsonb_build_array('Names cannot contain control characters'); end if;
  if member_name ~ '^[=+@-]' or momo_name ~ '^[=+@-]' then issues:=issues||jsonb_build_array('Names cannot begin with spreadsheet formula characters'); end if;
  if phone is null then issues:=issues||jsonb_build_array('Enter a valid full Rwanda MoMo number'); end if;
  if confidence<0.8 then issues:=issues||jsonb_build_array('Extraction confidence is below 80%'); end if;
  if phone is not null then
   if seen ? phone then issues:=issues||jsonb_build_array('MoMo number duplicates source row '||(seen->>phone));
   else seen:=seen||jsonb_build_object(phone,sr); end if;
  end if;
  rows:=rows||jsonb_build_array(jsonb_build_object('source_row',sr,'member_name',member_name,'momo_name',momo_name,
   'momo_number',coalesce(phone,collect_hybrid.roster_clean_text(raw->>'momo_number')),'confidence',confidence,'issues',issues,'ready',jsonb_array_length(issues)=0));
  if jsonb_array_length(issues)=0 then
   ready:=ready+1; normalized:=normalized||jsonb_build_array(jsonb_build_object('member_name',member_name,'momo_name',momo_name,'momo_number',phone)); end if;
 end loop;
 if p_human and ready<>n then raise exception 'roster_rows_invalid' using errcode='22023'; end if;
 return jsonb_build_object('rows',rows,'row_count',n,'ready_count',ready,'error_count',n-ready,'normalized_rows',normalized);
end $_$;


--
-- Name: roster_recovery_leaf(uuid, boolean); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.roster_recovery_leaf(p_import uuid, p_mutation boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s collect_hybrid.roster_import_sources; root_source collect_hybrid.roster_import_sources; begin
 perform public._lock_notification_session_gate();
 perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
 select * into s from collect_hybrid.roster_import_sources where id=p_import;
 if s.id is null then return; end if; -- Frozen entrypoint preserves its missing-source contract.
 if auth.role()='authenticated' and s.actor_id is distinct from auth.uid() then
  raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 if exists(select 1 from collect_hybrid.roster_recovery_transfers where from_import_id=s.id) then
  raise exception 'roster_recovery_transferred' using errcode='55000'; end if;
 select * into root_source from collect_hybrid.roster_import_sources where id=collect_hybrid.roster_recovery_root(s.id);
 if s.id<>root_source.id then
  -- Logout may legitimately delete the issued source session. Immutable
  -- provenance records that issuance; current verified authority authorizes
  -- this branch. The original SID never becomes a credential/dependency.
  if auth.role()='authenticated' then
   perform collect_hybrid.require_roster_actor(root_source.actor_id,(auth.jwt()->>'session_id')::uuid);
  end if;
  if s.actor_id<>root_source.actor_id or s.expires_at<>root_source.expires_at then
   raise exception 'roster_recovery_lineage_invalid' using errcode='55000'; end if;
 end if;
 if p_mutation and s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
end $$;


--
-- Name: roster_recovery_payload(text, text, text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.roster_recovery_payload(p_payload text, p_sha text, p_kind text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare v jsonb; r jsonb; raw_row json; keys text[]; field text; begin
 if p_payload is null or octet_length(p_payload) not between 2 and 512000
  or p_sha is null or p_sha !~ '^[a-f0-9]{64}$'
  or encode(extensions.digest(convert_to(p_payload,'UTF8'),'sha256'),'hex')<>p_sha then
  raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 begin v:=p_payload::jsonb; exception when others then
  raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end;
 if jsonb_typeof(v)<>'object' then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 if (select count(*) from json_object_keys(p_payload::json))<>(select count(*) from jsonb_object_keys(v)) then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(v) k;
 if p_kind='review' then
  if keys is distinct from array['p_import_id','p_parent_revision_id','p_reason','p_request_id','p_rows'] then
   raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 elsif p_kind='commit' then
  if keys is distinct from array['p_collection_id','p_human_affirmed','p_import_id','p_mode','p_reason','p_request_id','p_reviewed_rows_sha256','p_revision_id','p_title'] then
   raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 elsif p_kind='draft' then
  if keys is distinct from array['parent_revision_id','reason','rows','title'] then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 else raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 if p_kind in ('review','commit') then
  foreach field in array (case when p_kind='review' then array['p_import_id','p_request_id','p_parent_revision_id'] else array['p_import_id','p_request_id','p_revision_id'] end) loop
   if jsonb_typeof(v->field) is distinct from 'string' or coalesce(v->>field,'') !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' then
    raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
  end loop;
  if jsonb_typeof(v->'p_reason') is distinct from 'string' or length(btrim(v->>'p_reason')) not between 8 and 500 or (v->>'p_reason') ~ '[[:cntrl:]]' then
   raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 end if;
 if p_kind='commit' then
  if v->'p_human_affirmed' is distinct from 'true'::jsonb or jsonb_typeof(v->'p_mode') is distinct from 'string'
   or v->>'p_mode' not in ('create','existing') or jsonb_typeof(v->'p_reviewed_rows_sha256') is distinct from 'string'
   or coalesce(v->>'p_reviewed_rows_sha256','') !~ '^[a-f0-9]{64}$'
   or (v->>'p_mode'='create' and (v->'p_collection_id' is distinct from 'null'::jsonb
    or jsonb_typeof(v->'p_title') is distinct from 'string' or length(btrim(v->>'p_title')) not between 3 and 120 or (v->>'p_title') ~ '[[:cntrl:]]'))
   or (v->>'p_mode'='existing' and (v->'p_title' is distinct from 'null'::jsonb
    or jsonb_typeof(v->'p_collection_id') is distinct from 'string' or coalesce(v->>'p_collection_id','') !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$')) then
   raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 end if;
 if p_kind in ('draft','review') then
  if jsonb_typeof(case when p_kind='draft' then v->'rows' else v->'p_rows' end) is distinct from 'array'
   or jsonb_array_length(case when p_kind='draft' then v->'rows' else v->'p_rows' end) not between 1 and 500 then
   raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
  for raw_row in select value from json_array_elements(case when p_kind='draft' then p_payload::json->'rows' else p_payload::json->'p_rows' end) loop
   r:=raw_row::jsonb;
   if json_typeof(raw_row) is distinct from 'object' then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
   if (select count(*) from json_object_keys(raw_row))<>(select count(*) from jsonb_object_keys(r)) then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
   if jsonb_typeof(r) is distinct from 'object' then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
   select array_agg(k order by k) into keys from jsonb_object_keys(r) k;
   if keys is distinct from array['member_name','momo_name','momo_number']
    or jsonb_typeof(r->'member_name') is distinct from 'string' or length(r->>'member_name')>480
    or jsonb_typeof(r->'momo_name') is distinct from 'string' or length(r->>'momo_name')>480
    or jsonb_typeof(r->'momo_number') is distinct from 'string' or length(r->>'momo_number')>32 then
    raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
  end loop;
 end if;
 if p_kind='draft' and (jsonb_typeof(v->'parent_revision_id') is distinct from 'string' or jsonb_typeof(v->'title') is distinct from 'string' or length(v->>'title')>120
  or jsonb_typeof(v->'reason') is distinct from 'string' or length(v->>'reason')>500
  or coalesce(v->>'parent_revision_id','') !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$') then
  raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 return v;
end $_$;


--
-- Name: roster_recovery_root(uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.roster_recovery_root(p_import uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select coalesce((select root_import_id from collect_hybrid.roster_recovery_transfers where to_import_id=p_import),p_import)
$$;


--
-- Name: roster_recovery_sha(text); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.roster_recovery_sha(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
 select encode(extensions.digest(convert_to(p_text,'UTF8'),'sha256'),'hex')
$$;


--
-- Name: roster_revision_receipt(uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.roster_revision_receipt(p_revision uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare answer jsonb; t collect_hybrid.roster_recovery_transfers; r collect_hybrid.roster_import_revisions;
 proof text; begin
 select * into r from collect_hybrid.roster_import_revisions where id=p_revision;
 if r.id is null then return null; end if;
 answer:=collect_hybrid.roster_revision_receipt_v149_frozen(r.id);
 if exists(select 1 from collect_hybrid.roster_recovery_transfers where from_import_id=r.import_id) then
  answer:=answer||jsonb_build_object('can_submit',false);
 end if;
 select * into t from collect_hybrid.roster_recovery_transfers where to_import_id=r.import_id;
 if t.request_id is null then return answer; end if;
 proof:=collect_hybrid.roster_original_proof(t.root_import_id);
 if proof is null or collect_hybrid.roster_recovery_sha(proof)<>t.original_proof_sha256 then
  raise exception 'roster_recovery_lineage_invalid' using errcode='55000'; end if;
 return answer||jsonb_build_object('source_receipt',proof::jsonb->'source_receipt',
  'recovery_lineage',jsonb_build_object('contract_version',1,'transfer_request_id',t.request_id,
   'root_import_id',t.root_import_id,'from_import_id',t.from_import_id,'to_import_id',t.to_import_id,
   'actor_id',t.actor_id,'destination_session_id',t.to_session_id,'destination_reference_id',t.destination_reference_id,
   'initial_revision_id',t.initial_revision_id,'original_proof',proof,'original_proof_sha256',t.original_proof_sha256));
end $$;


--
-- Name: roster_revision_receipt_v149_frozen(uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.roster_revision_receipt_v149_frozen(p_revision uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select r.preview||jsonb_build_object('contract_version',1,'ok',true,'import_id',s.id,'source_sha256',s.source_sha256,
  'source_kind',s.source_kind,'revision_id',r.id,'parent_revision_id',r.parent_revision_id,'revision_number',r.revision_number,
  'reviewed_rows_sha256',r.reviewed_rows_sha256,'can_submit',r.processing_method='human_review' and s.expires_at>statement_timestamp()
    and not exists(select 1 from collect_hybrid.roster_import_commits c where c.import_id=s.id)
    and not exists(select 1 from collect_hybrid.roster_import_revisions newer where newer.import_id=s.id and newer.revision_number>r.revision_number),
  'requires_human_review',r.processing_method<>'human_review','processing_method',r.processing_method,'model',e.model,'expires_at',s.expires_at,
  'source_receipt',jsonb_build_object('request_id',s.request_id,'source_size',s.source_size,'client_filename',s.client_filename,
    'declared_mime',s.declared_mime,'detected_type',s.detected_type,'derived_sha256',s.derived_sha256,
    'derived_assurance',case when s.source_kind='xlsx' then 'client_derived_tsv' end,'extraction_id',e.id,
    'ai_consent',s.ai_consent,'consent_version',s.consent_version,'parser_version',s.parser_version,'schema_version',s.schema_version))
 from collect_hybrid.roster_import_revisions r join collect_hybrid.roster_import_sources s on s.id=r.import_id
 left join collect_hybrid.roster_import_extractions e on e.id=r.extraction_id where r.id=p_revision
$$;


--
-- Name: roster_transfer_ack(uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.roster_transfer_ack(p_request uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select jsonb_build_object('contract_version',1,'ok',true,'state','transferred','request_id',t.request_id,
  'from_import_id',t.from_import_id,'root_import_id',t.root_import_id,'to_import_id',t.to_import_id,
  'actor_id',t.actor_id,'destination_session_id',t.to_session_id,'destination_reference_id',t.destination_reference_id,
  'initial_revision_id',t.initial_revision_id,'checkpoint_id',t.checkpoint_id,'draft_sha256',t.draft_sha256,
  'source_etag',t.source_etag,'original_proof_sha256',t.original_proof_sha256,'expires_at',t.expires_at)
 from collect_hybrid.roster_recovery_transfers t where t.request_id=p_request
$$;


--
-- Name: sms_receipt_job_is_current(uuid); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.sms_receipt_job_is_current(p_job_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select true
    from collect_hybrid.sms_notification_outbox job
    join public.payments payment on payment.id = job.payment_id
    join collect_hybrid.member_records member on member.id = job.member_record_id
    join collect_hybrid.member_momo_identities identity
      on identity.member_id = member.id
    join collect_hybrid.sms_receipt_policies policy
      on policy.collection_id = job.collection_id
    join collect_hybrid.sms_receipt_member_consents consent
      on consent.member_record_id = job.member_record_id
    where job.id = p_job_id
      and coalesce((
        select flag.enabled from public.feature_flags flag
        where flag.key = 'hybrid_sms_notifications'
      ), false)
      and payment.status = 'posted'
      and payment.amount_rwf = job.amount_rwf
      and member.lifecycle = 'active'
      and not collect_hybrid.member_record_has_account(member.id)
      and identity.revision = job.destination_revision
      and identity.momo_number = job.destination_e164
      and encode(
        extensions.digest(identity.momo_number, 'sha256'), 'hex'
      ) = job.destination_sha256
      and policy.enabled
      and policy.revision = job.policy_revision
      and policy.template_key = job.template_key
      and policy.template_version = job.template_version
      and consent.enabled
      and consent.revision = job.consent_revision
  ), false);
$$;


--
-- Name: sync_collection_origin(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.sync_collection_origin() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  -- Preserve origin for future calls to the unchanged public-sponsored RPC.
  if new.is_platform_sponsored then new.creation_origin := 'platform_sponsored'; end if;
  return new;
end; $$;


--
-- Name: validate_receiving_assignment(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.validate_receiving_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  route public.collection_receivers;
  expected_key text;
begin
  if tg_op = 'DELETE' then
    raise exception 'Receiving assignments are retained; end the assignment instead';
  end if;

  if tg_op = 'UPDATE' then
    if new.member_record_id is distinct from old.member_record_id
       or new.collection_id is distinct from old.collection_id
       or new.collection_receiver_id is distinct from old.collection_receiver_id
       or new.route_key is distinct from old.route_key
       or new.starts_at is distinct from old.starts_at
       or new.reason is distinct from old.reason
       or new.created_by is distinct from old.created_by
       or new.created_at is distinct from old.created_at
       or old.status <> 'active'
       or new.status <> 'ended'
       or new.ended_at is null then
      raise exception 'Receiving assignment history is immutable';
    end if;
    return new;
  end if;

  select receiver.* into route
  from public.collection_receivers receiver
  where receiver.id = new.collection_receiver_id
    and receiver.collection_id = new.collection_id
    and receiver.is_active;
  if route.id is null then
    raise exception 'Active receiving route for this group required';
  end if;
  if not exists (
    select 1
    from collect_hybrid.member_records member
    join public.collection_members membership
      on membership.member_record_id = member.id
     and membership.collection_id = new.collection_id
     and membership.status = 'active'
    where member.id = new.member_record_id
      and member.lifecycle = 'active'
  ) then
    raise exception 'Active group membership required';
  end if;
  expected_key := encode(
    extensions.digest(
      route.receiver_user_id::text || '|' || route.momo_number_hash || '|' || route.network,
      'sha256'
    ),
    'hex'
  );
  new.route_key := expected_key;
  return new;
end;
$$;


--
-- Name: verify_legacy_bank_scheduler_retirement(); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.verify_legacy_bank_scheduler_retirement() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  receipt collect_hybrid.legacy_bank_scheduler_retirements%rowtype;
  observation collect_hybrid.legacy_bank_scheduler_observations%rowtype;
  final_receipt collect_hybrid.legacy_bank_scheduler_verifications%rowtype;
  readback jsonb;
  readback_hash text;
  elapsed numeric;
begin
  perform pg_catalog.pg_advisory_xact_lock(143, 20260930);
  readback := collect_hybrid.bank_scheduler_retirement_readback();
  perform cron.alter_job((readback->>'job_id')::bigint, schedule := '30 21 * * *');
  readback := collect_hybrid.bank_scheduler_retirement_readback();
  select * into receipt from collect_hybrid.legacy_bank_scheduler_retirements where job_id = (readback->>'job_id')::bigint;
  if not found then raise exception 'bank_scheduler_pause_receipt_required' using errcode = '55000'; end if;
  if receipt.paused_xid = pg_catalog.txid_current() then
    raise exception 'bank_scheduler_postcommit_transaction_required' using errcode = '25001';
  end if;
  if (readback->>'active')::boolean is distinct from false
    or receipt.inactive_metadata_sha256 is distinct from readback->>'metadata_sha256'
    or receipt.history_rows is distinct from (readback->>'history_rows')::bigint
    or receipt.history_sha256 is distinct from readback->>'history_sha256'
    or receipt.cron_timezone is distinct from readback->>'cron_timezone'
    or receipt.launcher_pid is distinct from (readback->>'launcher_pid')::integer
    or receipt.launcher_started_at is distinct from (readback->>'launcher_started_at')::timestamptz then
    raise exception 'bank_scheduler_retirement_drift' using errcode = '55000';
  end if;
  select * into final_receipt from collect_hybrid.legacy_bank_scheduler_verifications where job_id = receipt.job_id;
  if found then
    return jsonb_build_object('contract_version', 2, 'job_id', receipt.job_id,
      'state', 'retired_verified', 'replayed', true, 'active_jobs', 0,
      'verification', to_jsonb(final_receipt));
  end if;
  readback_hash := encode(extensions.digest(readback::text, 'sha256'), 'hex');
  select * into observation from collect_hybrid.legacy_bank_scheduler_observations where job_id = receipt.job_id;
  if not found then
    insert into collect_hybrid.legacy_bank_scheduler_observations
      values (receipt.job_id, (readback->>'observed_at')::timestamptz, current_user, pg_catalog.txid_current(), readback_hash);
    return jsonb_build_object('contract_version', 2, 'job_id', receipt.job_id,
      'state', 'awaiting_observation_interval', 'minimum_seconds', 30,
      'readback', readback, 'readback_sha256', readback_hash);
  end if;
  if observation.observation_xid = pg_catalog.txid_current() then
    raise exception 'bank_scheduler_postcommit_transaction_required' using errcode = '25001';
  end if;
  elapsed := extract(epoch from (readback->>'observed_at')::timestamptz - observation.observed_at);
  if elapsed < 30 then raise exception 'bank_scheduler_observation_interval_required' using errcode = '55000'; end if;
  insert into collect_hybrid.legacy_bank_scheduler_verifications
    values (receipt.job_id, 'retired_verified', (readback->>'observed_at')::timestamptz,
      current_user, pg_catalog.txid_current(), readback_hash, observation.readback_sha256, elapsed);
  select * into strict final_receipt from collect_hybrid.legacy_bank_scheduler_verifications where job_id = receipt.job_id;
  return jsonb_build_object('contract_version', 2, 'job_id', receipt.job_id,
    'state', 'retired_verified', 'replayed', false, 'active_jobs', 0,
    'readback', readback, 'verification', to_jsonb(final_receipt));
end;
$$;


--
-- Name: verify_roster_source_integrity_guarded_149(uuid, uuid, uuid, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: collect_hybrid; Owner: -
--

CREATE FUNCTION collect_hybrid.verify_roster_source_integrity_guarded_149(p_reservation_id uuid, p_actor_id uuid, p_session_id uuid, p_decoder_receipt_sha256 text, p_decoder_build_sha256 text, p_policy_version text, p_toolchain jsonb, p_summary jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare r collect_hybrid.roster_resource_reservations; v collect_hybrid.roster_source_verifications;
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'roster_service_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(p_actor_id,p_session_id);
 select * into r from collect_hybrid.roster_resource_reservations where id=p_reservation_id for update;
 if r.id is null or r.actor_id<>p_actor_id or r.session_id<>p_session_id or r.source_kind not in ('xlsx','image','pdf') then
  raise exception 'roster_resource_unavailable' using errcode='42501'; end if;
 if p_decoder_receipt_sha256 is null or p_decoder_receipt_sha256 !~ '^[a-f0-9]{64}$'
  or p_decoder_build_sha256 is null or p_decoder_build_sha256 !~ '^[a-f0-9]{64}$'
  or p_policy_version is distinct from 'collect-roster-decoder-v1' or p_toolchain is distinct from
   '{"python":"3.12","pillow":"12.0.0","pypdfium2":"5.2.0","pypdf":"6.7.0","openpyxl":"3.1.5","defusedxml":"0.7.1"}'::jsonb
  or p_summary is null or jsonb_typeof(p_summary)<>'object' or not (p_summary ?& array['frames','pages','pixels','expanded_bytes'])
  or (select count(*) from jsonb_object_keys(p_summary))<>4
  or exists(select 1 from jsonb_each(p_summary) where jsonb_typeof(value)<>'number' or value::text !~ '^[0-9]+$'
    or value::text::numeric>160000000)
  or (p_summary->>'frames')::numeric>20 or (p_summary->>'pages')::numeric>20 or (p_summary->>'pixels')::numeric>40000000
  or (r.source_kind='image' and ((p_summary->>'frames')::numeric<1 or (p_summary->>'pages')::numeric<>0 or (p_summary->>'pixels')::numeric<1))
  or (r.source_kind='pdf' and ((p_summary->>'pages')::numeric<1 or (p_summary->>'frames')::numeric<>0 or (p_summary->>'pixels')::numeric<1))
  or (r.source_kind='xlsx' and ((p_summary->>'frames')::numeric<>0 or (p_summary->>'pages')::numeric<>0 or (p_summary->>'pixels')::numeric<>0
    or (p_summary->>'expanded_bytes')::numeric>8388608)) then raise exception 'roster_input_invalid' using errcode='22023'; end if;
 select * into v from collect_hybrid.roster_source_verifications where reservation_id=r.id;
 if v.reservation_id is not null then
  if v.decoder_receipt_sha256<>p_decoder_receipt_sha256 or v.decoder_build_sha256<>p_decoder_build_sha256 or v.toolchain<>p_toolchain or v.summary<>p_summary then
   raise exception 'roster_request_conflict' using errcode='55000'; end if;
 else
  if r.expires_at<=clock_timestamp() or exists(select 1 from collect_hybrid.roster_resource_completions where reservation_id=r.id) then
   raise exception 'roster_resource_expired' using errcode='55000'; end if;
  insert into collect_hybrid.roster_source_verifications values(r.id,r.source_sha256,r.derived_sha256,p_decoder_receipt_sha256,p_decoder_build_sha256,
   p_policy_version,p_toolchain,p_summary,clock_timestamp());
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'reservation_id',r.id,'source_sha256',r.source_sha256,
  'derived_sha256',r.derived_sha256,'decoder_receipt_sha256',p_decoder_receipt_sha256,'verified',true);
end $_$;


--
-- Name: add_owned_group_admin(uuid, text); Type: FUNCTION; Schema: collect_member_actions; Owner: -
--

CREATE FUNCTION collect_member_actions.add_owned_group_admin(p_collection uuid, p_public_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor uuid := auth.uid();
  group_row public.collections%rowtype;
  target_user uuid;
  clean_id text := btrim(coalesce(p_public_id, ''));
begin
  if actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  -- Share the owner-control lock: queued requests re-check current authority
  -- after a concurrent ownership transfer or archive, rather than trusting it.
  select * into group_row from public.collections where id = p_collection for update;
  if group_row.id is null or group_row.creator_user_id is distinct from actor
     or group_row.is_platform_sponsored
     or group_row.public_status not in ('private', 'archived') then
    raise exception 'Only the current owner can add a private group admin' using errcode = '42501';
  end if;
  if group_row.archived_at is not null or group_row.public_status = 'archived' then
    raise exception 'Archived groups cannot add admins' using errcode = '22023';
  end if;
  if clean_id !~ '^[0-9]{6}$' then
    raise exception 'Enter a 6 digit Collect ID.' using errcode = '22023';
  end if;
  -- Resolve the ID only within this group's active membership, never expose
  -- global account existence, phone numbers or names through this endpoint.
  select p.id into target_user from public.profiles p
  where p.public_id = clean_id and p.id <> actor
    and exists(select 1 from public.collection_members m
      where m.collection_id = p_collection and m.user_id = p.id and m.status = 'active');
  if target_user is null then
    raise exception 'Choose another active group member.' using errcode = '22023';
  end if;
  -- Lock and re-check membership too; a removed/left member must not be revived.
  perform 1 from public.collection_members
    where collection_id = p_collection and user_id = target_user for update;
  if not exists(select 1 from public.collection_members where collection_id = p_collection
    and user_id = target_user and status = 'active') then
    raise exception 'Choose another active group member.' using errcode = '22023';
  end if;
  if not exists(select 1 from public.collection_members where collection_id = p_collection
    and user_id = target_user and role = 'admin' and status = 'active') then
    insert into public.collection_members(collection_id, user_id, role, status)
    values(p_collection, target_user, 'admin', 'active')
    on conflict(collection_id, user_id, role) do update set status = 'active';
    insert into public.audit_logs(actor_user_id, action, entity_type, entity_id, metadata)
    values(actor, 'collection.admin_added', 'collection', p_collection,
      jsonb_build_object('member_public_id', clean_id));
  end if;
  -- Lost-response retries return the same minimal, verifiable result and do
  -- not create a second role or audit event. No ownership/payment/Admin writes.
  return jsonb_build_object('collection_id', p_collection, 'public_id', clean_id,
    'role', 'admin', 'status', 'active');
end;
$_$;


--
-- Name: archive_owned_group(uuid); Type: FUNCTION; Schema: collect_member_actions; Owner: -
--

CREATE FUNCTION collect_member_actions.archive_owned_group(p_collection uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor uuid := auth.uid();
  group_row public.collections%rowtype;
begin
  if actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  select * into group_row from public.collections where id = p_collection for update;
  if group_row.id is null or group_row.creator_user_id is distinct from actor
     or group_row.is_platform_sponsored
     or group_row.public_status not in ('private', 'archived') then
    raise exception 'Only the current owner can archive a private group' using errcode = '42501';
  end if;
  -- A lost response can be retried by the same owner without a second event.
  if group_row.archived_at is not null then return; end if;
  update public.collections
  set visibility = 'archived', public_status = 'archived', archived_at = now(), updated_at = now()
  where id = p_collection;
  insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata)
  values(actor,'collection.archived','collection',p_collection,
    jsonb_build_object('previous_status',group_row.public_status::text));
end;
$$;


--
-- Name: group_roster(uuid); Type: FUNCTION; Schema: collect_member_actions; Owner: -
--

CREATE FUNCTION collect_member_actions.group_roster(p_collection_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor uuid := auth.uid();
  group_row public.collections%rowtype;
  result jsonb;
begin
  if actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  select * into group_row
  from public.collections where id = p_collection_id;
  -- Directory visibility and platform authority do not confer membership.
  -- Retain verified linked/claimed feature-phone membership through the
  -- existing lifecycle-aware ownership predicate.
  if group_row.id is null or not (
    group_row.creator_user_id = actor or exists (
      select 1 from public.collection_members membership
      where membership.collection_id = p_collection_id
        and membership.status = 'active'
        and (
          membership.user_id = actor
          or collect_hybrid.member_record_belongs_to_user(
            membership.member_record_id, actor
          )
        )
    )
  ) then
    raise exception 'Join this group to view members' using errcode = '42501';
  end if;

  with candidates as (
    select
      coalesce(
        membership.member_record_id::text,
        'user:' || membership.user_id::text
      ) as identity_key,
      membership.member_record_id,
      coalesce(
        membership.user_id, member.linked_user_id, claim.user_id
      ) as account_user_id,
      coalesce(member.collect_id::text, profile.public_id::text) as public_id,
      case when coalesce(
          membership.user_id, member.linked_user_id, claim.user_id
        ) = group_row.creator_user_id then 'owner'
        when membership.role = 'owner' then 'admin'
        else membership.role::text end as role,
      membership.status::text as status,
      membership.created_at as joined_at
    from public.collection_members membership
    left join collect_hybrid.member_records member
      on member.id = membership.member_record_id
    left join collect_hybrid.member_account_claims claim
      on claim.member_record_id = member.id and claim.user_id is not null
    left join public.profiles profile
      on profile.id = coalesce(
        membership.user_id, member.linked_user_id, claim.user_id
      )
    where membership.collection_id = p_collection_id
    union all
    select
      coalesce(member.id::text, 'user:' || group_row.creator_user_id::text),
      member.id,
      group_row.creator_user_id,
      coalesce(member.collect_id::text, profile.public_id::text),
      'owner', 'active', group_row.created_at
    from public.profiles profile
    left join collect_hybrid.member_records member
      on member.linked_user_id = profile.id
    where profile.id = group_row.creator_user_id
      and not exists (
        select 1 from public.collection_members membership
        where membership.collection_id = p_collection_id
          and membership.user_id = group_row.creator_user_id
      )
  ), ranked as (
    select *,
      min(joined_at) over (partition by identity_key) as first_joined_at,
      row_number() over (
        partition by identity_key
        order by
          case status when 'active' then 0 when 'invited' then 1 else 2 end,
          case role when 'owner' then 0 when 'admin' then 1
            when 'receiver' then 2 when 'member' then 3
            when 'contributor' then 4 else 5 end,
          joined_at, status
      ) as priority
    from candidates
    where public_id is not null
  ), roster as (
    select identity_key, member_record_id, account_user_id, public_id,
      role, status, first_joined_at as joined_at
    from ranked where priority = 1
  ), visible_amounts as (
    select roster.identity_key, payment.currency,
      payment.amount_rwf as amount_minor
    from public.payments payment
    join roster on (
      payment.member_record_id = roster.member_record_id
      or (
        payment.member_record_id is null
        and payment.contributor_user_id = roster.account_user_id
      )
    )
    where payment.collection_id = p_collection_id
      and payment.status = 'posted'
      and (
        roster.account_user_id = actor
        or (
          payment.anonymity_choice = 'public_id'
          and payment.contributor_public_id::text = roster.public_id
        )
      )
    union all
    select roster.identity_key, transaction.currency,
      transaction.amount_minor
    from public.bank_transactions transaction
    join public.bank_transaction_allocations allocation
      on allocation.bank_transaction_id = transaction.id
    join roster on roster.account_user_id = allocation.contributor_user_id
    where allocation.collection_id = p_collection_id
      and transaction.status = 'reconciled'
      and roster.account_user_id = actor
  ), totals as (
    select identity_key, currency, sum(amount_minor)::bigint as amount_minor
    from visible_amounts group by identity_key, currency
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'public_id', roster.public_id,
    'role', roster.role,
    'status', roster.status,
    'joined_at', roster.joined_at,
    'account_state', case when roster.account_user_id is null
      then 'feature_phone' else 'app' end,
    'amount_scope', case when roster.account_user_id = actor then 'own'
      when exists (
        select 1 from totals
        where totals.identity_key = roster.identity_key
      ) then 'shared' else 'hidden' end,
    'contributions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'currency', totals.currency,
        'amount_minor', totals.amount_minor
      ) order by totals.currency)
      from totals where totals.identity_key = roster.identity_key
    ), '[]'::jsonb)
  ) order by roster.public_id), '[]'::jsonb)
  into result from roster;
  return result;
end;
$$;


--
-- Name: history_page(uuid, text, text, jsonb, integer); Type: FUNCTION; Schema: collect_member_actions; Owner: -
--

CREATE FUNCTION collect_member_actions.history_page(p_collection_id uuid, p_query text, p_sort text, p_cursor jsonb, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor uuid := auth.uid();
  query_text text := lower(btrim(coalesce(p_query, '')));
  anchor_id uuid;
  anchor_at timestamptz;
  anchor_amount bigint;
  total_count bigint;
  total_amount bigint;
  own_amount bigint;
  own_collection_ids jsonb;
  revision text;
  page_items jsonb;
  has_more boolean;
  last_id text;
  keyset_predicate text;
  source_order text;
  window_order text;
begin
  if actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if p_limit is null or p_limit not between 1 and 100 or length(query_text) > 80
     or p_sort is null or p_sort not in ('newest', 'oldest', 'highest', 'lowest') then
    raise exception 'Invalid history query' using errcode = '22023';
  end if;
  if p_cursor is not null then
    if jsonb_typeof(p_cursor) <> 'object'
       or coalesce(p_cursor->>'revision', '') !~ '^[a-f0-9]{32}$'
       or coalesce(p_cursor->>'after', '') !~
         '^momo:[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then
      raise exception 'Invalid history cursor' using errcode = '22023';
    end if;
    anchor_id := substring(p_cursor->>'after' from 6)::uuid;
  end if;

  with readable as materialized (
    select collection.id from public.collections collection
    where public.user_can_read_collection(collection.id, actor)
  ), scoped as (
    select payment.id, payment.collection_id, payment.amount_rwf,
      payment.posted_at,
      coalesce(payment.contributor_user_id = actor, false) as own,
      case when payment.contributor_user_id = actor
        then payment.transaction_id end as transaction_id,
      case when payment.contributor_user_id = actor then 'You'
        when payment.anonymity_choice = 'public_id'
          and payment.contributor_public_id is not null
          then 'Collect ID ' || payment.contributor_public_id
        else 'Anonymous supporter' end as supporter_label,
      collection.title,
      payment.collection_id in (select id from readable) as can_read_collection
    from public.payments payment
    join public.collections collection on collection.id = payment.collection_id
    where payment.status = 'posted' and payment.currency = 'RWF'
      and (p_collection_id is null or payment.collection_id = p_collection_id)
      and (payment.contributor_user_id = actor
        or payment.collection_id in (select id from readable))
  ), matched as (
    select * from scoped
    where query_text = ''
      or strpos(lower(supporter_label), query_text) > 0
      or strpos(lower(coalesce(transaction_id, '')), query_text) > 0
      or (can_read_collection and strpos(lower(title), query_text) > 0)
  )
  select count(*)::bigint,
    coalesce(sum(amount_rwf), 0)::bigint,
    coalesce(sum(amount_rwf) filter (where own), 0)::bigint,
    coalesce(to_jsonb(array_agg(distinct collection_id::text
      order by collection_id::text) filter (where own)), '[]'::jsonb),
    -- A 256-bit XOR of per-row SHA-256 digests has constant aggregate space.
    -- Row identity is included, so a changed/missing row changes the revision
    -- with overwhelming probability; count also distinguishes cardinality.
    md5(row(actor, p_collection_id, query_text, p_sort, count(*),
      coalesce(bit_xor(('x' || encode(extensions.digest(
        row(id, collection_id, amount_rwf, posted_at, own,
          transaction_id, supporter_label)::text, 'sha256'), 'hex'))::bit(256)),
        repeat('0', 256)::bit(256)))::text)
  into total_count, total_amount, own_amount, own_collection_ids, revision
  from matched;

  if p_cursor is not null and revision <> p_cursor->>'revision' then
    raise exception 'History changed. Refresh before loading more.'
      using errcode = 'P0001';
  end if;
  if anchor_id is not null then
    with readable as materialized (
      select collection.id from public.collections collection
      where public.user_can_read_collection(collection.id, actor)
    )
    select payment.posted_at, payment.amount_rwf
    into anchor_at, anchor_amount
    from public.payments payment
    join public.collections collection on collection.id = payment.collection_id
    where payment.id = anchor_id
      and payment.status = 'posted' and payment.currency = 'RWF'
      and (p_collection_id is null or payment.collection_id = p_collection_id)
      and (payment.contributor_user_id = actor
        or payment.collection_id in (select id from readable))
      and (query_text = ''
        or strpos(lower(case when payment.contributor_user_id = actor then 'You'
          when payment.anonymity_choice = 'public_id'
            and payment.contributor_public_id is not null
            then 'Collect ID ' || payment.contributor_public_id
          else 'Anonymous supporter' end), query_text) > 0
        or (payment.contributor_user_id = actor
          and strpos(lower(coalesce(payment.transaction_id, '')), query_text) > 0)
        or (payment.collection_id in (select id from readable)
          and strpos(lower(collection.title), query_text) > 0));
    if not found then
      raise exception 'History changed. Refresh before loading more.'
        using errcode = 'P0001';
    end if;
  end if;

  -- These fragments are selected solely from the four validated enum values.
  -- All user data remains in EXECUTE USING parameters, never in SQL text.
  if p_sort = 'newest' then
    keyset_predicate := '($4::uuid is null or payment.posted_at < $5 or '
      || '(payment.posted_at = $5 and payment.id > $4))';
    source_order := 'payment.posted_at desc, payment.id';
    window_order := 'posted_at desc, id';
  elsif p_sort = 'oldest' then
    keyset_predicate := '($4::uuid is null or payment.posted_at > $5 or '
      || '(payment.posted_at = $5 and payment.id > $4))';
    source_order := 'payment.posted_at, payment.id';
    window_order := 'posted_at, id';
  elsif p_sort = 'highest' then
    keyset_predicate := '($4::uuid is null or payment.amount_rwf < $6 or '
      || '(payment.amount_rwf = $6 and (payment.posted_at < $5 or '
      || '(payment.posted_at = $5 and payment.id > $4))))';
    source_order := 'payment.amount_rwf desc, payment.posted_at desc, payment.id';
    window_order := 'amount_rwf desc, posted_at desc, id';
  else
    keyset_predicate := '($4::uuid is null or payment.amount_rwf > $6 or '
      || '(payment.amount_rwf = $6 and (payment.posted_at < $5 or '
      || '(payment.posted_at = $5 and payment.id > $4))))';
    source_order := 'payment.amount_rwf, payment.posted_at desc, payment.id';
    window_order := 'amount_rwf, posted_at desc, id';
  end if;

  execute format($page$
    with readable as materialized (
      select collection.id from public.collections collection
      where public.user_can_read_collection(collection.id, $1)
    ), candidate as (
      select payment.id, payment.collection_id, payment.amount_rwf,
        payment.posted_at, payment.contributor_user_id, payment.transaction_id,
        payment.anonymity_choice, payment.contributor_public_id
      from public.payments payment
      join public.collections collection on collection.id = payment.collection_id
      where payment.status = 'posted' and payment.currency = 'RWF'
        and ($2::uuid is null or payment.collection_id = $2)
        and (payment.contributor_user_id = $1
          or payment.collection_id in (select id from readable))
        and ($3 = ''
          or strpos(lower(case when payment.contributor_user_id = $1 then 'You'
            when payment.anonymity_choice = 'public_id'
              and payment.contributor_public_id is not null
              then 'Collect ID ' || payment.contributor_public_id
            else 'Anonymous supporter' end), $3) > 0
          or (payment.contributor_user_id = $1
            and strpos(lower(coalesce(payment.transaction_id, '')), $3) > 0)
          or (payment.collection_id in (select id from readable)
            and strpos(lower(collection.title), $3) > 0))
        and %s
      order by %s
      limit $7 + 1
    ), numbered as (
      select candidate.*, row_number() over (order by %s) as position
      from candidate
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'payment_id', 'momo:' || id,
      'collection_id', collection_id,
      'amount_minor', amount_rwf,
      'currency', 'RWF',
      'rail', 'rwanda_momo',
      'posted_at', posted_at,
      'transaction_id', case when contributor_user_id = $1 then transaction_id end,
      'is_current_user_contribution', coalesce(contributor_user_id = $1, false),
      'supporter_label', case when contributor_user_id = $1 then 'You'
        when anonymity_choice = 'public_id' and contributor_public_id is not null
          then 'Collect ID ' || contributor_public_id
        else 'Anonymous supporter' end
    ) order by position) filter (where position <= $7), '[]'::jsonb),
    count(*) > $7,
    max(case when position = $7 then 'momo:' || id end)
    from numbered
  $page$, keyset_predicate, source_order, window_order)
  into page_items, has_more, last_id
  using actor, p_collection_id, query_text, anchor_id, anchor_at,
    anchor_amount, p_limit;

  return jsonb_build_object(
    'items', page_items,
    'total_count', total_count,
    'totals', case when total_count = 0 then '{}'::jsonb
      else jsonb_build_object('RWF', total_amount) end,
    'own_totals', case when total_count = 0 then '{}'::jsonb
      else jsonb_build_object('RWF', own_amount) end,
    'own_collection_ids', own_collection_ids,
    'revision', revision,
    'next_cursor', case when has_more then
      jsonb_build_object('revision', revision, 'after', last_id) end
  );
end;
$_$;


--
-- Name: payment_history(); Type: FUNCTION; Schema: collect_member_actions; Owner: -
--

CREATE FUNCTION collect_member_actions.payment_history() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare actor uuid := auth.uid(); result jsonb;
begin
  if actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  with readable as materialized (
    select collection.id from public.collections collection
    where public.user_can_read_collection(collection.id, actor)
  ), history as (
    select payment.posted_at as happened_at, jsonb_build_object(
      'payment_id', 'momo:' || payment.id,
      'collection_id', payment.collection_id,
      'amount_minor', payment.amount_rwf,
      'currency', 'RWF',
      'rail', 'rwanda_momo',
      'posted_at', payment.posted_at,
      'transaction_id', case when payment.contributor_user_id = actor
        then payment.transaction_id end,
      'is_current_user_contribution', coalesce(payment.contributor_user_id = actor, false),
      'supporter_label', case when payment.contributor_user_id = actor then 'You'
        when payment.anonymity_choice = 'public_id'
          and payment.contributor_public_id is not null
          then 'Collect ID ' || payment.contributor_public_id
        else 'Anonymous supporter' end
    ) as item
    from public.payments payment
    where payment.status = 'posted' and payment.currency = 'RWF'
      and (payment.contributor_user_id = actor
        or payment.collection_id in (select id from readable))
  )
  select coalesce(jsonb_agg(item order by happened_at desc, item->>'payment_id'), '[]'::jsonb)
  into result from history;
  return result;
end;
$$;


--
-- Name: recent_intents(uuid); Type: FUNCTION; Schema: collect_member_actions; Owner: -
--

CREATE FUNCTION collect_member_actions.recent_intents(p_intent_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor uuid := auth.uid();
  items jsonb;
  pending_count bigint;
begin
  if actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  select count(*)::bigint into pending_count
  from public.payment_intents intent
  where intent.contributor_user_id = actor
    and intent.status = 'pending' and intent.expires_at > now();

  if p_intent_id is null then
    with selected as materialized (
      select intent.id, intent.collection_id, intent.expected_amount_rwf,
        intent.receiver_momo_number_hash, intent.status, intent.created_at,
        intent.expires_at
      from public.payment_intents intent
      where intent.contributor_user_id = actor
      order by intent.created_at desc, intent.id
      limit 50
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', intent.id,
      'collection_id', intent.collection_id,
      'rail', 'rwanda_momo',
      'amount_minor', intent.expected_amount_rwf,
      'currency', 'RWF',
      'receiver_momo_number', receiver.momo_number,
      'receiver_label', receiver.label,
      'network', receiver.network,
      'status', case when intent.status = 'pending' and intent.expires_at <= now()
        then 'expired' else intent.status::text end,
      'created_at', intent.created_at,
      'expires_at', intent.expires_at
    ) order by intent.created_at desc, intent.id), '[]'::jsonb)
    into items
    from selected intent
    left join lateral (
      select route.momo_number, route.label, route.network
      from public.collection_receivers route
      where route.collection_id = intent.collection_id
        and route.momo_number_hash = intent.receiver_momo_number_hash
      order by route.created_at desc, route.id limit 1
    ) receiver on true;
  else
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', intent.id,
      'collection_id', intent.collection_id,
      'rail', 'rwanda_momo',
      'amount_minor', intent.expected_amount_rwf,
      'currency', 'RWF',
      'receiver_momo_number', receiver.momo_number,
      'receiver_label', receiver.label,
      'network', receiver.network,
      'status', case when intent.status = 'pending' and intent.expires_at <= now()
        then 'expired' else intent.status::text end,
      'created_at', intent.created_at,
      'expires_at', intent.expires_at
    )), '[]'::jsonb)
    into items
    from public.payment_intents intent
    left join lateral (
      select route.momo_number, route.label, route.network
      from public.collection_receivers route
      where route.collection_id = intent.collection_id
        and route.momo_number_hash = intent.receiver_momo_number_hash
      order by route.created_at desc, route.id limit 1
    ) receiver on true
    where intent.id = p_intent_id and intent.contributor_user_id = actor;
  end if;

  return jsonb_build_object('items', items, 'pending_count', pending_count);
end;
$$;


--
-- Name: transfer_owned_group(uuid, text); Type: FUNCTION; Schema: collect_member_actions; Owner: -
--

CREATE FUNCTION collect_member_actions.transfer_owned_group(p_collection uuid, p_public_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor uuid := auth.uid();
  group_row public.collections%rowtype;
  target_user uuid;
  clean_id text := btrim(coalesce(p_public_id,''));
begin
  if actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  -- Serialize transfers/archives and re-check authority after taking the lock.
  select * into group_row from public.collections where id = p_collection for update;
  if group_row.id is null or group_row.creator_user_id is distinct from actor
     or group_row.is_platform_sponsored
     or group_row.public_status not in ('private', 'archived') then
    raise exception 'Only the current owner can transfer a private group' using errcode = '42501';
  end if;
  if group_row.archived_at is not null or group_row.public_status = 'archived' then
    raise exception 'Archived groups cannot be transferred' using errcode = '22023';
  end if;
  if clean_id !~ '^[0-9]{6}$' then
    raise exception 'Enter a 6 digit Collect ID.' using errcode = '22023';
  end if;
  -- Preserve the existing contract: a registered Collect ID may receive
  -- ownership. This endpoint never looks up or returns a personal name.
  select id into target_user from public.profiles where public_id = clean_id for key share;
  if target_user is null or target_user = actor then
    raise exception 'Choose another registered Collect ID' using errcode = '22023';
  end if;

  update public.collections set creator_user_id = target_user, updated_at = now()
  where id = p_collection;
  -- Preserve historical memberships, but never leave a stale active owner.
  update public.collection_members set status = 'removed'
  where collection_id = p_collection and role = 'owner' and user_id is distinct from target_user;
  insert into public.collection_members(collection_id,user_id,role,status)
  values(p_collection,target_user,'owner','active')
  on conflict(collection_id,user_id,role) do update set status = 'active';
  insert into public.collection_members(collection_id,user_id,role,status)
  values(p_collection,actor,'admin','active')
  on conflict(collection_id,user_id,role) do update set status = 'active';
  insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata)
  values(actor,'collection.ownership_transferred','collection',p_collection,
    jsonb_build_object('previous_owner_id',actor,'new_owner_id',target_user));
  -- Receiver, SMS consent, ledger and platform Admin roles are intentionally
  -- unchanged. Transferring a group is not approval to redirect its funds.
end;
$_$;


--
-- Name: assert_ready(text); Type: FUNCTION; Schema: collect_profile_access; Owner: -
--

CREATE FUNCTION collect_profile_access.assert_ready(required_rail text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  profile_row public.profiles%rowtype;
  local_momo text;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if required_rail is not null and required_rail <> 'rwanda' then
    raise exception 'Only Rwanda MoMo contributions are supported';
  end if;
  select * into profile_row from public.profiles where id = auth.uid() for share;
  if profile_row.id is null or profile_row.country_code <> 'RW'
     or profile_row.currency_code <> 'RWF'
     or profile_row.public_id !~ '^[0-9]{6}$'
     or nullif(btrim(profile_row.whatsapp_phone), '') is null then
    raise exception 'Complete your Rwanda MoMo profile first';
  end if;
  local_momo := public._rwanda_momo_local(profile_row.momo_number);
  if local_momo is null
     or profile_row.momo_provider not in ('mtn_momo', 'airtel_money')
     or (profile_row.momo_provider = 'mtn_momo' and local_momo !~ '^07[89][0-9]{7}$')
     or (profile_row.momo_provider = 'airtel_money' and local_momo !~ '^07[23][0-9]{7}$')
     or profile_row.momo_number_hash is distinct from
        encode(extensions.digest('+250' || substr(local_momo, 2), 'sha256'), 'hex') then
    raise exception 'Complete your profile with a valid MoMo number first';
  end if;
end;
$_$;


--
-- Name: normalize_account_number(text); Type: FUNCTION; Schema: collect_profile_access; Owner: -
--

CREATE FUNCTION collect_profile_access.normalize_account_number(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select upper(regexp_replace(btrim(coalesce(value, '')), '[[:space:]-]', '', 'g')); $$;


--
-- Name: require_rwanda_momo_collection(); Type: FUNCTION; Schema: collect_profile_access; Owner: -
--

CREATE FUNCTION collect_profile_access.require_rwanda_momo_collection() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (
    select 1 from public.collections collection
    where collection.id = new.collection_id
      and collection.currency = 'RWF'
      and not collection.diaspora_enabled
  ) then
    raise exception 'Only Rwanda MoMo groups accept new payment activity';
  end if;
  return new;
end;
$$;


--
-- Name: valid_account_number(text); Type: FUNCTION; Schema: collect_profile_access; Owner: -
--

CREATE FUNCTION collect_profile_access.valid_account_number(value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select collect_profile_access.normalize_account_number(value) ~ '^[A-Z0-9]{4,34}$'
    and collect_profile_access.normalize_account_number(value) ~ '[0-9]';
$_$;


--
-- Name: govern_runtime_control(); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.govern_runtime_control() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare control_family text:=tg_table_name; spec jsonb:=collect_security.runtime_control_spec(control_family); prior jsonb; next_row jsonb; identity_row jsonb;
 head collect_security.runtime_control_heads; context jsonb; owner_maintenance boolean;
 actor uuid; sid uuid; audit_redacted boolean; reason_hash text; reason_length integer; changed text[]; content_hash text; target_revision bigint;
begin
 if spec is null or spec->>'relation'<>(tg_table_schema||'.'||tg_table_name) then raise exception 'runtime_control_family_invalid' using errcode='55000';end if;
 prior:=case when tg_op='INSERT' then null else to_jsonb(old) end;
 next_row:=case when tg_op='DELETE' then null else to_jsonb(new) end;
 owner_maintenance:=session_user='postgres' and current_setting('role') in ('none','postgres');
 if control_family='notification_preferences' and not owner_maintenance and coalesce(next_row,prior)->>'user_id' is distinct from auth.uid()::text then raise exception 'runtime_control_owner_required' using errcode='42501';end if;
 -- Crucial: preserve the145/146 physical same-value UPDATE serialization
 -- fence. Returning NEW still writes the row; governance state remains untouched.
 if tg_op='UPDATE' and collect_security.runtime_control_hash(prior)=collect_security.runtime_control_hash(next_row) then return new;end if;
 identity_row:=collect_security.runtime_control_identity(control_family,coalesce(next_row,prior));
 if tg_op='UPDATE' and identity_row is distinct from collect_security.runtime_control_identity(control_family,prior) then raise exception 'runtime_control_identity_immutable' using errcode='55000';end if;
 if tg_op='DELETE' and (control_family in ('policy_documents','notification_template_versions') and (prior->>'status'<>'draft' or prior->>'published_at' is not null)
    or control_family='notification_templates' and exists(select 1 from public.notification_template_versions where template_key=prior->>'key' and (status<>'draft' or published_at is not null))
    or control_family='policy_document_sections' and exists(select 1 from public.policy_documents where id=(prior->>'policy_document_id')::uuid and (status<>'draft' or published_at is not null))) then raise exception 'runtime_control_published_immutable' using errcode='55000';end if;
 perform collect_security.runtime_control_lock_parent(control_family,coalesce(next_row,prior),prior,tg_op='DELETE');
 if owner_maintenance then
  actor:=null;sid:=null;reason_hash:=encode(extensions.digest(convert_to('database_owner_maintenance','UTF8'),'sha256'),'hex');reason_length:=26;
 else
  begin context:=current_setting('collect.runtime_control_context',true)::jsonb;exception when others then context:=null;end;
  if context is null or jsonb_typeof(context) is distinct from 'object' or octet_length(context::text)>4096 then raise exception 'runtime_control_revision_required' using errcode='42501';end if;
  if (select array_agg(key order by key) from jsonb_object_keys(context) key) is distinct from
   array['actor_id','expected_revision','family','identity','reason_characters','reason_sha256','session_id']::text[]
   or jsonb_typeof(context->'family') is distinct from 'string' or context->>'family' is distinct from control_family
   or jsonb_typeof(context->'identity') is distinct from 'object' or context->'identity' is distinct from identity_row
   or jsonb_typeof(context->'actor_id') is distinct from 'string' or context->>'actor_id' is distinct from auth.uid()::text
   or jsonb_typeof(context->'session_id') is distinct from 'string' or context->>'session_id' is distinct from auth.jwt()->>'session_id'
   or jsonb_typeof(context->'expected_revision') is distinct from 'number' or char_length(context->>'expected_revision') not between 1 and 10
   or context->>'expected_revision' !~ '^(0|[1-9][0-9]*)$'
   or jsonb_typeof(context->'reason_characters') is distinct from 'number' or char_length(context->>'reason_characters') not between 1 and 3
   or context->>'reason_characters' !~ '^[1-9][0-9]*$'
   or jsonb_typeof(context->'reason_sha256') is distinct from 'string' or context->>'reason_sha256' !~ '^[a-f0-9]{64}$' then
   raise exception 'runtime_control_revision_required' using errcode='42501';end if;
  if (context->>'expected_revision')::bigint not between 0 and 1000000000 or (context->>'reason_characters')::integer not between 8 and 500 then
   raise exception 'runtime_control_revision_required' using errcode='42501';end if;
  actor:=auth.uid();sid:=collect_security.runtime_control_actor(control_family);
  reason_hash:=context->>'reason_sha256';reason_length:=(context->>'reason_characters')::integer;
 end if;
 select * into head from collect_security.runtime_control_heads where runtime_control_heads.family=control_family and identity=identity_row for update;
 if not owner_maintenance and coalesce(head.revision,0) is distinct from (context->>'expected_revision')::bigint then raise exception 'runtime_control_conflict' using errcode='40001';end if;
 if head.family is not null and prior is not null and head.content_sha256 is distinct from collect_security.runtime_control_hash(prior) then raise exception 'runtime_control_head_invalid' using errcode='55000';end if;
 if tg_op<>'DELETE' then
  if control_family in ('policy_documents','notification_template_versions') and next_row->>'status'='published' and (prior is null or prior->>'status'='draft') then next_row:=next_row||jsonb_build_object('published_at',clock_timestamp());end if;
  if control_family in ('sms_receipt_policies','sms_receipt_member_consents') then
   next_row:=next_row||jsonb_build_object('reason','runtime_control:'||reason_hash,'revision',coalesce((prior->>'revision')::integer,0)+1);
   if control_family='sms_receipt_policies' then next_row:=next_row||jsonb_build_object('updated_by',actor);else next_row:=next_row||jsonb_build_object('recorded_by',actor,'recorded_at',clock_timestamp());end if;
   -- Database-owner fixtures must explicitly carry the accountable profile.
   if actor is null then next_row:=next_row||jsonb_build_object(case when control_family='sms_receipt_policies' then 'updated_by' else 'recorded_by' end,coalesce(to_jsonb(new)->case when control_family='sms_receipt_policies' then 'updated_by' else 'recorded_by' end,prior->case when control_family='sms_receipt_policies' then 'updated_by' else 'recorded_by' end));end if;
  end if;
  perform collect_security.runtime_control_validate(control_family,next_row,prior);
  if next_row ? 'updated_at' then next_row:=next_row||jsonb_build_object('updated_at',clock_timestamp());end if;
  if next_row ? 'updated_by' and not (control_family='sms_receipt_policies' and actor is null) then next_row:=next_row||jsonb_build_object('updated_by',actor);end if;
  if next_row ? 'updated_reason' then next_row:=next_row||jsonb_build_object('updated_reason','runtime_control:'||reason_hash);end if;
  if control_family='roster_resource_policy' and prior is not null then next_row:=next_row||jsonb_build_object('version',(prior->>'version')::integer+1);end if;
  new:=jsonb_populate_record(new,next_row);
 end if;
 select coalesce(array_agg(key order by key),'{}') into changed from jsonb_each(coalesce(next_row,prior)) field
 where field.key not in ('created_at','updated_at','updated_by','updated_reason','recorded_by','recorded_at','reason') and (tg_op<>'UPDATE' or prior->field.key is distinct from field.value);
 target_revision:=coalesce(head.revision,0)+1;
 content_hash:=case when tg_op='DELETE' then collect_security.runtime_control_hash(jsonb_build_object('deleted',true)) else collect_security.runtime_control_hash(next_row) end;
 insert into collect_security.runtime_control_heads(family,identity,revision,content_sha256,updated_at) values(control_family,identity_row,target_revision,content_hash,clock_timestamp())
 on conflict on constraint runtime_control_heads_pkey do update set revision=excluded.revision,content_sha256=excluded.content_sha256,updated_at=excluded.updated_at;
 audit_redacted:=control_family='notification_preferences' or control_family='system_settings' and coalesce((coalesce(next_row,prior)->>'is_sensitive')::boolean,false);
 insert into collect_security.runtime_control_events(family,identity_sha256,previous_revision,revision,operation,old_sha256,new_sha256,changed_fields,actor_id,session_id,authority,reason_sha256,redacted,reason_characters)
 values(control_family,collect_security.runtime_control_hash(identity_row),target_revision-1,target_revision,lower(tg_op),case when prior is null or audit_redacted then null else collect_security.runtime_control_hash(prior) end,
 case when next_row is null or audit_redacted then null else content_hash end,changed,actor,sid,case when owner_maintenance then 'database_owner' else 'live_operator' end,reason_hash,audit_redacted,reason_length);
 if tg_op='DELETE' then return old;end if;return new;
end $_$;


