--
-- Name: operational_health_alerts(jsonb); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.operational_health_alerts(p_metrics jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare rule record; value jsonb; number_value numeric; state text;
 alerts jsonb:='[]';
begin
 if p_metrics is null or jsonb_typeof(p_metrics)<>'object' then
  raise exception 'operational_health_invalid' using errcode='22023';end if;
 for rule in select * from (values
  ('receipt_parse_backlog','sms_pending',100::numeric,null::text),
  ('receipt_parse_age','sms_pending_age_seconds',300::numeric,'sms_pending'),
  ('receipt_parse_failure','sms_failed_24h',1::numeric,null::text),
  ('receipt_parser_lease_expired','sms_expired_parse_leases',1::numeric,null::text),
  ('payment_unmatched','unallocated_events',1::numeric,null::text),
  ('payment_review_age','payment_review_age_seconds',3600::numeric,'payments_review'),
  ('reconciliation_exception','reconciliation_open',1::numeric,null::text),
  ('push_queue_age','push_due_age_seconds',120::numeric,'push_due'),
  ('push_expired_lease','push_expired_leases',1::numeric,null::text),
  ('push_missing_lease','push_missing_leases',1::numeric,null::text),
  ('push_attempt_failure','push_failed_24h',5::numeric,null::text),
  ('receipt_telemetry_stale','receipt_telemetry_age_seconds',300::numeric,'durable_receipts_24h'),
  ('push_scheduler_stale','push_scheduler_age_seconds',180::numeric,'push_due')
 ) rules(code,metric,threshold,queue) loop
  value:=p_metrics->rule.metric;
  if rule.queue is not null and p_metrics->rule.queue='0'::jsonb then state:='not_applicable';
  elsif value is null or value='null'::jsonb then state:='unknown';
  elsif jsonb_typeof(value)<>'number' or (value#>>'{}') !~ '^[0-9]+$'
     or (value#>>'{}')::numeric>9007199254740991 then
   raise exception 'operational_health_invalid' using errcode='22023';
  else number_value:=(value#>>'{}')::numeric;
   state:=case when number_value>=rule.threshold then 'attention' else 'ok' end;
  end if;
  alerts:=alerts||jsonb_build_array(jsonb_build_object('code',rule.code,'metric',rule.metric,
   'threshold',rule.threshold,'state',state));
 end loop;
 return alerts;
end $_$;


--
-- Name: otp_expire_v3(text); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.otp_expire_v3(p_hook_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r collect_security.signed_otp_requests; kind text; h text; t timestamptz:=clock_timestamp();
begin
 select * into r from collect_security.signed_otp_requests where hook_id=p_hook_id for update;
 if r.status='reserved' and r.requested_at<t-interval '5 minutes' then
   kind:='expired_unsent';
 elsif r.status='sending' and r.started_at<t-interval '1 minute' then
   kind:='transport_ambiguous';
 else return; end if;
 h:=encode(extensions.digest(convert_to(kind||':'||r.attempt_id::text||':'||r.revision::text,'UTF8'),'sha256'),'hex');
 update collect_security.signed_otp_requests set status=case when kind='expired_unsent' then 'expired' else 'ambiguous' end,
   revision=revision+1,last_evidence_sha256=h where hook_id=r.hook_id returning * into r;
 insert into collect_security.signed_otp_evidence(hook_id,attempt_id,revision,evidence_sha256,evidence_kind,observed_at,source)
 values(r.hook_id,r.attempt_id,r.revision,h,kind,t,'local_clock');
end $$;


--
-- Name: signed_otp_requests; Type: TABLE; Schema: collect_security; Owner: -
--

CREATE TABLE collect_security.signed_otp_requests (
    hook_id text NOT NULL,
    payload_hash text NOT NULL,
    phone_hash text NOT NULL,
    requested_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    delivered_at timestamp with time zone,
    status text DEFAULT 'reserved'::text NOT NULL,
    attempt_id uuid DEFAULT gen_random_uuid() NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    started_at timestamp with time zone,
    accepted_at timestamp with time zone,
    provider_message_hash text,
    last_evidence_sha256 text,
    contract_version integer DEFAULT 3 NOT NULL,
    CONSTRAINT signed_otp_evidence_hash_v3 CHECK (((last_evidence_sha256 IS NULL) OR (last_evidence_sha256 ~ '^[a-f0-9]{64}$'::text))),
    CONSTRAINT signed_otp_hook_v3 CHECK ((((char_length(hook_id) >= 1) AND (char_length(hook_id) <= 256)) AND (hook_id ~ '^[A-Za-z0-9_:.-]+$'::text))),
    CONSTRAINT signed_otp_provider_hash_v3 CHECK (((provider_message_hash IS NULL) OR (provider_message_hash ~ '^[a-f0-9]{64}$'::text))),
    CONSTRAINT signed_otp_requests_payload_hash_check CHECK ((payload_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT signed_otp_requests_phone_hash_check CHECK ((phone_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT signed_otp_revision_v3 CHECK (((revision >= 1) AND (revision <= 1000000))),
    CONSTRAINT signed_otp_state_v3 CHECK ((status = ANY (ARRAY['reserved'::text, 'sending'::text, 'accepted'::text, 'delivered'::text, 'not_sent'::text, 'failed'::text, 'ambiguous'::text, 'expired'::text])))
);


--
-- Name: otp_receipt_v3(collect_security.signed_otp_requests); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.otp_receipt_v3(r collect_security.signed_otp_requests) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if r.contract_version not in (2,3) or r.revision is null or r.attempt_id is null or
   (r.status='sending' and r.started_at is null) or
   (r.status='accepted' and r.contract_version=3 and (r.accepted_at is null or r.provider_message_hash is null)) or
   (r.status='delivered' and (r.accepted_at is null or r.delivered_at is null or r.provider_message_hash is null)) then
   raise exception 'OTP stored state unavailable' using errcode='55000';
 end if;
 return jsonb_build_object('contract_version',3,'hook_id',r.hook_id,'payload_hash',r.payload_hash,
   'attempt_id',r.attempt_id,'state',r.status,'revision',r.revision,
   'can_send',r.contract_version=3 and r.status='reserved');
end $$;


--
-- Name: purge_operational_metrics(integer); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.purge_operational_metrics(p_limit integer DEFAULT 1000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare removed integer;
begin
 if p_limit is null or p_limit not between 1 and 10000 then
  raise exception 'operational_metric_limit_invalid' using errcode='22023';end if;
 with old as (select bucket_at,event_code from collect_security.operational_metric_buckets
   where bucket_at<clock_timestamp()-interval '90 days' order by bucket_at,event_code
   for update skip locked limit p_limit), gone as (
   delete from collect_security.operational_metric_buckets b using old
   where b.bucket_at=old.bucket_at and b.event_code=old.event_code returning 1)
 select count(*) into removed from gone;
 return removed;
end $$;


--
-- Name: reconciliation_actor_current(uuid, uuid); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.reconciliation_actor_current(p_actor uuid, p_session uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare u auth.users; s auth.sessions;
begin
 if p_actor is null or p_session is null then return false; end if;
 select * into u from auth.users where id=p_actor for share;
 select * into s from auth.sessions where id=p_session and user_id=p_actor for share;
 if u.id is null or s.id is null or s.aal::text is distinct from 'aal2'
   or (s.not_after is not null and s.not_after<=clock_timestamp())
   or u.deleted_at is not null or u.phone_confirmed_at is null or coalesce(u.is_anonymous,false)
   or (u.banned_until is not null and u.banned_until>clock_timestamp()) then return false; end if;
 return exists(select 1 from collect_admin_access.whatsapp_approvals a
   join public.admin_user_roles ur on ur.user_id=a.user_id and ur.revoked_at is null
   join public.admin_roles r on r.id=ur.role_id and r.name='platform_owner'
   join public.admin_role_permissions rp on rp.role_id=r.id and rp.permission_name='payments.allocate'
   where a.user_id=p_actor and a.revoked_at is null
     and a.phone_e164='+'||ltrim(u.phone,'+')
     and (a.expires_at is null or a.expires_at>clock_timestamp())
     and s.created_at>=a.approved_at and s.created_at>=ur.created_at);
end $$;


--
-- Name: payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    parsed_event_id uuid,
    payment_intent_id uuid,
    collection_id uuid NOT NULL,
    contributor_user_id uuid,
    contributor_public_id character(6),
    receiver_user_id uuid NOT NULL,
    receiver_momo_number_hash text NOT NULL,
    amount_rwf bigint NOT NULL,
    currency text DEFAULT 'RWF'::text NOT NULL,
    transaction_id text,
    source text NOT NULL,
    status text DEFAULT 'posted'::text NOT NULL,
    anonymity_choice text DEFAULT 'anonymous'::text NOT NULL,
    posted_at timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    provider_network text DEFAULT 'unknown'::text NOT NULL,
    member_record_id uuid,
    CONSTRAINT payments_amount_rwf_check CHECK ((amount_rwf > 0)),
    CONSTRAINT payments_anonymity_choice_check CHECK ((anonymity_choice = ANY (ARRAY['anonymous'::text, 'public_id'::text, 'display_name'::text]))),
    CONSTRAINT payments_currency_check CHECK ((currency = 'RWF'::text)),
    CONSTRAINT payments_posted_rwf_has_posted_at CHECK (((status <> 'posted'::text) OR (currency <> 'RWF'::text) OR (posted_at IS NOT NULL))),
    CONSTRAINT payments_provider_network_check CHECK ((provider_network = ANY (ARRAY['mtn_momo'::text, 'airtel_money'::text, 'unknown'::text]))),
    CONSTRAINT payments_source_check CHECK ((source = ANY (ARRAY['sms_auto'::text, 'manual_sms_paste'::text, 'manual_admin'::text, 'import'::text]))),
    CONSTRAINT payments_status_check CHECK ((status = ANY (ARRAY['posted'::text, 'reversed'::text, 'review'::text])))
);


--
-- Name: reconciliation_fingerprint(public.payments); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.reconciliation_fingerprint(p public.payments) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select encode(extensions.digest(jsonb_build_object(
   'id',p.id,'collection_id',p.collection_id,'amount_rwf',p.amount_rwf,
   'network',p.provider_network,'transaction_id',p.transaction_id,
   'receiver_user_id',p.receiver_user_id,'receiver_hash',p.receiver_momo_number_hash,
   'contributor_user_id',p.contributor_user_id,'member_record_id',p.member_record_id,
   'parsed_event_id',p.parsed_event_id,'payment_intent_id',p.payment_intent_id,
   'source',p.source,'currency',p.currency
 )::text,'sha256'),'hex')
$$;


--
-- Name: require_otp_service_v3(); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.require_otp_service_v3() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if coalesce(auth.role(),'')<>'service_role' then
   raise exception 'OTP authorization required' using errcode='42501';
 end if;
end $$;


--
-- Name: require_reconciliation_actor(); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.require_reconciliation_actor() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare session_text text:=auth.jwt()->>'session_id'; session_id uuid;
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'authenticated' or auth.uid() is null
   or auth.jwt()->>'aal' is distinct from 'aal2' or session_text is null
   or session_text !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
  raise exception 'reconciliation_step_up_required' using errcode='42501';
 end if;
 session_id:=session_text::uuid;
 perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
 if not collect_security.reconciliation_actor_current(auth.uid(),session_id) then
  raise exception 'reconciliation_actor_unavailable' using errcode='42501';
 end if;
 return session_id;
end $_$;


--
-- Name: require_shadow_actor(); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.require_shadow_actor() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid;
begin
  begin sid:=public._lock_notification_registration_session();
  exception when sqlstate '42501' then
    raise exception 'shadow_session_required' using errcode='42501';end;
  -- Match150: Auth/session -> roster serialization -> authority rows -> lease.
  perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
  begin
    perform collect_hybrid.require_roster_actor_authority(auth.uid(),sid,
      'platform_owner',array['system_health.read','notifications.read']);
  exception when sqlstate '42501' then
    raise exception 'shadow_permission_required' using errcode='42501';end;
  return sid;
end $$;


--
-- Name: require_shadow_health(jsonb, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.require_shadow_health(p_health jsonb, p_started_at timestamp with time zone, p_observed_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare checked timestamptz; expires timestamptz; canonical_alerts jsonb;
  allowed_keys text[]:=array['id','contract_version','database','auth','parser_pending_sms',
    'failed_sms_parse','unallocated_events','queued_notifications','processing_notifications',
    'failed_notifications','checked_at','metrics','alerts','health_status','sample_valid_until',
    'window_seconds','threshold_version','scheduler','evidence_limits'];
  metric_keys text[]:=array['push_due','push_failed','push_queued','sms_pending','reversals_24h',
    'push_retry_24h','sms_failed_24h','sms_parsed_24h','payments_review','push_failed_24h',
    'push_processing','push_attempts_24h','unallocated_events','finality_processing',
    'payments_posted_24h','push_expired_leases','push_latency_p95_ms','push_missing_leases',
    'reconciliation_open','durable_receipts_24h','push_due_age_seconds','receipt_rejected_24h',
    'finality_processed_24h','sms_pending_age_seconds','sms_expired_parse_leases',
    'push_provider_accepts_24h','receipt_ack_generated_24h','payment_review_age_seconds',
    'push_scheduler_age_seconds','receipt_ack_latency_mean_ms','receipt_telemetry_age_seconds'];
  nullable_metric_keys text[]:=array['push_latency_p95_ms','push_due_age_seconds',
    'sms_pending_age_seconds','payment_review_age_seconds','push_scheduler_age_seconds',
    'receipt_ack_latency_mean_ms','receipt_telemetry_age_seconds'];
  metric record;
begin
  if p_health is null or jsonb_typeof(p_health) is distinct from 'object'
    or p_health->'contract_version' is distinct from '1'::jsonb
    or jsonb_typeof(p_health->'alerts') is distinct from 'array'
    or jsonb_typeof(p_health->'metrics') is distinct from 'object'
    or jsonb_typeof(p_health->'checked_at') is distinct from 'string'
    or jsonb_typeof(p_health->'sample_valid_until') is distinct from 'string'
    or p_health->>'health_status' is null
    or p_health->>'health_status' not in ('ok','unknown','attention') then
    raise exception 'shadow_integrity_unavailable' using errcode='55000';end if;
  if not (p_health->'metrics' ?& metric_keys)
    or (p_health->'metrics')-metric_keys<>'{}'::jsonb then
    raise exception 'shadow_integrity_unavailable' using errcode='55000';end if;
  for metric in select key,value from jsonb_each(p_health->'metrics') loop
    if metric.value='null'::jsonb and metric.key=any(nullable_metric_keys) then continue;end if;
    if jsonb_typeof(metric.value) is distinct from 'number' then
      raise exception 'shadow_integrity_unavailable' using errcode='55000';end if;
    if metric.value::text !~ '^[0-9]+$' or metric.value::text::numeric>9007199254740991 then
      raise exception 'shadow_integrity_unavailable' using errcode='55000';end if;
  end loop;
  if p_health->'parser_pending_sms' is distinct from p_health->'metrics'->'sms_pending'
    or p_health->'failed_sms_parse' is distinct from p_health->'metrics'->'sms_failed_24h'
    or p_health->'unallocated_events' is distinct from p_health->'metrics'->'unallocated_events'
    or p_health->'queued_notifications' is distinct from p_health->'metrics'->'push_queued'
    or p_health->'processing_notifications' is distinct from p_health->'metrics'->'push_processing'
    or p_health->'failed_notifications' is distinct from p_health->'metrics'->'push_failed' then
    raise exception 'shadow_integrity_unavailable' using errcode='55000';end if;
  -- Enforce the existing redacted v1 surface before making durable evidence.
  -- Future accidental source fields must not become a receipt-data export.
  if not (p_health ?& allowed_keys) or p_health-allowed_keys<>'{}'::jsonb
    or p_health->>'id' is distinct from 'system'
    or p_health->>'database' is distinct from 'reachable'
    or p_health->>'auth' is distinct from 'authenticated'
    or p_health->'window_seconds' is distinct from '86400'::jsonb
    or p_health->'threshold_version' is distinct from '1'::jsonb
    or jsonb_typeof(p_health->'metrics') is distinct from 'object'
    or jsonb_typeof(p_health->'scheduler') is distinct from 'object'
    or (p_health->'scheduler')-array['state','configuration_verified']<>'{}'::jsonb
    or p_health->'scheduler'->'configuration_verified' is distinct from 'false'::jsonb
    or p_health->'scheduler'->>'state' is null
    or p_health->'scheduler'->>'state' not in ('unknown','enabled','disabled')
    or p_health->'evidence_limits' is distinct from jsonb_build_array(
      'ACK generation does not prove device receipt.',
      'Provider acceptance does not prove user delivery.',
      'Scheduler activation does not prove provider configuration.') then
    raise exception 'shadow_integrity_unavailable' using errcode='55000';end if;
  if jsonb_array_length(p_health->'alerts')<>13 or exists(
    select 1 from jsonb_array_elements(p_health->'alerts') a
    where jsonb_typeof(a) is distinct from 'object' or a->>'state' is null
      or a->>'state' not in ('ok','unknown','attention','not_applicable')) then
    raise exception 'shadow_integrity_unavailable' using errcode='55000';end if;
  begin canonical_alerts:=collect_security.operational_health_alerts(p_health->'metrics');
  exception when others then
    raise exception 'shadow_integrity_unavailable' using errcode='55000';end;
  if p_health->'alerts' is distinct from canonical_alerts
    or p_health->>'health_status' is distinct from (case
      when exists(select 1 from jsonb_array_elements(canonical_alerts) a where a->>'state'='attention') then 'attention'
      when exists(select 1 from jsonb_array_elements(canonical_alerts) a where a->>'state'='unknown') then 'unknown'
      else 'ok' end) then
    raise exception 'shadow_integrity_unavailable' using errcode='55000';end if;
  begin
    checked:=(p_health->>'checked_at')::timestamptz;
    expires:=(p_health->>'sample_valid_until')::timestamptz;
  exception when others then
    raise exception 'shadow_integrity_unavailable' using errcode='55000';end;
  if checked is null or expires is null or not isfinite(checked) or not isfinite(expires)
    or expires<>checked+interval '60 seconds' or checked<p_started_at or checked>p_observed_at then
    raise exception 'shadow_integrity_unavailable' using errcode='55000';end if;
  if expires<=p_observed_at then
    raise exception 'shadow_health_stale' using errcode='55000';end if;
end $_$;


--
-- Name: runtime_control_actor(text, boolean); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.runtime_control_actor(p_family text, p_read boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare spec jsonb:=collect_security.runtime_control_spec(p_family);
 session_id uuid; permissions text[];
begin
 if spec is null then raise exception 'runtime_control_family_invalid' using errcode='22023';end if;
 begin session_id:=public._lock_notification_registration_session();
 exception when sqlstate '42501' then
  raise exception 'runtime_control_session_required' using errcode='42501';end;
 if coalesce((spec->>'user_owned')::boolean,false) then return session_id;end if;
 permissions:=array[case when p_read then spec->>'read_permission' else spec->>'permission' end];
 if not p_read and spec ? 'additional_permission' then
  permissions:=array_append(permissions,spec->>'additional_permission');end if;
 begin
  perform collect_hybrid.require_roster_actor_authority(auth.uid(),session_id,'platform_owner',permissions);
 exception when sqlstate '42501' then
  raise exception 'runtime_control_permission_required' using errcode='42501';end;
 return session_id;
end $$;


--
-- Name: runtime_control_bound_json(jsonb, integer); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.runtime_control_bound_json(p_value jsonb, p_depth integer DEFAULT 0) RETURNS void
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare item record; text_value text;
begin
 if p_value is null or p_depth>5 or octet_length(p_value::text)>65536 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
 if jsonb_typeof(p_value)='object' then
  if (select count(*) from jsonb_object_keys(p_value))>50 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
  for item in select * from jsonb_each(p_value) loop
   if char_length(item.key) not between 1 and 80 or item.key !~ '^[A-Za-z_][A-Za-z0-9_.:-]*$'
      or item.key ~* '(secret|password|credential|api[_-]?key|authorization|access[_-]?token|refresh[_-]?token|private[_-]?key)' then
    raise exception 'runtime_control_sensitive_field' using errcode='22023';end if;
   perform collect_security.runtime_control_bound_json(item.value,p_depth+1);
  end loop;
 elsif jsonb_typeof(p_value)='array' then
  if jsonb_array_length(p_value)>50 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
  for item in select value from jsonb_array_elements(p_value) loop perform collect_security.runtime_control_bound_json(item.value,p_depth+1);end loop;
 elsif jsonb_typeof(p_value)='string' then
  text_value:=p_value#>>'{}';
  if char_length(text_value)>32768 or regexp_replace(text_value,E'[\n\r\t]','','g') ~ '[[:cntrl:]]' then raise exception 'runtime_control_invalid' using errcode='22023';end if;
 elsif jsonb_typeof(p_value)='number' then
  if (p_value#>>'{}')::numeric not between -100000000000 and 100000000000 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
 end if;
end $_$;


--
-- Name: runtime_control_check_identity(text, jsonb); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.runtime_control_check_identity(p_family text, p_identity jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare spec jsonb:=collect_security.runtime_control_spec(p_family); field record; typ text; clean text;
begin
 if spec is null or p_identity is null or jsonb_typeof(p_identity)<>'object' or octet_length(p_identity::text)>2048 then raise exception 'runtime_control_identity_invalid' using errcode='22023';end if;
 if (select array_agg(key order by key) from jsonb_object_keys(p_identity) key) is distinct from (select array_agg(key order by key) from jsonb_array_elements_text(spec->'identity') key) then raise exception 'runtime_control_identity_invalid' using errcode='22023';end if;
 if coalesce((spec->>'user_owned')::boolean,false) and p_identity->>'user_id' is distinct from auth.uid()::text then raise exception 'runtime_control_owner_required' using errcode='42501';end if;
 for field in select * from jsonb_each(p_identity) loop
  typ:=spec->'types'->>field.key;clean:=field.value#>>'{}';
  if field.value='null'::jsonb
   or typ='uuid' and (jsonb_typeof(field.value)<>'string' or clean !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$')
   or typ='boolean' and field.value is distinct from 'true'::jsonb
   or typ='text' and (jsonb_typeof(field.value)<>'string' or char_length(clean) not between 1 and 128 or clean !~ '^[A-Za-z0-9_.:-]+$') then raise exception 'runtime_control_identity_invalid' using errcode='22023';end if;
 end loop;
end $_$;


--
-- Name: runtime_control_check_values(text, jsonb); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.runtime_control_check_values(p_family text, p_values jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare spec jsonb:=collect_security.runtime_control_spec(p_family); field record; typ text; value_type text; clean text; limit_chars integer; numeric_value numeric;
begin
 if spec is null or p_values is null or jsonb_typeof(p_values)<>'object' or octet_length(p_values::text)>65536 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
 for field in select * from jsonb_each(p_values) loop
  typ:=spec->'types'->>field.key;value_type:=jsonb_typeof(field.value);clean:=field.value#>>'{}';
  if typ is null then raise exception 'runtime_control_invalid' using errcode='22023';end if;
  if value_type='null' then
   if not (spec->'nullable') ? field.key then raise exception 'runtime_control_invalid' using errcode='22023';end if;
   continue;
  end if;
  if typ='boolean' and value_type<>'boolean' or typ in ('integer','bigint') and (value_type<>'number' or clean !~ '^-?[0-9]+$')
    or typ in ('text','uuid','timestamp with time zone') and value_type<>'string' then raise exception 'runtime_control_invalid' using errcode='22023';end if;
  if typ in ('integer','bigint') then
   numeric_value:=clean::numeric;
   if typ='integer' and numeric_value not between -2147483648 and 2147483647 or typ='bigint' and numeric_value not between -100000000000 and 100000000000 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
  end if;
  if typ='jsonb' then perform collect_security.runtime_control_bound_json(field.value);end if;
  if typ='uuid' and clean !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then raise exception 'runtime_control_invalid' using errcode='22023';end if;
  if typ='timestamp with time zone' then
   if char_length(clean) not between 20 and 35 or clean !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'runtime_control_invalid' using errcode='22023';end if;
   begin
    if not isfinite(clean::timestamptz) or clean::timestamptz>clock_timestamp()+interval '2 years' or clean::timestamptz<'2000-01-01'::timestamptz then raise exception 'runtime_control_invalid' using errcode='22023';end if;
   exception when invalid_datetime_format or datetime_field_overflow then raise exception 'runtime_control_invalid' using errcode='22023';end;
  end if;
  if typ='text' then
   limit_chars:=case when field.key in ('body','body_template','instructions','regulatory_footer_note') then 24000 when field.key in ('description','subtitle','summary','short_purpose','target','owner','escalation') then 2000 when field.key like '%url' then 2048 else 500 end;
   if char_length(clean)>limit_chars or regexp_replace(clean,E'[\n\r\t]','','g') ~ '[[:cntrl:]]' then raise exception 'runtime_control_invalid' using errcode='22023';end if;
   if field.key in ('key','queue_key','rpc_name','section_key','icon_key','version','locale','network','currency','country_code','required_permission','template_key','event_type_key','preference_key','collection_type_key','default_category_subtype','default_purpose_template_key')
    and (char_length(clean) not between 1 and 128 or clean !~ '^[A-Za-z0-9_.:-]+$') then raise exception 'runtime_control_invalid' using errcode='22023';end if;
   if field.key in ('label','display_name','legal_name','title','title_template','body_template','body','target','owner','escalation') and char_length(btrim(clean))=0 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
   if field.key like '%url' and not collect_security.runtime_control_https(clean) then raise exception 'runtime_control_invalid_url' using errcode='22023';end if;
   if field.key in ('title_template','body_template') and regexp_replace(clean,'\{\{[a-z][a-z0-9_]{0,63}\}\}','','g') ~ '(\{\{|\}\})' then raise exception 'runtime_control_invalid_template' using errcode='22023';end if;
  end if;
  if field.key in ('display_order','sort_order') and numeric_value not between 0 and 10000 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
 end loop;
end $_$;


--
-- Name: runtime_control_hash(jsonb); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.runtime_control_hash(p_row jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select encode(extensions.digest(convert_to((p_row-array['updated_at','updated_by','updated_reason','recorded_at','recorded_by','reason'])::text,'UTF8'),'sha256'),'hex');
$$;


--
-- Name: runtime_control_https(text); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.runtime_control_https(p_value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
 select p_value is not null and char_length(p_value) between 10 and 2048
  and p_value ~ '^https://[A-Za-z0-9][A-Za-z0-9.-]*\.[A-Za-z]{2,63}(:443)?([/?][^[:space:]@]*)?$'
  and p_value !~ '[[:cntrl:]]' and p_value !~ '^https://[0-9.]+';
$_$;


--
-- Name: runtime_control_identity(text, jsonb); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.runtime_control_identity(p_family text, p_row jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select jsonb_object_agg(k,p_row->k) from jsonb_array_elements_text(collect_security.runtime_control_spec(p_family)->'identity') k;
$$;


--
-- Name: runtime_control_lock_parent(text, jsonb, jsonb, boolean); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.runtime_control_lock_parent(p_family text, p_new jsonb, p_old jsonb, p_delete boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare parent_id uuid; template_key_text text; parent public.policy_documents;
begin
 if p_family='policy_documents' then
  perform 1 from public.policy_documents where id=(p_new->>'id')::uuid for update;
 elsif p_family='policy_document_sections' then
  if p_old is not null and p_old->>'policy_document_id' is distinct from p_new->>'policy_document_id' then raise exception 'runtime_control_wiring_immutable' using errcode='55000';end if;
  parent_id:=(p_new->>'policy_document_id')::uuid;
  -- Physical parent fencing also prevents stale repeatable-read publication
  -- after a committed section edit. Governance no-op keeps its version intact.
  update public.policy_documents set status=status where id=parent_id returning * into parent;
  if parent.id is null and p_delete and pg_trigger_depth()>1 then return;end if;
  if parent.id is null or parent.status<>'draft' or parent.published_at is not null then raise exception 'runtime_control_published_immutable' using errcode='55000';end if;
 elsif p_family='notification_template_versions' then
  template_key_text:=p_new->>'template_key';
  update public.notification_templates set enabled=enabled where key=template_key_text;
  if not found and p_delete and pg_trigger_depth()>1 then return;end if;
  if not found then raise exception 'runtime_control_template_required' using errcode='22023';end if;
 end if;
end $$;


