--
-- Name: runtime_control_validate(text, jsonb, jsonb); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.runtime_control_validate(p_family text, p_new jsonb, p_old jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare spec jsonb:=collect_security.runtime_control_spec(p_family); field record; typ text; value_type text; clean text; limit_chars integer;
 parent public.policy_documents; amount_text text;
begin
 if spec is null or p_new is null or jsonb_typeof(p_new)<>'object' then raise exception 'runtime_control_invalid' using errcode='22023';end if;
 perform collect_security.runtime_control_check_values(p_family,case when p_old is null then p_new else
  coalesce((select jsonb_object_agg(key,value) from jsonb_each(p_new) where p_old->key is distinct from value),'{}'::jsonb) end);
 if p_old is not null and exists(select 1 from jsonb_array_elements_text(spec->'immutable_after_create') k where p_new->k is distinct from p_old->k) then
  raise exception 'runtime_control_wiring_immutable' using errcode='55000';end if;
 if p_family='support_channels' then
  if p_new->>'channel_type' in ('phone','whatsapp') and (char_length(p_new->>'value') not between 8 and 16 or p_new->>'value' !~ '^\+?[1-9][0-9]+$')
   or p_new->>'channel_type'='email' and (char_length(p_new->>'value')>254 or p_new->>'value' !~ '^[A-Za-z0-9.!#$%&''*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,63}$')
   or p_new->>'channel_type'='url' and not collect_security.runtime_control_https(p_new->>'value') then raise exception 'runtime_control_invalid_support' using errcode='22023';end if;
 end if;
 if p_family='payment_entrypoints' and (p_new->>'is_active')::boolean then
  if p_new->>'country_code' is distinct from 'RW' or p_new->>'currency' is distinct from 'RWF' or p_new->>'network' is distinct from 'mtn_momo'
    or p_new->>'code' is null or p_new->>'code' !~ '^\*182\*8\*1\*41258\*[1-9][0-9]{0,8}#$' then raise exception 'runtime_control_rwanda_route_required' using errcode='22023';end if;
  amount_text:=split_part(p_new->>'code','*',6);amount_text:=replace(amount_text,'#','');
  if p_new->'metadata'->>'amount_rwf' is distinct from amount_text then raise exception 'runtime_control_payment_amount_mismatch' using errcode='22023';end if;
 end if;
 if p_family='collection_type_country_rules' and (p_new->>'enabled')::boolean and p_new->>'country_code' is distinct from 'RW' then raise exception 'runtime_control_rwanda_route_required' using errcode='22023';end if;
 if p_family='feature_flags' and (p_new->>'enabled')::boolean and p_new->>'key' ~* '(bank_transfer|stripe|diaspora|international|foreign)' then raise exception 'runtime_control_rwanda_route_required' using errcode='22023';end if;
 if p_family='system_settings' then
  if p_new->>'key' ~* '(secret|password|credential|api[_-]?key|token|private[_-]?key)' then raise exception 'runtime_control_sensitive_field' using errcode='22023';end if;
  if p_new->>'key'='payments.mode' and p_new->'value' is distinct from '{"rwanda":{"provider":"momo_ussd_sms","currency":"RWF"}}'::jsonb then raise exception 'runtime_control_rwanda_route_required' using errcode='22023';end if;
  if p_new->>'key'='sms.parser.schema_version' and p_new->'value' is distinct from '"collect.sms_parser.v1"'::jsonb then raise exception 'runtime_control_unsupported_parser' using errcode='22023';end if;
 end if;
 if p_old is not null and p_family in ('policy_documents','notification_template_versions') and (p_old->>'status'<>'draft' or p_old->>'published_at' is not null) then
  if (p_new-array['status','updated_at','updated_by','updated_reason']) is distinct from (p_old-array['status','updated_at','updated_by','updated_reason'])
    or p_new->>'status' not in ('published','archived') or (p_old->>'status'='archived' and p_new->>'status'<>'archived') then raise exception 'runtime_control_published_immutable' using errcode='55000';end if;
 end if;
 if p_family='policy_document_sections' then
  select * into parent from public.policy_documents where id=(p_new->>'policy_document_id')::uuid;
  if parent.id is null or parent.status<>'draft' or parent.published_at is not null then raise exception 'runtime_control_published_immutable' using errcode='55000';end if;
 end if;
 if p_family='notification_templates' and p_old is not null and exists(select 1 from public.notification_template_versions where template_key=p_old->>'key' and (status<>'draft' or published_at is not null))
  and (p_new-array['enabled','updated_at','updated_by','updated_reason']) is distinct from (p_old-array['enabled','updated_at','updated_by','updated_reason']) then
  raise exception 'runtime_control_published_immutable' using errcode='55000';end if;
 if p_family='policy_documents' and p_new->>'status'='published' and (p_old is null or p_old->>'status'='draft') then
  if not exists(select 1 from public.policy_document_sections where policy_document_id=(p_new->>'id')::uuid) then raise exception 'runtime_control_policy_sections_required' using errcode='22023';end if;
 end if;
 if p_family='sms_receipt_policies' and not exists(select 1 from public.collections c where c.id=(p_new->>'collection_id')::uuid and c.collection_type='ikimina' and c.archived_at is null) then raise exception 'runtime_control_collection_required' using errcode='22023';end if;
 if p_family='sms_receipt_member_consents' and not exists(select 1 from collect_hybrid.member_records m join collect_hybrid.member_momo_identities i on i.member_id=m.id where m.id=(p_new->>'member_record_id')::uuid and m.lifecycle='active' and m.linked_user_id is null) then raise exception 'runtime_control_member_required' using errcode='22023';end if;
 if p_family='roster_resource_policy' and ((p_new->>'actor_active')::integer>(p_new->>'global_active')::integer
   or (p_new->>'actor_daily_requests')::integer>(p_new->>'global_daily_requests')::integer
   or (p_new->>'actor_daily_bytes')::bigint>(p_new->>'global_daily_bytes')::bigint
   or (p_new->>'actor_daily_cost_units')::bigint>(p_new->>'global_daily_cost_units')::bigint
   or (p_new->>'ai_attempt_cost_units')::bigint>(p_new->>'actor_daily_cost_units')::bigint) then raise exception 'runtime_control_quota_order_invalid' using errcode='22023';end if;
 if p_family='otp_policy' and (p_new->>'global_hourly_limit')::integer>(p_new->>'global_daily_limit')::integer then raise exception 'runtime_control_quota_order_invalid' using errcode='22023';end if;
end $_$;


--
-- Name: shadow_run_json(uuid, timestamp with time zone); Type: FUNCTION; Schema: collect_security; Owner: -
--

CREATE FUNCTION collect_security.shadow_run_json(p_run_id uuid, p_observed_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
declare r collect_security.shadow_supervisor_runs;
  s collect_security.shadow_supervisor_samples;
begin
  select * into r from collect_security.shadow_supervisor_runs where id=p_run_id;
  if r.id is null then return null;end if;
  select * into s from collect_security.shadow_supervisor_samples where run_id=r.id;
  if s.id is not null and s.content_sha256 is distinct from
    encode(extensions.digest(convert_to(s.body::text,'UTF8'),'sha256'),'hex') then
    raise exception 'shadow_integrity_unavailable' using errcode='55000';end if;
  return jsonb_build_object('run_id',r.id,'request_id',r.request_id,
    'fence_version',r.fence_version,'status',case when r.status='running'
      and r.lease_expires_at<=p_observed_at then 'expired' else r.status end,
    'started_at',r.started_at,'lease_expires_at',r.lease_expires_at,
    'sampled_at',s.checked_at,'completed_at',r.completed_at,'summary',s.body->'summary');
end $$;


--
-- Name: grant_pg_cron_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_cron_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
  END IF;
END;
$$;


--
-- Name: FUNCTION grant_pg_cron_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_cron_access() IS 'Grants access to pg_cron';


--
-- Name: grant_pg_graphql_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_graphql_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    func_is_graphql_resolve bool;
BEGIN
    func_is_graphql_resolve = (
        SELECT n.proname = 'resolve'
        FROM pg_event_trigger_ddl_commands() AS ev
        LEFT JOIN pg_catalog.pg_proc AS n
        ON ev.objid = n.oid
    );

    IF func_is_graphql_resolve
    THEN
        -- Update public wrapper to pass all arguments through to the pg_graphql resolve func
        DROP FUNCTION IF EXISTS graphql_public.graphql;
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language sql
        as $$
            select graphql.resolve(
                query := query,
                variables := coalesce(variables, '{}'),
                "operationName" := "operationName",
                extensions := extensions
            );
        $$;

        -- This hook executes when `graphql.resolve` is created. That is not necessarily the last
        -- function in the extension so we need to grant permissions on existing entities AND
        -- update default permissions to any others that are created after `graphql.resolve`
        grant usage on schema graphql to postgres, anon, authenticated, service_role;
        grant select on all tables in schema graphql to postgres, anon, authenticated, service_role;
        grant execute on all functions in schema graphql to postgres, anon, authenticated, service_role;
        grant all on all sequences in schema graphql to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on tables to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on functions to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on sequences to postgres, anon, authenticated, service_role;

        -- Allow postgres role to allow granting usage on graphql and graphql_public schemas to custom roles
        grant usage on schema graphql_public to postgres with grant option;
        grant usage on schema graphql to postgres with grant option;
    END IF;

END;
$_$;


--
-- Name: FUNCTION grant_pg_graphql_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_graphql_access() IS 'Grants access to pg_graphql';


--
-- Name: grant_pg_net_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_net_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
    ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

    ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
    ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

    REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
    REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

    GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
  END IF;
END;
$$;


--
-- Name: FUNCTION grant_pg_net_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_net_access() IS 'Grants access to pg_net';


--
-- Name: pgrst_ddl_watch(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.pgrst_ddl_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.command_tag IN (
      'CREATE SCHEMA', 'ALTER SCHEMA'
    , 'CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO', 'ALTER TABLE'
    , 'CREATE FOREIGN TABLE', 'ALTER FOREIGN TABLE'
    , 'CREATE VIEW', 'ALTER VIEW'
    , 'CREATE MATERIALIZED VIEW', 'ALTER MATERIALIZED VIEW'
    , 'CREATE FUNCTION', 'ALTER FUNCTION'
    , 'CREATE TRIGGER'
    , 'CREATE TYPE', 'ALTER TYPE'
    , 'CREATE RULE'
    , 'COMMENT'
    )
    -- don't notify in case of CREATE TEMP table or other objects created on pg_temp
    AND cmd.schema_name is distinct from 'pg_temp'
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


--
-- Name: pgrst_drop_watch(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.pgrst_drop_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
  LOOP
    IF obj.object_type IN (
      'schema'
    , 'table'
    , 'foreign table'
    , 'view'
    , 'materialized view'
    , 'function'
    , 'trigger'
    , 'type'
    , 'rule'
    )
    AND obj.is_temporary IS false -- no pg_temp objects
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


--
-- Name: set_graphql_placeholder(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.set_graphql_placeholder() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$_$;


--
-- Name: FUNCTION set_graphql_placeholder(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.set_graphql_placeholder() IS 'Reintroduces placeholder function for graphql_public.graphql';


--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: -
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
    raise debug 'PgBouncer auth request: %', p_usename;

    return query
    select 
        rolname::text, 
        case when rolvaliduntil < now() 
            then null 
            else rolpassword::text 
        end 
    from pg_authid 
    where rolname=$1 and rolcanlogin;
end;
$_$;


--
-- Name: collect_admin_country_for_row(text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.collect_admin_country_for_row(p_rpc_name text, p_row jsonb) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
declare
  v_country text := upper(nullif(btrim(coalesce(p_row ->> 'country_code', '')), ''));
  v_rail text := lower(nullif(btrim(coalesce(p_row ->> 'rail', '')), ''));
  v_record_id uuid;
  v_intent_id uuid;
  v_transaction_id uuid;
  v_collection_id uuid;
  v_user_id uuid;
  v_whatsapp_phone text;
  v_platform_sponsored boolean := false;
begin
  if v_country ~ '^[A-Z]{2}$' then
    return v_country;
  end if;

  if v_rail = 'rw_momo' or p_rpc_name = 'admin_list_collect_payees' then
    return 'RW';
  end if;

  if p_rpc_name = 'admin_list_collections' then
    v_record_id := private.collect_admin_try_uuid(p_row ->> 'id');
    select collection.creator_user_id, collection.is_platform_sponsored
      into v_user_id, v_platform_sponsored
    from public.collections collection
    where collection.id = v_record_id;
    if v_platform_sponsored then return 'RW'; end if;
  elsif p_rpc_name = 'admin_list_notifications' then
    v_record_id := private.collect_admin_try_uuid(p_row ->> 'id');
    select event.user_id into v_user_id
    from public.notification_events event
    where event.id = v_record_id;
  elsif p_rpc_name in (
    'admin_list_collect_transactions',
    'admin_list_collect_reconciliations',
    'admin_list_collect_ledgers'
  ) then
    v_intent_id := private.collect_admin_try_uuid(p_row ->> 'payment_intent_id');
    v_transaction_id := private.collect_admin_try_uuid(p_row ->> 'transaction_id');
    v_collection_id := private.collect_admin_try_uuid(p_row ->> 'collection_id');

    if v_intent_id is not null then
      select intent.contributor_user_id into v_user_id
      from public.bank_transfer_intents intent
      where intent.id = v_intent_id;
    end if;

    if v_user_id is null and nullif(btrim(coalesce(p_row ->> 'reference', '')), '') is not null then
      select intent.contributor_user_id into v_user_id
      from public.bank_transfer_intents intent
      where upper(intent.transfer_reference) = upper(btrim(p_row ->> 'reference'))
      order by intent.created_at desc
      limit 1;
    end if;

    if v_user_id is null and v_transaction_id is not null then
      select allocation.contributor_user_id into v_user_id
      from public.bank_transaction_allocations allocation
      where allocation.bank_transaction_id = v_transaction_id
      order by allocation.created_at desc
      limit 1;
    end if;

    if v_user_id is null and v_collection_id is not null then
      select collection.creator_user_id into v_user_id
      from public.collections collection
      where collection.id = v_collection_id;
    end if;
  end if;

  if v_user_id is not null then
    select
      upper(nullif(btrim(profile.country_code), '')),
      profile.whatsapp_phone
      into v_country, v_whatsapp_phone
    from public.profiles profile
    where profile.id = v_user_id;
  end if;

  if v_country ~ '^[A-Z]{2}$' then return v_country; end if;
  if regexp_replace(coalesce(v_whatsapp_phone, ''), '[^0-9+]', '', 'g') like '+250%' then
    return 'RW';
  end if;
  if regexp_replace(coalesce(v_whatsapp_phone, ''), '[^0-9+]', '', 'g') like '+356%' then
    return 'MT';
  end if;

  -- ZZ is an internal safe bucket for an unresolved non-Rwanda/non-Malta row.
  -- It is displayed only through the "Other countries" scope.
  return 'ZZ';
end;
$_$;


--
-- Name: collect_admin_try_uuid(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.collect_admin_try_uuid(p_value text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  return nullif(btrim(coalesce(p_value, '')), '')::uuid;
exception
  when invalid_text_representation then return null;
end;
$$;


--
-- Name: _admin_list_people_by_membership(boolean, text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._admin_list_people_by_membership(p_has_active_group boolean, p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('users.read');
  with base as (
    select
      profile.id,
      'Collect ID ' || profile.public_id as title,
      public.mask_phone(profile.whatsapp_phone) as subtitle,
      case
        when (
        collect_admin_access.approved_identity(profile.id)
        and exists (
          select 1 from public.admin_user_roles assignment
          join public.admin_roles role on role.id = assignment.role_id
          where assignment.user_id = profile.id
            and assignment.revoked_at is null
            and role.name = 'platform_owner'
        )
      ) then 'admin'
        when p_has_active_group then 'active'
        else 'registered'
      end as status,
      profile.created_at,
      profile.updated_at,
      coalesce(member_count.active_groups, 0)::integer as active_groups,
      jsonb_build_object(
        'public_id', profile.public_id,
        'display_name', profile.display_name,
        'whatsapp_masked', public.mask_phone(profile.whatsapp_phone),
        'country_code', coalesce(profile.country_code, 'RW'),
        'currency_code', coalesce(profile.currency_code, 'RWF'),
        'momo_provider', profile.momo_provider,
        'momo_masked', public.mask_phone(profile.momo_number),
        'has_revolut_profile',
          profile.revolut_link is not null
          and profile.revolut_account is not null,
        'account_last4', case
          when profile.revolut_account is null then null
          else right(regexp_replace(
            profile.revolut_account, '[^A-Za-z0-9]', '', 'g'
          ), 4)
        end,
        'active_groups', coalesce(member_count.active_groups, 0),
        'is_platform_admin', (
        collect_admin_access.approved_identity(profile.id)
        and exists (
          select 1 from public.admin_user_roles assignment
          join public.admin_roles role on role.id = assignment.role_id
          where assignment.user_id = profile.id
            and assignment.revoked_at is null
            and role.name = 'platform_owner'
        )
      ),
        'updated_at', profile.updated_at
      ) as extra
    from public.profiles profile
    left join lateral (
      select count(distinct membership.collection_id) as active_groups
      from public.collection_members membership
      join public.collections collection
        on collection.id = membership.collection_id
      where (
          membership.user_id = profile.id
          or collect_hybrid.member_record_belongs_to_user(
            membership.member_record_id, profile.id
          )
        )
        and membership.status = 'active'
        and collection.archived_at is null
    ) member_count on true
    where case
      when p_has_active_group then coalesce(member_count.active_groups, 0) > 0
      else coalesce(member_count.active_groups, 0) = 0
    end
  ), filtered as (
    select * from base
    where (
      nullif(btrim(coalesce(p_status, '')), '') is null
      or status = btrim(p_status)
    ) and (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or title ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'display_name', '')
        ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'whatsapp_masked', '')
        ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'country_code', '')
        ilike '%' || btrim(p_search) || '%'
    )
  ), counted as (
    select filtered.*,
      row_number() over (order by
        case when p_sort = 'created_at_asc' then created_at end asc nulls last,
        created_at desc, id
      ) as ordinal
    from filtered
    order by ordinal
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', id,
        'title', title,
        'subtitle', subtitle,
        'status', status,
        'amount', active_groups::text || ' groups',
        'created_at', created_at
      ) || extra order by ordinal
    ), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into result
  from counted;
  return result;
end;
$$;


--
-- Name: _admin_row(uuid, text, text, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._admin_row(p_id uuid, p_title text, p_subtitle text DEFAULT ''::text, p_status text DEFAULT 'unknown'::text, p_amount text DEFAULT ''::text, p_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_extra jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'id', p_id,
    'title', coalesce(p_title, 'Record'),
    'subtitle', coalesce(p_subtitle, ''),
    'status', coalesce(p_status, 'unknown'),
    'amount', coalesce(p_amount, ''),
    'created_at', p_created_at
  ) || coalesce(p_extra, '{}'::jsonb);
$$;


--
-- Name: _authenticated_momo_phone_hash(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._authenticated_momo_phone_hash(p_user_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $_$
declare
  profile_digits text;
  auth_digits text;
  canonical_profile_phone text;
  canonical_auth_phone text;
  auth_phone_confirmed_at timestamptz;
begin
  select
    regexp_replace(coalesce(profile.momo_number, ''), '[^0-9]', '', 'g'),
    regexp_replace(coalesce(auth_user.phone, ''), '[^0-9]', '', 'g'),
    auth_user.phone_confirmed_at
    into profile_digits, auth_digits, auth_phone_confirmed_at
  from public.profiles profile
  join auth.users auth_user on auth_user.id = profile.id
  where profile.id = p_user_id
    and auth_user.deleted_at is null
    and profile.country_code = 'RW';

  if profile_digits ~ '^250[0-9]{9}$' then
    canonical_profile_phone := '+' || profile_digits;
  elsif profile_digits ~ '^0[0-9]{9}$' then
    canonical_profile_phone := '+250' || substr(profile_digits, 2);
  elsif profile_digits ~ '^[0-9]{9}$' then
    canonical_profile_phone := '+250' || profile_digits;
  else
    return null;
  end if;

  if auth_digits ~ '^250[0-9]{9}$' then
    canonical_auth_phone := '+' || auth_digits;
  elsif auth_digits ~ '^0[0-9]{9}$' then
    canonical_auth_phone := '+250' || substr(auth_digits, 2);
  elsif auth_digits ~ '^[0-9]{9}$' then
    canonical_auth_phone := '+250' || auth_digits;
  else
    return null;
  end if;

  if auth_phone_confirmed_at is null
     or canonical_profile_phone <> canonical_auth_phone then
    return null;
  end if;

  return encode(extensions.digest(canonical_auth_phone, 'sha256'), 'hex');
end;
$_$;


--
-- Name: _create_roster_import_source_v142(uuid, uuid, uuid, text, text, bigint, text, text, text, text, bigint, boolean, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._create_roster_import_source_v142(p_actor_id uuid, p_session_id uuid, p_request_id uuid, p_source_kind text, p_original_sha256 text, p_original_size bigint, p_client_filename text, p_declared_mime text, p_detected_type text, p_derived_sha256 text, p_derived_size bigint, p_ai_consent boolean, p_consent_version text, p_ai_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
   begin perform collect_hybrid.guard_roster_service_recovery((select id from collect_hybrid.roster_import_sources where request_id=p_request_id)); return collect_hybrid._create_roster_import_source_v142_guarded_149(p_actor_id,p_session_id,p_request_id,p_source_kind,p_original_sha256,p_original_size,p_client_filename,p_declared_mime,p_detected_type,p_derived_sha256,p_derived_size,p_ai_consent,p_consent_version,p_ai_metadata); end $$;


--
-- Name: _lock_notification_registration_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._lock_notification_registration_session() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare session_text text:=auth.jwt()->>'session_id'; session_id uuid; begin
  perform public._lock_notification_session_gate();
  if auth.role() is distinct from 'authenticated' or auth.uid() is null
    or session_text is null or session_text !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
    raise exception 'notification_registration_session_required' using errcode='42501';
  end if;
  session_id:=session_text::uuid;
  -- SHARE blocks both deletion and non-key revocation updates before we lock
  -- a token. A late registration sees the deletion after waiting and refuses.
  perform 1 from auth.sessions s where s.id=session_id and s.user_id=auth.uid() for share;
  if not found or not public._notification_session_is_live(session_id,auth.uid()) then
    raise exception 'notification_registration_session_required' using errcode='42501';
  end if;
  return session_id;
end $_$;


--
-- Name: _lock_notification_session_gate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._lock_notification_session_gate() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select pg_catalog.pg_advisory_xact_lock_shared(193517,141);
$$;


--
-- Name: profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.profiles (
    id uuid NOT NULL,
    public_id character(6) NOT NULL,
    display_name text,
    avatar_url text,
    whatsapp_phone text,
    momo_number text,
    momo_number_hash text,
    anonymity_default text DEFAULT 'anonymous'::text NOT NULL,
    is_platform_admin boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    momo_pay_code text,
    country_code text,
    currency_code text,
    revolut_name text,
    momo_provider text,
    momo_number_verified_at timestamp with time zone,
    revolut_link text,
    revolut_account text,
    CONSTRAINT profiles_anonymity_default_check CHECK ((anonymity_default = ANY (ARRAY['anonymous'::text, 'public_id'::text, 'display_name'::text]))),
    CONSTRAINT profiles_country_code_format CHECK (((country_code IS NULL) OR (country_code ~ '^[A-Z]{2}$'::text))),
    CONSTRAINT profiles_currency_code_format CHECK (((currency_code IS NULL) OR (currency_code ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT profiles_momo_number_hash_matches CHECK (((momo_number_hash IS NULL) OR ((momo_number ~ '^07[2389][0-9]{7}$'::text) AND (momo_number_hash = encode(extensions.digest(('+250'::text || substr(momo_number, 2)), 'sha256'::text), 'hex'::text))) OR ((momo_number ~ '^\\+2507[2389][0-9]{7}$'::text) AND (momo_number_hash = encode(extensions.digest(momo_number, 'sha256'::text), 'hex'::text))))),
    CONSTRAINT profiles_momo_number_rw_format CHECK (((momo_number IS NULL) OR (momo_number ~ '^07[2389][0-9]{7}$'::text) OR (momo_number ~ '^\+2507[2389][0-9]{7}$'::text))),
    CONSTRAINT profiles_momo_pay_code_format CHECK (((momo_pay_code IS NULL) OR (momo_pay_code ~ '^[0-9]{4,9}$'::text))),
    CONSTRAINT profiles_momo_provider_check CHECK (((momo_provider IS NULL) OR (momo_provider = ANY (ARRAY['mtn_momo'::text, 'airtel_money'::text])))),
    CONSTRAINT profiles_momo_provider_number_match CHECK (((momo_provider IS NULL) OR (momo_number IS NULL) OR ((momo_provider = 'mtn_momo'::text) AND (momo_number ~ '^(\+250|0)7[89][0-9]{7}$'::text)) OR ((momo_provider = 'airtel_money'::text) AND (momo_number ~ '^(\+250|0)7[23][0-9]{7}$'::text)))),
    CONSTRAINT profiles_public_id_digits CHECK ((public_id ~ '^[0-9]{6}$'::text)),
    CONSTRAINT profiles_revolut_account_length CHECK (((revolut_account IS NULL) OR ((char_length(btrim(revolut_account)) >= 4) AND (char_length(btrim(revolut_account)) <= 120)))),
    CONSTRAINT profiles_revolut_link_format CHECK (((revolut_link IS NULL) OR (revolut_link ~ '^https://([a-z0-9-]+\.)?revolut\.me/[A-Za-z0-9._~-]+/?$'::text))),
    CONSTRAINT profiles_revolut_name_length CHECK (((revolut_name IS NULL) OR ((char_length(TRIM(BOTH FROM revolut_name)) >= 2) AND (char_length(TRIM(BOTH FROM revolut_name)) <= 100))))
);


