--
-- Name: admin_list_collect_ledgers(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_collect_ledgers(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('ledger.read');
  with unified as (
    select
      'momo:' || entry.id::text as id,
      entry.external_reference as title,
      case when entry.entry_type = 'reversal'
        then 'Rwanda · compensating MoMo reversal'
        else 'Rwanda · provider-confirmed MoMo receipt' end as subtitle,
      case when entry.entry_type = 'reversal'
        then 'reversed' else 'balanced' end as status,
      ('RWF ' || case when entry.entry_type = 'reversal' then '-' else '' end
        || to_char(entry.amount_rwf, 'FM999G999G999G999') || ' =') as amount,
      entry.created_at,
      jsonb_build_object(
        'rail', 'rw_momo',
        'payment_id', entry.payment_id,
        'journal_entry_id', entry.id,
        'collection_id', entry.collection_id,
        'debit_total', totals.debit_total,
        'credit_total', totals.credit_total,
        'currency', 'RWF',
        'line_count', totals.line_count,
        'entry_type', entry.entry_type
      ) as extra
    from collect_hybrid.momo_journal_entries entry
    join lateral (
      select
        coalesce(sum(line.amount_rwf) filter (
          where line.direction = 'debit'
        ), 0)::bigint as debit_total,
        coalesce(sum(line.amount_rwf) filter (
          where line.direction = 'credit'
        ), 0)::bigint as credit_total,
        count(*)::bigint as line_count
      from collect_hybrid.momo_journal_lines line
      where line.journal_entry_id = entry.id
    ) totals on true
    union all
    select
      'diaspora:' || journal.id::text,
      coalesce(journal.external_reference, 'Diaspora journal ' || right(journal.id::text, 8)),
      'Diaspora · ' || journal.description,
      case when totals.debit_total = totals.credit_total and totals.debit_total > 0
        then 'balanced' else 'unbalanced' end,
      journal.currency || ' '
        || to_char(totals.debit_total::numeric / 100, 'FM999G999G999D00') || ' =',
      journal.posted_at,
      jsonb_build_object(
        'rail', 'diaspora_account',
        'journal_entry_id', journal.id,
        'transaction_id', journal.bank_transaction_id,
        'collection_id', journal.collection_id,
        'debit_total', totals.debit_total,
        'credit_total', totals.credit_total,
        'currency', journal.currency,
        'line_count', totals.line_count
      )
    from public.journal_entries journal
    join lateral (
      select
        coalesce(sum(line.amount_minor) filter (
          where line.direction = 'debit'
        ), 0)::bigint as debit_total,
        coalesce(sum(line.amount_minor) filter (
          where line.direction = 'credit'
        ), 0)::bigint as credit_total,
        count(*)::bigint as line_count
      from public.journal_lines line
      where line.journal_entry_id = journal.id
    ) totals on true
  ), filtered as (
    select * from unified
    where (nullif(btrim(coalesce(p_status, '')), '') is null
        or status = btrim(p_status))
      and (nullif(btrim(coalesce(p_search, '')), '') is null
        or title ilike '%' || btrim(p_search) || '%'
        or subtitle ilike '%' || btrim(p_search) || '%')
  ), counted as (
    select filtered.*, count(*) over () as total_count
    from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(jsonb_build_object(
      'id', id,
      'title', title,
      'subtitle', subtitle,
      'status', status,
      'amount', amount,
      'created_at', created_at
    ) || extra order by created_at desc), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  ) into result
  from counted;
  return result;
end;
$$;


--
-- Name: FUNCTION admin_list_collect_ledgers(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_list_collect_ledgers(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) IS 'Country-aware Collect ledger queue with explicit stable JSON projection names.';


--
-- Name: admin_list_collect_payees(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_collect_payees(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('receivers.read');

  with official_payees as (
    select
      'momo:' || receiver.id::text as id,
      receiver.label as title,
      collection.title || ' · ' || case receiver.network
        when 'mtn_momo' then 'MTN MoMo'
        when 'airtel_money' then 'Airtel Money'
        else 'MoMo'
      end || ' · code ' || receiver.momo_number || ' · route locked' as subtitle,
      case when receiver.is_active then 'active' else 'inactive' end as status,
      'Rwanda · MoMo USSD' as amount,
      receiver.created_at,
      jsonb_build_object(
        'rail', 'rw_momo',
        'payee_id', receiver.id,
        'collection_id', receiver.collection_id,
        'collection_title', collection.title,
        'provider', receiver.network,
        'momo_code', receiver.momo_number,
        'route_locked', true,
        'is_platform_sponsored', true
      ) as extra
    from public.collection_receivers receiver
    join public.collections collection on collection.id = receiver.collection_id
    where collection.is_platform_sponsored
      and collection.archived_at is null
  ), filtered as (
    select *
    from official_payees
    where (
      nullif(btrim(coalesce(p_status, '')), '') is null
      or status = btrim(p_status)
    ) and (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or title ilike '%' || btrim(p_search) || '%'
      or subtitle ilike '%' || btrim(p_search) || '%'
    )
  ), counted as (
    select filtered.*, count(*) over () as total_count
    from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', id,
        'title', title,
        'subtitle', subtitle,
        'status', status,
        'amount', amount,
        'created_at', created_at
      ) || extra
      order by created_at desc
    ), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  )
  into result
  from counted;

  return result;
end;
$$;


--
-- Name: admin_list_collect_reconciliations(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_collect_reconciliations(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('payment_events.read');

  with unified as (
    select
      'momo:' || event.id::text as id,
      coalesce(event.transaction_id, 'Unallocated MoMo receipt') as title,
      'Rwanda · ' || coalesce(collection.title, 'Select a group payee') as subtitle,
      event.allocation_status::text as status,
      case when event.amount_rwf is null then ''
        else 'RWF ' || to_char(event.amount_rwf, 'FM999G999G999G999') end as amount,
      event.created_at,
      jsonb_build_object(
        'rail', 'rw_momo',
        'event_id', event.id,
        'transaction_id', null,
        'collection_id', coalesce(event.collection_id, candidate.collection_id),
        'payment_intent_id', candidate.id,
        'can_allocate', event.id is not null,
        'reference', event.transaction_id,
        'age', now() - event.created_at
      ) as extra
    from public.parsed_payment_events event
    left join public.collections collection on collection.id = event.collection_id
    left join lateral (
      select intent.id, intent.collection_id
      from public.payment_intents intent
      where intent.status = 'pending'
        and intent.expires_at > now()
        and intent.expected_amount_rwf = event.amount_rwf
        and (event.collection_id is null or intent.collection_id = event.collection_id)
        and (
          (event.sender_phone_hash is not null and intent.sender_phone_hash = event.sender_phone_hash)
          or (event.detected_user_public_id is not null
            and intent.contributor_public_id = event.detected_user_public_id)
        )
      order by intent.created_at desc
      limit 1
    ) candidate on true
    where event.allocation_status in ('unallocated', 'ambiguous', 'needs_review')

    union all

    select
      'diaspora:' || bank_transaction.id::text,
      coalesce(bank_transaction.transfer_reference,
        bank_transaction.bank_transaction_id, 'Unallocated account receipt'),
      'Diaspora · ' || coalesce(collection.title, 'Select a group payee'),
      coalesce(exception.exception_type, bank_transaction.status),
      bank_transaction.currency || ' ' ||
        to_char(bank_transaction.amount_minor::numeric / 100, 'FM999G999G999D00'),
      bank_transaction.created_at,
      jsonb_build_object(
        'rail', 'diaspora_account',
        'event_id', null,
        'transaction_id', bank_transaction.id,
        'collection_id', candidate.collection_id,
        'payment_intent_id', candidate.id,
        'can_allocate', bank_transaction.status not in ('reconciled', 'returned'),
        'reference', bank_transaction.transfer_reference,
        'age', now() - bank_transaction.created_at
      )
    from public.bank_transactions bank_transaction
    left join public.bank_transaction_allocations allocation
      on allocation.bank_transaction_id = bank_transaction.id
    left join lateral (
      select intent.id, intent.collection_id
      from public.bank_transfer_intents intent
      where intent.status not in ('reconciled', 'returned', 'cancelled', 'expired')
        and intent.currency = bank_transaction.currency
        and intent.amount_minor = bank_transaction.amount_minor
        and (bank_transaction.transfer_reference is null
          or intent.transfer_reference = bank_transaction.transfer_reference)
      order by intent.created_at desc
      limit 1
    ) candidate on true
    left join public.collections collection on collection.id = candidate.collection_id
    left join lateral (
      select reconciliation.exception_type
      from public.reconciliation_exceptions reconciliation
      where reconciliation.bank_transaction_id = bank_transaction.id
        and reconciliation.status in ('open', 'reviewing')
      order by reconciliation.created_at desc limit 1
    ) exception on true
    where allocation.id is null
      and bank_transaction.status not in ('reconciled', 'returned')

    union all

    select
      'diaspora-exception:' || exception.id::text,
      replace(exception.exception_type, '_', ' '),
      'Diaspora · reconciliation exception without a canonical transaction',
      exception.status,
      '',
      exception.created_at,
      jsonb_build_object(
        'rail', 'diaspora_exception',
        'event_id', null,
        'transaction_id', null,
        'collection_id', null,
        'payment_intent_id', exception.bank_transfer_intent_id,
        'can_allocate', false,
        'age', now() - exception.created_at
      )
    from public.reconciliation_exceptions exception
    where exception.bank_transaction_id is null
      and exception.status in ('open', 'reviewing')
  ), filtered as (
    select * from unified
    where (
      nullif(btrim(coalesce(p_status, '')), '') is null
      or status = btrim(p_status)
    ) and (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or title ilike '%' || btrim(p_search) || '%'
      or subtitle ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'reference', '') ilike '%' || btrim(p_search) || '%'
    )
  ), counted as (
    select filtered.*, count(*) over () as total_count
    from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', id, 'title', title, 'subtitle', subtitle,
        'status', status, 'amount', amount, 'created_at', created_at
      ) || extra order by created_at desc
    ), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  ) into result from counted;
  return result;
end;
$$;


--
-- Name: admin_list_collect_transactions(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_collect_transactions(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('payments.read');

  with unified as (
    select
      'momo:' || sms.id::text as id,
      coalesce(event.transaction_id, 'Receipt ' || right(sms.body_hash, 8)) as title,
      'Rwanda · ' || case event.network
        when 'mtn_momo' then 'MTN MoMo'
        when 'airtel_money' then 'Airtel Money'
        else 'MoMo SMS'
      end || ' · ' || coalesce(collection.title, 'Payee not linked') as subtitle,
      coalesce(event.allocation_status::text, sms.parse_status) as status,
      case when event.amount_rwf is null then ''
        else 'RWF ' || to_char(event.amount_rwf, 'FM999G999G999G999') end as amount,
      coalesce(sms.received_at_device, sms.ingested_at) as created_at,
      event.amount_rwf::numeric as sort_amount,
      jsonb_build_object(
        'rail', 'rw_momo',
        'source_label', case event.network
          when 'mtn_momo' then 'MTN MoMo receipt SMS'
          when 'airtel_money' then 'Airtel Money receipt SMS'
          else 'MoMo receipt SMS'
        end,
        'raw_sms_id', sms.id,
        'event_id', event.id,
        'payment_id', payment.id,
        'collection_id', coalesce(payment.collection_id, event.collection_id, sms.collection_id),
        'payment_intent_id', payment.payment_intent_id,
        'reference', event.transaction_id,
        'sender_masked', public.collect_admin_mask_sender(sms.raw_sender),
        'group_name', collection.title,
        'payee_label', receiver.label
      ) as extra
    from public.raw_payment_sms sms
    left join public.parsed_payment_events event on event.raw_sms_id = sms.id
    left join public.payments payment on payment.parsed_event_id = event.id
    left join public.collections collection
      on collection.id = coalesce(payment.collection_id, event.collection_id, sms.collection_id)
    left join lateral (
      select route.label
      from public.collection_receivers route
      where route.collection_id = collection.id and route.is_active
      order by route.created_at desc
      limit 1
    ) receiver on true

    union all

    select
      'diaspora:' || evidence.id::text,
      coalesce(bank_transaction.bank_transaction_id, event.transfer_reference,
        'Account receipt ' || right(evidence.body_hash, 8)),
      'Diaspora · ' || upper(evidence.channel) || ' · ' ||
        coalesce(collection.title, destination.beneficiary_name, 'Payee not linked'),
      coalesce(event.allocation_status, bank_transaction.status, evidence.parse_status),
      case when coalesce(bank_transaction.amount_minor, event.amount_minor) is null then ''
        else coalesce(bank_transaction.currency, event.currency, 'EUR') || ' ' ||
          to_char(coalesce(bank_transaction.amount_minor, event.amount_minor)::numeric / 100,
            'FM999G999G999D00') end,
      evidence.received_at,
      coalesce(bank_transaction.amount_minor, event.amount_minor)::numeric,
      jsonb_build_object(
        'rail', 'diaspora_account',
        'source_label', 'Revolut EUR account transfer',
        'raw_bank_event_id', event.id,
        'raw_evidence_id', evidence.id,
        'transaction_id', bank_transaction.id,
        'collection_id', allocation.collection_id,
        'payment_intent_id', allocation.bank_transfer_intent_id,
        'reference', coalesce(bank_transaction.transfer_reference, event.transfer_reference),
        'sender_masked', public.collect_admin_mask_sender(evidence.raw_sender),
        'group_name', collection.title,
        'payee_label', destination.beneficiary_name
      )
    from public.raw_payment_evidence evidence
    left join public.bank_evidence_events event on event.raw_evidence_id = evidence.id
    left join public.payment_evidence_links evidence_link
      on evidence_link.evidence_event_id = event.id
    left join public.bank_transactions bank_transaction
      on bank_transaction.id = evidence_link.bank_transaction_id
    left join public.bank_transaction_allocations allocation
      on allocation.bank_transaction_id = bank_transaction.id
    left join public.collections collection on collection.id = allocation.collection_id
    left join public.bank_transfer_destinations destination
      on destination.id = bank_transaction.destination_id
  ), filtered as (
    select * from unified
    where (
      nullif(btrim(coalesce(p_status, '')), '') is null
      or status = btrim(p_status)
    ) and (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or title ilike '%' || btrim(p_search) || '%'
      or subtitle ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'reference', '') ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'group_name', '') ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'payee_label', '') ilike '%' || btrim(p_search) || '%'
    )
  ), counted as (
    select filtered.*, count(*) over () as total_count
    from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      case when p_sort = 'amount_asc' then sort_amount end asc nulls last,
      case when p_sort = 'amount_desc' then sort_amount end desc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', id, 'title', title, 'subtitle', subtitle,
        'status', status, 'amount', amount, 'created_at', created_at
      ) || extra order by created_at desc
    ), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  ) into result from counted;
  return result;
end;
$$;


--
-- Name: admin_list_collections(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_collections(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.admin_list_collections(
    p_search,
    p_status,
    100,
    0,
    'created_at_desc'
  );
$$;


--
-- Name: admin_list_collections(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_collections(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('collections.read');

  with base as (
    select
      collection.id,
      collection.title,
      coalesce(collection.purpose_label, collection.category, 'Community group') as subtitle,
      case
        when collection.archived_at is not null then 'archived'
        when collection.public_status = 'public_approved' then 'public_approved'
        else 'private'
      end as status,
      collection.created_at,
      collection.updated_at,
      coalesce(member_count.active_members, 0)::integer as active_members,
      jsonb_build_object(
        'slug', collection.slug,
        'collection_type', collection.collection_type,
        'category_subtype', collection.category_subtype,
        'purpose_label', collection.purpose_label,
        'visibility', case
          when collection.public_status = 'public_approved' then 'public'
          else 'private'
        end,
        'is_platform_sponsored', collection.is_platform_sponsored,
        'creator_label', case
          when collection.is_platform_sponsored then 'Collect platform'
          else 'Collect ID ' || coalesce(profile.public_id, 'unavailable')
        end,
        'active_members', coalesce(member_count.active_members, 0),
        'receiver_label', receiver.label,
        'receiver_network', receiver.network,
        'momo_identifier', case
          when receiver.momo_number is null then null
          when collection.is_platform_sponsored then receiver.momo_number
          else public.mask_phone(receiver.momo_number)
        end,
        'route_ready', receiver.momo_number is not null,
        'updated_at', collection.updated_at
      ) as extra
    from public.collections collection
    left join public.profiles profile on profile.id = collection.creator_user_id
    left join lateral (
      select route.label, route.momo_number, route.network
      from public.collection_receivers route
      where route.collection_id = collection.id and route.is_active
      order by route.created_at desc
      limit 1
    ) receiver on true
    left join lateral (
      select count(*) as active_members
      from public.collection_members member
      where member.collection_id = collection.id and member.status = 'active'
    ) member_count on true
  ), filtered as (
    select * from base
    where (
      nullif(btrim(coalesce(p_status, '')), '') is null
      or status = btrim(p_status)
    ) and (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or title ilike '%' || btrim(p_search) || '%'
      or subtitle ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'slug', '') ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'creator_label', '') ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'receiver_label', '') ilike '%' || btrim(p_search) || '%'
    )
  ), counted as (
    select filtered.*, count(*) over () as total_count
    from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', id,
        'title', title,
        'subtitle', subtitle,
        'status', status,
        'amount', active_members::text || ' members',
        'created_at', created_at
      ) || extra order by created_at desc
    ), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  ) into result from counted;
  return result;
end;
$$;


--
-- Name: admin_list_country_scoped(text, text, text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_country_scoped(p_rpc_name text, p_country text, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_allowed_rpcs constant text[] := array[
    'admin_list_collections',
    'admin_list_users',
    'admin_list_members',
    'admin_list_non_member_users',
    'admin_list_collect_payees',
    'admin_list_collect_transactions',
    'admin_list_collect_reconciliations',
    'admin_list_collect_ledgers',
    'admin_list_notifications'
  ];
  v_country text := upper(btrim(coalesce(p_country, '')));
  v_page_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);
  v_page_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_source_offset integer := 0;
  v_source_total integer := 0;
  v_batch jsonb;
  v_all_rows jsonb := '[]'::jsonb;
  v_result jsonb;
begin
  if not (p_rpc_name = any(v_allowed_rpcs)) then
    raise exception 'Unsupported country-scoped Admin list';
  end if;
  if v_country not in ('RW', 'MT', 'OTHER') then
    raise exception 'Country scope must be RW, MT, or OTHER';
  end if;

  loop
    v_batch := case p_rpc_name
      when 'admin_list_collections' then public.admin_list_collections(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_users' then public.admin_list_users(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_members' then public.admin_list_members(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_non_member_users' then public.admin_list_non_member_users(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_collect_payees' then public.admin_list_collect_payees(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_collect_transactions' then public.admin_list_collect_transactions(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_collect_reconciliations' then public.admin_list_collect_reconciliations(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_collect_ledgers' then public.admin_list_collect_ledgers(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_notifications' then public.admin_list_notifications(
        p_search, p_status, 100, v_source_offset, p_sort)
    end;

    v_source_total := greatest(
      v_source_total,
      coalesce(nullif(v_batch ->> 'total', '')::integer, 0)
    );
    v_all_rows := v_all_rows || coalesce(v_batch -> 'rows', '[]'::jsonb);
    exit when jsonb_array_length(coalesce(v_batch -> 'rows', '[]'::jsonb)) = 0
      or v_source_offset + 100 >= v_source_total;
    v_source_offset := v_source_offset + 100;
  end loop;

  with enriched as (
    select
      source.ordinality,
      source.value || jsonb_build_object(
        'country_code',
        private.collect_admin_country_for_row(p_rpc_name, source.value)
      ) as row
    from jsonb_array_elements(v_all_rows) with ordinality as source(value, ordinality)
  ), filtered as (
    select enriched.*
    from enriched
    where case v_country
      when 'RW' then enriched.row ->> 'country_code' = 'RW'
      when 'MT' then enriched.row ->> 'country_code' = 'MT'
      else enriched.row ->> 'country_code' not in ('RW', 'MT')
    end
  ), paged as (
    select filtered.*
    from filtered
    order by filtered.ordinality
    limit v_page_limit offset v_page_offset
  )
  select jsonb_build_object(
    'rows', coalesce(
      (select jsonb_agg(paged.row order by paged.ordinality) from paged),
      '[]'::jsonb
    ),
    'total', (select count(*) from filtered)
  ) into v_result;

  return coalesce(v_result, jsonb_build_object('rows', '[]'::jsonb, 'total', 0));
end;
$$;


--
-- Name: FUNCTION admin_list_country_scoped(p_rpc_name text, p_country text, p_search text, p_status text, p_limit integer, p_offset integer, p_sort text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_list_country_scoped(p_rpc_name text, p_country text, p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) IS 'Country-aware Admin list wrapper. Resolves country from authoritative profiles and financial relationships before pagination.';


--
-- Name: admin_list_feature_flags(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_feature_flags(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 perform collect_security.runtime_control_actor('feature_flags',true);
 if char_length(coalesce(p_search,''))>200 or p_status is not null and p_status not in ('enabled','disabled') then raise exception 'runtime_control_query_invalid' using errcode='22023';end if;
 return jsonb_build_object('rows',coalesce((select jsonb_agg(public._admin_row(md5('collect.runtime-control.row.v1:feature_flags:'||flag.key)::uuid,flag.key,flag.description,case when flag.enabled then 'enabled' else 'disabled' end,'',flag.updated_at)||jsonb_build_object('extra',jsonb_build_object('runtime_revision',head.revision)) order by flag.key)
 from public.feature_flags flag join collect_security.runtime_control_heads head on head.family='feature_flags' and head.identity=jsonb_build_object('key',flag.key)
 where (p_search is null or flag.key ilike '%'||p_search||'%' or flag.description ilike '%'||p_search||'%') and (p_status is null or p_status='enabled' and flag.enabled or p_status='disabled' and not flag.enabled)),'[]'::jsonb));
end $$;


--
-- Name: admin_list_hybrid_sms_receipts(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_hybrid_sms_receipts(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  bounded_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);
  bounded_offset integer := greatest(coalesce(p_offset, 0), 0);
  result jsonb;
begin
  perform public.assert_admin_permission('notifications.read');
  with filtered as (
    select
      outbox.*,
      collection.title as collection_title,
      member.collect_id
    from collect_hybrid.sms_notification_outbox outbox
    join public.collections collection on collection.id = outbox.collection_id
    join collect_hybrid.member_records member on member.id = outbox.member_record_id
    where (nullif(btrim(coalesce(p_status, '')), '') is null
        or outbox.state = btrim(p_status))
      and (
        nullif(btrim(coalesce(p_search, '')), '') is null
        or collection.title ilike '%' || btrim(p_search) || '%'
        or member.collect_id = btrim(p_search)
        or outbox.reference ilike '%' || btrim(p_search) || '%'
        or right(outbox.destination_e164, 3) = btrim(p_search)
      )
  ), ordered as (
    select filtered.*,
      row_number() over (
        order by
          case when coalesce(p_sort, 'created_at_desc') = 'created_at_asc'
            then filtered.created_at end asc nulls last,
          filtered.created_at desc,
          filtered.id
      ) as admin_rank
    from filtered
    order by
      case when coalesce(p_sort, 'created_at_desc') = 'created_at_asc'
        then filtered.created_at end asc nulls last,
      filtered.created_at desc,
      filtered.id
    limit bounded_limit offset bounded_offset
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(public._admin_row(
      ordered.id,
      ordered.collection_title || ' receipt',
      'Collect ID ' || ordered.collect_id || ' • '
        || left(ordered.destination_e164, 4) || '•••'
        || right(ordered.destination_e164, 3),
      ordered.state,
      'RWF ' || to_char(ordered.amount_rwf, 'FM999,999,999,999,999,990'),
      ordered.created_at,
      jsonb_build_object(
        'collection_id', ordered.collection_id,
        'member_collect_id', ordered.collect_id,
        'reference', ordered.reference,
        'destination_masked', left(ordered.destination_e164, 4) || '•••'
          || right(ordered.destination_e164, 3),
        'template_key', ordered.template_key,
        'template_version', ordered.template_version,
        'consent_revision', ordered.consent_revision,
        'authorization_current',
          collect_hybrid.sms_receipt_job_is_current(ordered.id),
        'attempt_count', ordered.attempt_count,
        'claim_expires_at', ordered.claim_expires_at,
        'channel', 'assisted_sms',
        'country_code', 'RW'
      )
    ) order by ordered.admin_rank), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into result
  from ordered;
  return coalesce(result, jsonb_build_object('rows', '[]'::jsonb, 'total', 0));
end;
$$;


--
-- Name: admin_list_interrupted_roster_imports(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_interrupted_roster_imports() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid; s collect_hybrid.roster_import_sources; answer jsonb:='[]'; begin
 sid:=collect_hybrid.require_fresh_roster_auth();
 -- A bounded authenticated server lookup; browser references confer no access.
 for s in select * from collect_hybrid.roster_import_sources where actor_id=auth.uid() and session_id<>sid
  and expires_at>clock_timestamp() and not exists(select 1 from collect_hybrid.roster_recovery_transfers where from_import_id=id)
  order by created_at desc,id limit 100 loop
  begin
   if exists(select 1 from collect_hybrid.roster_import_commits where import_id=s.id) then
    answer:=answer||jsonb_build_array(jsonb_build_object('import_id',s.id,'source_sha256',s.source_sha256,
     'source_kind',s.source_kind,'created_at',s.created_at,'expires_at',s.expires_at,'state','committed','etag',null));
   else
    perform collect_hybrid.require_interrupted_roster(s.id,sid);
    answer:=answer||jsonb_build_array(jsonb_build_object('import_id',s.id,'source_sha256',s.source_sha256,
     'source_kind',s.source_kind,'created_at',s.created_at,'expires_at',s.expires_at,'state','interrupted',
     'etag',collect_hybrid.roster_interrupted_etag(s.id,sid)));
   end if;
  exception when sqlstate '42501' or sqlstate '55000' then null;
  end;
 end loop;
 return jsonb_build_object('contract_version',1,'ok',true,'actor_id',auth.uid(),'destination_session_id',sid,'items',answer);
end $$;


--
-- Name: admin_list_journal_entries(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_journal_entries(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('bank_reconciliation.read');
  with filtered as (
    select entry.*,
      coalesce((select sum(line.amount_minor) from public.journal_lines line
        where line.journal_entry_id = entry.id and line.direction = 'debit'), 0) amount_minor
    from public.journal_entries entry
    where (p_status is null or entry.entry_type = p_status)
      and (p_search is null or entry.external_reference ilike '%' || p_search || '%'
        or entry.description ilike '%' || p_search || '%')
  ), counted as (
    select count(*) over () total_count, filtered.* from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(public._admin_row(
      id, external_reference, description, entry_type,
      currency || ' ' || to_char(amount_minor::numeric / 100, 'FM999G999G999D00'),
      created_at, jsonb_build_object('collection_id', collection_id)
    ) order by created_at desc), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  ) into result from counted;
  return result;
end;
$$;


--
-- Name: admin_list_ledger(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_ledger(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform assert_admin_permission('ledger.read');
  return jsonb_build_object('rows', coalesce((
    select jsonb_agg(_admin_row(le.id, le.entry_type, le.collection_id::text, le.visibility, le.amount_rwf::text || ' RWF', le.created_at) order by le.created_at desc)
    from ledger_entries le
    where (
        p_search is null
        or le.entry_type ilike '%' || p_search || '%'
        or le.collection_id::text = p_search
      )
      and (
        p_status is null
        or le.visibility = p_status
        or le.entry_type = p_status
      )
  ), '[]'::jsonb));
end;
$$;


--
-- Name: admin_list_members(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_members(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('users.read');
  with base as (
    select
      member.id,
      'Collect ID ' || member.collect_id as title,
      case when coalesce(member.linked_user_id, claim.user_id) is null
        then 'Feature phone • ' || public.mask_phone(identity.momo_number)
        else 'App account • ' || public.mask_phone(
          coalesce(profile.whatsapp_phone, identity.momo_number)
        )
      end as subtitle,
      case when (
        collect_admin_access.approved_identity(profile.id)
        and exists (
          select 1 from public.admin_user_roles assignment
          join public.admin_roles role on role.id = assignment.role_id
          where assignment.user_id = profile.id
            and assignment.revoked_at is null
            and role.name = 'platform_owner'
        )
      )
        then 'admin' else member.lifecycle end as status,
      member.created_at,
      coalesce(membership.active_groups, 0)::integer as active_groups,
      jsonb_build_object(
        'public_id', member.collect_id,
        'display_name', coalesce(identity.member_name, profile.display_name),
        'momo_registered_name', identity.momo_name,
        'whatsapp_masked', case when profile.id is null then null
          else public.mask_phone(profile.whatsapp_phone) end,
        'momo_masked', public.mask_phone(identity.momo_number),
        'country_code', coalesce(profile.country_code, 'RW'),
        'currency_code', coalesce(profile.currency_code, 'RWF'),
        'momo_provider', case when identity.member_id is not null
          then 'mtn_momo' else profile.momo_provider end,
        'account_state', case
          when member.linked_user_id is not null then 'app'
          when claim.user_id is not null then 'app_claimed'
          else 'feature_phone'
        end,
        'active_groups', coalesce(membership.active_groups, 0),
        'is_platform_admin', (
        collect_admin_access.approved_identity(profile.id)
        and exists (
          select 1 from public.admin_user_roles assignment
          join public.admin_roles role on role.id = assignment.role_id
          where assignment.user_id = profile.id
            and assignment.revoked_at is null
            and role.name = 'platform_owner'
        )
      )
      ) as extra
    from collect_hybrid.member_records member
    left join collect_hybrid.member_account_claims claim
      on claim.member_record_id = member.id and claim.user_id is not null
    left join public.profiles profile
      on profile.id = coalesce(member.linked_user_id, claim.user_id)
    left join collect_hybrid.member_momo_identities identity
      on identity.member_id = member.id
    left join lateral (
      select count(distinct membership.collection_id) as active_groups
      from public.collection_members membership
      join public.collections collection
        on collection.id = membership.collection_id
      where membership.member_record_id = member.id
        and membership.status = 'active'
        and collection.archived_at is null
    ) membership on true
    where member.lifecycle = 'active'
      and coalesce(membership.active_groups, 0) > 0
  ), filtered as (
    select * from base
    where (
      nullif(btrim(coalesce(p_status, '')), '') is null
      or status = btrim(p_status)
    ) and (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or title ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'display_name', '')
        ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'momo_registered_name', '')
        ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'momo_masked', '')
        ilike '%' || btrim(p_search) || '%'
    )
  ), counted as (
    select filtered.*,
      row_number() over (order by
        case when p_sort = 'created_at_asc' then created_at end asc nulls last,
        created_at desc, id
      ) as ordinal
    from filtered
    order by ordinal
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(
      public._admin_row(
        id, title, subtitle, status,
        active_groups::text || ' groups', created_at, extra
      ) order by ordinal
    ), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into result from counted;
  return result;
end;
$$;


--
-- Name: admin_list_non_member_users(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

