--
-- Name: admin_list_platform_payee_candidates(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_platform_payee_candidates(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('receivers.manage');

  with candidates as (
    select
      collection.id::text as id,
      collection.title,
      'Platform-sponsored public group with no payee route'::text as subtitle,
      'eligible'::text as status,
      'Rwanda · MoMo USSD'::text as amount,
      collection.created_at
    from public.collections collection
    where collection.is_platform_sponsored
      and collection.public_status = 'public_approved'
      and collection.archived_at is null
      and not exists (
        select 1
        from public.collection_receivers receiver
        where receiver.collection_id = collection.id
      )
  ), filtered as (
    select *
    from candidates
    where (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or title ilike '%' || btrim(p_search) || '%'
    )
  ), counted as (
    select filtered.*, count(*) over () as total_count
    from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', id,
        'title', title,
        'subtitle', subtitle,
        'status', status,
        'amount', amount,
        'created_at', created_at
      )
      order by created_at desc
    ), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  )
  into result
  from counted;

  return result;
end;
$$;


--
-- Name: admin_list_receivers(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_receivers(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform assert_admin_permission('receivers.read');
  return jsonb_build_object('rows', coalesce((
    select jsonb_agg(_admin_row(cr.id, cr.label, mask_phone(cr.momo_number), case when cr.is_active then 'active' else 'inactive' end, cr.network, cr.created_at) order by cr.created_at desc)
    from collection_receivers cr
    where (
        p_search is null
        or cr.label ilike '%' || p_search || '%'
        or cr.network ilike '%' || p_search || '%'
      )
      and (
        p_status is null
        or (p_status = 'active' and cr.is_active)
        or (p_status = 'inactive' and not cr.is_active)
      )
  ), '[]'::jsonb));
end;
$$;


--
-- Name: admin_list_reconciliation_exceptions(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_reconciliation_exceptions(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('bank_reconciliation.read');
  with filtered as (
    select exception.* from public.reconciliation_exceptions exception
    where (p_status is null or exception.status = p_status)
      and (p_search is null or exception.exception_type ilike '%' || p_search || '%'
        or exception.details::text ilike '%' || p_search || '%')
  ), counted as (
    select count(*) over () total_count, filtered.* from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(public._admin_row(
      id, replace(exception_type, '_', ' '),
      coalesce(details ->> 'transfer_reference', 'Reconciliation exception'),
      status, coalesce(details ->> 'currency', 'EUR'), created_at,
      jsonb_build_object('bank_transaction_id', bank_transaction_id, 'intent_id', bank_transfer_intent_id)
    ) order by created_at desc), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  ) into result from counted;
  return result;
end;
$$;


--
-- Name: admin_list_reconciliation_runs(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_reconciliation_runs(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('bank_reconciliation.read');
  with filtered as (
    select run.* from public.reconciliation_runs run
    where (p_status is null or run.status = p_status)
      and (p_search is null or run.run_date::text ilike '%' || p_search || '%')
  ), counted as (
    select count(*) over () total_count, filtered.* from filtered
    order by
      case when p_sort = 'created_at_asc' then started_at end asc nulls last,
      started_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(public._admin_row(
      id, run_date::text || ' · ' || currency,
