      status, currency || ' ' || to_char(matched_total_minor::numeric / 100, 'FM999G999G999D00'),
      started_at, jsonb_build_object('exception_count', exception_count)
    ) order by started_at desc), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  ) into result from counted;
  return result;
end;
$$;


--
-- Name: admin_list_runtime_control_events_v1(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_runtime_control_events_v1(p_family text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare session_id uuid;
begin
 session_id:=public._lock_notification_registration_session();
 begin
  perform collect_hybrid.require_roster_actor_authority(auth.uid(),session_id,'platform_owner',array['audit.read']);
 exception when sqlstate '42501' then
  raise exception 'runtime_control_permission_required' using errcode='42501';end;
 if p_limit is null or p_limit not between 1 and 100
  or p_family is not null and collect_security.runtime_control_spec(p_family) is null then
  raise exception 'runtime_control_query_invalid' using errcode='22023';end if;
 return jsonb_build_object('contract_version',1,'events',coalesce((
  select jsonb_agg(to_jsonb(event)-'session_id' order by event.recorded_at desc,event.id)
  from(select * from collect_security.runtime_control_events
   where p_family is null or family=p_family order by recorded_at desc,id limit p_limit) event),'[]'::jsonb));
end $$;


--
-- Name: admin_list_settings(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_settings(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform assert_admin_permission('settings.read');
  return jsonb_build_object('rows', coalesce((
    select jsonb_agg(_admin_row(gen_random_uuid(), key, description, case when is_sensitive then 'sensitive' else 'normal' end, '', updated_at) order by key)
    from system_settings
    where (
        p_search is null
        or key ilike '%' || p_search || '%'
        or description ilike '%' || p_search || '%'
      )
      and (
        p_status is null
        or (p_status = 'sensitive' and is_sensitive)
        or (p_status = 'normal' and not is_sensitive)
      )
  ), '[]'::jsonb));
end;
$$;


--
-- Name: admin_list_sms_metadata(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_sms_metadata(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  search_term text := nullif(btrim(p_search), '');
begin
  perform public.assert_admin_permission('sms.metadata.read');
  return jsonb_build_object('rows', coalesce((
    select jsonb_agg(
      public._admin_row(
        sms.id,
        coalesce(public.mask_phone(sms.raw_sender), 'SMS'),
        sms.body_hash,
        sms.parse_status,
        '',
        sms.ingested_at
      )
      order by sms.ingested_at desc
    )
    from public.raw_payment_sms sms
    where (p_status is null or sms.parse_status = p_status)
      and (
        search_term is null
        or coalesce(public.mask_phone(sms.raw_sender), 'SMS')
          ilike '%' || search_term || '%'
        or sms.body_hash ilike '%' || search_term || '%'
        or sms.parse_status::text ilike '%' || search_term || '%'
      )
  ), '[]'::jsonb));
end;
$$;


--
-- Name: admin_list_unallocated(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_unallocated(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_sort text := coalesce(nullif(p_sort, ''), 'created_at_desc');
  v_result jsonb;
begin
  perform assert_admin_permission('payment_events.read');
  if v_sort not in (
    'created_at_desc',
    'created_at_asc',
    'amount_desc',
    'amount_asc'
  ) then
    v_sort := 'created_at_desc';
  end if;

  with filtered as (
    select e.*
    from parsed_payment_events e
    where (
      (
        p_status is null
        and e.allocation_status in ('unallocated', 'ambiguous', 'needs_review')
      )
      or (
        p_status is not null
        and e.allocation_status::text = p_status
      )
    )
    and (
      p_search is null
      or e.transaction_id ilike '%' || p_search || '%'
    )
  ),
  ordered as (
    select
      filtered.*,
      row_number() over (
        order by
          case when v_sort = 'created_at_asc' then filtered.created_at end asc nulls last,
          case when v_sort = 'created_at_desc' then filtered.created_at end desc nulls last,
          case when v_sort = 'amount_asc' then filtered.amount_rwf end asc nulls last,
          case when v_sort = 'amount_desc' then filtered.amount_rwf end desc nulls last,
          filtered.created_at desc nulls last,
          filtered.id
      ) as admin_rank
    from filtered
    order by
      case when v_sort = 'created_at_asc' then filtered.created_at end asc nulls last,
      case when v_sort = 'created_at_desc' then filtered.created_at end desc nulls last,
      case when v_sort = 'amount_asc' then filtered.amount_rwf end asc nulls last,
      case when v_sort = 'amount_desc' then filtered.amount_rwf end desc nulls last,
      filtered.created_at desc nulls last,
      filtered.id
    limit v_limit
    offset v_offset
  )
  select jsonb_build_object(
    'rows',
    coalesce(
      jsonb_agg(
        _admin_row(
          ordered.id,
          coalesce(ordered.transaction_id, 'Payment event'),
          'MoMo SMS',
          ordered.allocation_status::text,
          coalesce(ordered.amount_rwf::text || ' RWF', ''),
          ordered.created_at,
          jsonb_build_object('collection_id', ordered.collection_id)
        )
        order by ordered.admin_rank
      ),
      '[]'::jsonb
    ),
    'total',
    (select count(*) from filtered)
  )
  into v_result
  from ordered;

  return coalesce(v_result, jsonb_build_object('rows', '[]'::jsonb, 'total', 0));
end;
$$;


--
-- Name: admin_list_users(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_users(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.admin_list_users(
    p_search,
    p_status,
    100,
    0,
    'created_at_desc'
  );
$$;


--
-- Name: admin_list_users(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_users(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('users.read');

  with base as (
    select
      profile.id,
      'Collect ID ' || profile.public_id as title,
      public.mask_phone(profile.whatsapp_phone) as subtitle,
      case when profile.is_platform_admin then 'admin' else 'active' end as status,
      profile.created_at,
      profile.updated_at,
      coalesce(member_count.active_groups, 0)::integer as active_groups,
      jsonb_build_object(
        'public_id', profile.public_id,
        'display_name', profile.display_name,
        'whatsapp_masked', public.mask_phone(profile.whatsapp_phone),
        'country_code', coalesce(profile.country_code, 'RW'),
        'currency_code', coalesce(profile.currency_code, 'RWF'),
        'momo_provider', profile.momo_provider,
        'momo_masked', public.mask_phone(profile.momo_number),
        'has_revolut_profile',
          profile.revolut_link is not null and profile.revolut_account is not null,
        'account_last4', case
          when profile.revolut_account is null then null
          else right(regexp_replace(profile.revolut_account, '[^A-Za-z0-9]', '', 'g'), 4)
        end,
        'active_groups', coalesce(member_count.active_groups, 0),
        'is_platform_admin', profile.is_platform_admin,
        'updated_at', profile.updated_at
      ) as extra
    from public.profiles profile
    left join lateral (
      select count(distinct member.collection_id) as active_groups
      from public.collection_members member
      where member.user_id = profile.id and member.status = 'active'
    ) member_count on true
  ), filtered as (
    select * from base
    where (
      nullif(btrim(coalesce(p_status, '')), '') is null
      or status = btrim(p_status)
    ) and (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or title ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'display_name', '') ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'whatsapp_masked', '') ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'country_code', '') ilike '%' || btrim(p_search) || '%'
    )
  ), counted as (
    select filtered.*, count(*) over () as total_count
    from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', id,
        'title', title,
        'subtitle', subtitle,
        'status', status,
        'amount', active_groups::text || ' groups',
        'created_at', created_at
      ) || extra order by created_at desc
    ), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  ) into result from counted;
  return result;
end;
$$;


--
-- Name: admin_manual_allocate_payment(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_manual_allocate_payment(p_event_id uuid, p_collection_id uuid, p_payment_intent_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  event_row public.parsed_payment_events%rowtype;
  intent_row public.payment_intents%rowtype;
  receiver_hash text;
  payment_id uuid;
begin
  perform public.assert_admin_permission('payments.allocate');
  if p_payment_intent_id is null then
    raise exception 'A verified payment intent is required';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 8 then
    raise exception 'Allocation reason must be at least 8 characters';
  end if;

  select * into event_row from public.parsed_payment_events
  where id = p_event_id for update;
  select * into intent_row from public.payment_intents
  where id = p_payment_intent_id for update;
  if event_row.id is null or intent_row.id is null then
    raise exception 'Payment event and intent are required';
  end if;
  if intent_row.collection_id <> p_collection_id then
    raise exception 'Payment intent does not belong to the selected group';
  end if;

  if event_row.receiver_phone_hash is null then
    select receiver.momo_number_hash into receiver_hash
    from public.collection_receivers receiver
    where receiver.collection_id = p_collection_id
      and receiver.receiver_user_id = event_row.receiver_user_id
      and receiver.momo_number_hash = intent_row.receiver_momo_number_hash
      and receiver.is_active
    order by receiver.created_at desc limit 1;
    if receiver_hash is null then
      raise exception 'SMS receiver is not an active payee for the selected group';
    end if;
    update public.parsed_payment_events
    set receiver_phone_hash = receiver_hash,
        collection_id = p_collection_id
    where id = p_event_id;
  end if;

  payment_id := public.post_payment_from_event(
    p_event_id,
    p_payment_intent_id,
    p_collection_id,
    'Admin verified allocation: ' || btrim(p_reason)
  );
  perform public.create_audit_log(
    'payment.allocated.admin_verified', 'payment', payment_id,
    jsonb_build_object(
      'parsed_event_id', p_event_id,
      'payment_intent_id', p_payment_intent_id,
      'collection_id', p_collection_id,
      'reason', btrim(p_reason)
    )
  );
  return jsonb_build_object('status', 'allocated', 'payment_id', payment_id);
end;
$$;


--
-- Name: admin_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_overview() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  review_count bigint;
  unallocated_count bigint;
  balanced_count bigint;
  payee_count bigint;
begin
  perform public.assert_admin_permission('overview.read');
  review_count := (public.admin_list_collect_reconciliations(null,null,1,0,'created_at_desc')->>'total')::bigint;
  unallocated_count := (public.admin_list_collect_transactions(null,'unallocated',1,0,'created_at_desc')->>'total')::bigint;
  balanced_count := (public.admin_list_collect_ledgers(null,'balanced',1,0,'created_at_desc')->>'total')::bigint;
  payee_count := (public.admin_list_collect_payees(null,'active',1,0,'created_at_desc')->>'total')::bigint;
  return jsonb_build_object('metrics', jsonb_build_array(
    jsonb_build_object('label','Open reconciliations','value',review_count,
      'status',case when review_count>0 then 'needs_review' else 'active' end),
    jsonb_build_object('label','Unallocated transactions','value',unallocated_count,
      'status',case when unallocated_count>0 then 'needs_review' else 'active' end),
    jsonb_build_object('label','Balanced ledgers','value',balanced_count,'status','active'),
    jsonb_build_object('label','Active payees','value',payee_count,'status','active')
  ));
end;
$$;


--
-- Name: admin_propose_bank_allocation(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_propose_bank_allocation(p_bank_transaction_id uuid, p_bank_transfer_intent_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  request public.bank_allocation_change_requests%rowtype;
  transaction_row public.bank_transactions%rowtype;
  intent public.bank_transfer_intents%rowtype;
begin
  perform public.assert_admin_permission('bank_allocations.propose');
  if char_length(btrim(coalesce(p_reason, ''))) < 8 then
    raise exception 'Allocation reason must be at least 8 characters';
  end if;
  select * into transaction_row
  from public.bank_transactions
  where id = p_bank_transaction_id
  for update;
  select * into intent
  from public.bank_transfer_intents
  where id = p_bank_transfer_intent_id
  for update;
  if transaction_row.id is null or intent.id is null then
    raise exception 'Bank transaction and transfer intent are required';
  end if;
  if transaction_row.currency <> intent.currency
     or transaction_row.amount_minor <> intent.amount_minor then
    raise exception 'Manual allocation requires an exact amount and currency match';
  end if;
  if transaction_row.status in ('reconciled', 'returned')
     or intent.status in ('reconciled', 'returned', 'cancelled', 'expired') then
    raise exception 'The transaction or transfer intent is no longer allocatable';
  end if;
  if exists (
    select 1 from public.bank_transaction_allocations allocation
    where allocation.bank_transaction_id = transaction_row.id
       or allocation.bank_transfer_intent_id = intent.id
  ) then
    raise exception 'The transaction or transfer intent is already allocated';
  end if;
  insert into public.bank_allocation_change_requests (
    bank_transaction_id, bank_transfer_intent_id, reason, proposed_by
  ) values (
    transaction_row.id, intent.id, btrim(p_reason), auth.uid()
  ) returning * into request;
  perform public.create_audit_log(
    'bank_allocation.proposed',
    'bank_allocation_change_request',
    request.id,
    jsonb_build_object(
      'bank_transaction_id', transaction_row.id,
      'bank_transfer_intent_id', intent.id,
      'reason', request.reason
    )
  );
  return to_jsonb(request);
end;
$$;


--
-- Name: admin_propose_bank_destination(text, text, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_propose_bank_destination(p_beneficiary_name text, p_iban text, p_bic text, p_bank_name text, p_supports_instant boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  request public.bank_destination_change_requests%rowtype;
  clean_iban text := public.normalize_iban(p_iban);
  clean_bic text := upper(regexp_replace(coalesce(p_bic, ''), '[^A-Za-z0-9]', '', 'g'));
begin
  perform public.assert_admin_permission('bank_details.propose');
  if clean_iban !~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$'
     or clean_iban like 'XX00%'
     or clean_iban like '%PLACEHOLDER%' then
    raise exception 'A valid non-placeholder IBAN is required';
  end if;
  if clean_bic !~ '^[A-Z0-9]{8}([A-Z0-9]{3})?$'
     or clean_bic like 'PLACEH%' then
    raise exception 'A valid non-placeholder BIC is required';
  end if;
  if char_length(btrim(coalesce(p_beneficiary_name, ''))) < 3
     or char_length(btrim(coalesce(p_bank_name, ''))) < 2 then
    raise exception 'Beneficiary and bank names are required';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 8 then
    raise exception 'Change reason must be at least 8 characters';
  end if;

  insert into public.bank_destination_change_requests (
    beneficiary_name, iban, bic, bank_name, currency,
    supports_instant, status, reason, proposed_by
  ) values (
    btrim(p_beneficiary_name), clean_iban, clean_bic, btrim(p_bank_name),
    'EUR', coalesce(p_supports_instant, true), 'pending', btrim(p_reason), auth.uid()
  ) returning * into request;

  perform public.create_audit_log(
    'bank_destination.change_proposed',
    'bank_destination_change_request',
    request.id,
    jsonb_build_object(
      'beneficiary_name', request.beneficiary_name,
      'iban_masked', public.mask_iban(request.iban),
      'bic', request.bic,
      'bank_name', request.bank_name,
      'supports_instant', request.supports_instant,
      'reason', request.reason
    )
  );
  return to_jsonb(request) - 'iban' || jsonb_build_object('iban_masked', public.mask_iban(request.iban));
end;
$_$;


--
-- Name: admin_record_operator_note(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_record_operator_note(p_entity_type text, p_entity_id uuid, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  note_id uuid;
  normalized_entity_type text := trim(coalesce(p_entity_type, ''));
  normalized_body text := trim(coalesce(p_body, ''));
begin
  if normalized_body = '' then
    raise exception 'Note body is required';
  end if;

  case normalized_entity_type
    when 'collection' then perform assert_admin_permission('collections.read');
    when 'profile' then perform assert_admin_permission('users.read');
    when 'payment_intent' then perform assert_admin_permission('payments.read');
    when 'parsed_payment_event' then perform assert_admin_permission('payment_events.read');
    when 'payment_receiver' then perform assert_admin_permission('collections.read');
    when 'raw_payment_sms' then perform assert_admin_permission('sms.metadata.read');
    else raise exception 'Unsupported admin note entity type: %', normalized_entity_type;
  end case;

  insert into admin_notes (entity_type, entity_id, body, created_by)
  values (normalized_entity_type, p_entity_id, normalized_body, auth.uid())
  returning id into note_id;

  perform create_audit_log(
    'admin.operator_note.recorded',
    normalized_entity_type,
    p_entity_id,
    jsonb_build_object('note_id', note_id)
  );

  return jsonb_build_object('ok', true, 'note_id', note_id);
end;
$$;


--
-- Name: admin_recover_roster_import(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_recover_roster_import(p_upload_request_id uuid, p_pending_request_id uuid) RETURNS jsonb
