   begin perform collect_hybrid.require_roster_caller(); perform collect_hybrid.roster_recovery_leaf((select id from collect_hybrid.roster_import_sources where request_id=p_upload_request_id),false); return collect_hybrid.admin_recover_roster_import_guarded_149(p_upload_request_id,p_pending_request_id); end $$;


--
-- Name: admin_reopen_daily_bank_close(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reopen_daily_bank_close(p_close_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  close_row public.daily_bank_closes%rowtype;
begin
  perform public.assert_admin_permission('bank_reconciliation.manage');
  if char_length(btrim(coalesce(p_reason, ''))) < 8 then
    raise exception 'Reopen reason must be at least 8 characters';
  end if;
  update public.daily_bank_closes
  set status = 'reopened',
      reopened_at = now(),
      reopened_by = auth.uid(),
      reopen_reason = btrim(p_reason),
      closed_at = null,
      closed_by = null,
      updated_at = now()
  where id = p_close_id
    and status in ('balanced', 'exception')
  returning * into close_row;
  if close_row.id is null then
    raise exception 'Daily close not found or already open';
  end if;
  perform public.create_audit_log(
    'bank_reconciliation.close_reopened',
    'daily_bank_close',
    close_row.id,
    jsonb_build_object('reason', btrim(p_reason))
  );
  return to_jsonb(close_row);
end;
$$;


--
-- Name: admin_reparse_payment_event(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reparse_payment_event(p_event_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform assert_admin_permission('payment_events.reparse');
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'Reason is required';
  end if;
  update parsed_payment_events
    set allocation_status = 'needs_review',
        review_reason = 'Reparse requested: ' || p_reason
    where id = p_event_id and allocation_status <> 'allocated';
  perform create_audit_log('payment_event.reparse.requested', 'parsed_payment_event', p_event_id, jsonb_build_object('reason', p_reason));
  return jsonb_build_object('ok', true, 'message', 'Reparse queued for review');
end;
$$;


--
-- Name: admin_resolve_reconciliation_exception(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_resolve_reconciliation_exception(p_exception_id uuid, p_resolution_note text, p_dismiss boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare exception public.reconciliation_exceptions%rowtype;
begin
  perform public.assert_admin_permission('bank_reconciliation.manage');
  if char_length(btrim(coalesce(p_resolution_note, ''))) < 8 then
    raise exception 'Resolution note must be at least 8 characters';
  end if;
  update public.reconciliation_exceptions
  set status = case when p_dismiss then 'dismissed' else 'resolved' end,
      resolved_by = auth.uid(), resolution_note = btrim(p_resolution_note),
      resolved_at = now()
  where id = p_exception_id and status in ('open', 'reviewing')
  returning * into exception;
  if exception.id is null then raise exception 'Open exception was not found'; end if;
  perform public.create_audit_log(
    'bank_reconciliation.exception_resolved', 'reconciliation_exception', exception.id,
    jsonb_build_object('status', exception.status, 'resolution_note', exception.resolution_note)
  );
  return to_jsonb(exception);
end;
$$;


--
-- Name: admin_retry_notification(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_retry_notification(p_event_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  reason text := trim(coalesce(p_reason, ''));
  device_ids uuid[];
  session_ids uuid[];
  retried integer;
begin
  perform public._lock_notification_session_gate();
  perform public.assert_admin_permission('notifications.manage');
  if reason = '' then raise exception 'Reason is required'; end if;
  select array_agg(locked.id) into session_ids from (
    select s.id from auth.sessions s where exists(select 1 from public.notification_device_tokens device
      join public.notification_deliveries d on d.device_id=device.id
      where device.registration_session_id=s.id and d.event_id=p_event_id and d.status='failed')
    order by s.id for share of s
  ) locked;
  select array_agg(locked.id) into device_ids from (
    select device.id from public.notification_device_tokens device
    join public.notification_events event on event.user_id = device.user_id and event.id = p_event_id
    where device.registration_session_id=any(session_ids)
      and public._notification_session_is_live(device.registration_session_id,device.user_id)
      and device.enabled and device.provider in ('apns', 'fcm') and device.token is not null
      and exists (select 1 from public.notification_deliveries d where d.device_id = device.id
        and d.event_id = p_event_id and d.status = 'failed'
        and (d.claim_expires_at is null or d.claim_expires_at <= clock_timestamp()))
    order by device.id for update of device
  ) locked;
  update public.notification_deliveries d set status = 'queued',
    prior_attempt_count = d.prior_attempt_count + d.attempt_count, attempt_count = 0,
    next_attempt_at = clock_timestamp(), last_attempt_at = null, sent_at = null,
    provider_message_id = null, last_error_code = null,
    claim_token = null, claim_expires_at = null, claim_user_id = null, updated_at = clock_timestamp()
  where d.event_id = p_event_id and d.device_id = any(device_ids) and d.status = 'failed'
    and (d.claim_expires_at is null or d.claim_expires_at <= clock_timestamp());
  get diagnostics retried = row_count;
  if retried = 0 then raise exception 'No retryable failed deliveries'; end if;
  perform public._refresh_notification_event(p_event_id);
  perform public.create_audit_log('notification.delivery.retried', 'notification_event', p_event_id,
    jsonb_build_object('reason', reason, 'delivery_count', retried));
  return jsonb_build_object('ok', true, 'status', 'queued', 'delivery_count', retried);
end $$;


--
-- Name: admin_reveal_raw_bank_evidence(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reveal_raw_bank_evidence(p_event_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare evidence public.raw_payment_evidence%rowtype;
begin
  perform public.assert_admin_permission('bank_evidence.raw.reveal');
  if char_length(btrim(coalesce(p_reason, ''))) < 8 then
    raise exception 'Reveal reason must be at least 8 characters';
  end if;
  select raw.* into evidence
  from public.bank_evidence_events event
  join public.raw_payment_evidence raw on raw.id = event.raw_evidence_id
  where event.id = p_event_id;
  if evidence.id is null then raise exception 'Bank evidence not found'; end if;
  insert into public.admin_sensitive_access_logs (
    actor_user_id, entity_type, entity_id, reason
  ) values (
    auth.uid(), 'raw_payment_evidence', evidence.id, btrim(p_reason)
  );
  perform public.create_audit_log(
    'bank_evidence.raw_revealed', 'raw_payment_evidence', evidence.id,
    jsonb_build_object('reason', btrim(p_reason), 'channel', evidence.channel)
  );
  return jsonb_build_object(
    'id', evidence.id, 'channel', evidence.channel,
    'sender', evidence.raw_sender, 'body', evidence.raw_body,
    'headers', evidence.headers, 'received_at', evidence.received_at
  );
end;
$$;


--
-- Name: admin_reveal_raw_sms(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reveal_raw_sms(p_sms_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  raw_body text;
begin
  perform assert_admin_permission('sms.raw.reveal');
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'Reason is required';
  end if;
  select s.raw_body into raw_body from raw_payment_sms s where s.id = p_sms_id;
  if raw_body is null then
    raise exception 'Raw SMS not found';
  end if;
  insert into admin_sensitive_access_logs (actor_user_id, entity_type, entity_id, reason)
  values (auth.uid(), 'raw_payment_sms', p_sms_id, p_reason);
  perform create_audit_log('sms.raw.revealed', 'raw_payment_sms', p_sms_id, jsonb_build_object('reason', p_reason));
  return jsonb_build_object('ok', true, 'message', raw_body);
end;
$$;


--
-- Name: admin_reverse_momo_payment(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reverse_momo_payment(p_payment_id uuid, p_reason text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  clean_reason text := btrim(coalesce(p_reason, ''));
  input_hash text;
  prior collect_hybrid.momo_reversal_requests;
  payment_row public.payments;
  original_entry collect_hybrid.momo_journal_entries;
  reversal_id uuid;
  group_balance bigint;
  member_balance bigint;
  response jsonb;
begin
  perform public.assert_admin_permission('payments.allocate');
  if p_request_id is null or p_payment_id is null
     or char_length(clean_reason) not between 8 and 500 then
    raise exception 'Payment, request ID and complete reversal reason required';
  end if;
  input_hash := encode(extensions.digest(
    jsonb_build_array(p_payment_id, clean_reason)::text, 'sha256'
  ), 'hex');
  perform pg_advisory_xact_lock(hashtextextended('hybrid-momo-reversal:' || p_request_id::text, 0));
  select request.* into prior
  from collect_hybrid.momo_reversal_requests request
  where request.request_id = p_request_id;
  if prior.request_id is not null then
    if prior.actor_id <> actor_id or prior.payment_id <> p_payment_id
       or prior.input_hash <> input_hash then
      raise exception 'MoMo reversal idempotency key conflict';
    end if;
    return prior.result || jsonb_build_object('replay', true);
  end if;

  select payment.* into payment_row
  from public.payments payment
  where payment.id = p_payment_id
  for update;
  if payment_row.id is null then raise exception 'Payment not found'; end if;
  if payment_row.status <> 'posted' then raise exception 'Only a posted payment can be reversed'; end if;
  select entry.* into original_entry
  from collect_hybrid.momo_journal_entries entry
  where entry.payment_id = payment_row.id and entry.entry_type = 'receipt'
  for share;
  if original_entry.id is null then raise exception 'Canonical receipt journal required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'hybrid-momo-group-balance:' || payment_row.collection_id::text, 0
  ));
  if payment_row.member_record_id is not null then
    perform pg_advisory_xact_lock(hashtextextended(
      'hybrid-momo-member-balance:' || payment_row.collection_id::text || ':' || payment_row.member_record_id::text,
      0
    ));
  end if;

  insert into collect_hybrid.momo_journal_entries(
    payment_id, parsed_event_id, collection_id, member_record_id,
    entry_type, amount_rwf, external_reference, reverses_entry_id, created_by
  ) values (
    payment_row.id, payment_row.parsed_event_id, payment_row.collection_id,
    payment_row.member_record_id, 'reversal', payment_row.amount_rwf,
    'reversal:' || original_entry.id::text, original_entry.id, actor_id
  ) returning id into reversal_id;
  insert into collect_hybrid.momo_journal_lines(
    journal_entry_id, account_code, direction, amount_rwf
  ) values
    (reversal_id, 'member_savings_liability:RWF', 'debit', payment_row.amount_rwf),
    (reversal_id, 'momo_receiving_asset:RWF', 'credit', payment_row.amount_rwf);

  -- Keep every compatibility reader financially equivalent without mutating
  -- the original immutable projection rows.
  insert into public.ledger_entries(
    payment_id, collection_id, user_id, member_record_id,
    entry_type, amount_rwf, currency, visibility, metadata
  )
  select ledger.payment_id, ledger.collection_id, ledger.user_id,
    ledger.member_record_id, ledger.entry_type, -ledger.amount_rwf,
    ledger.currency, ledger.visibility,
    ledger.metadata || jsonb_build_object(
      'compensates_ledger_entry_id', ledger.id,
      'momo_reversal_journal_entry_id', reversal_id,
      'reversal_request_id', p_request_id
    )
  from public.ledger_entries ledger
  where ledger.payment_id = payment_row.id
    and ledger.entry_type in ('collection_credit', 'member_credit')
    and ledger.amount_rwf > 0
  on conflict do nothing;

  update collect_hybrid.collection_balances balance
  set confirmed_rwf = balance.confirmed_rwf - payment_row.amount_rwf,
      updated_at = now()
  where balance.collection_id = payment_row.collection_id
    and balance.confirmed_rwf >= payment_row.amount_rwf
  returning confirmed_rwf into group_balance;
  if group_balance is null then raise exception 'Group balance cannot support this reversal'; end if;
  if payment_row.member_record_id is not null then
    update collect_hybrid.member_balances balance
    set confirmed_rwf = balance.confirmed_rwf - payment_row.amount_rwf,
        updated_at = now()
    where balance.collection_id = payment_row.collection_id
      and balance.member_record_id = payment_row.member_record_id
      and balance.confirmed_rwf >= payment_row.amount_rwf
    returning confirmed_rwf into member_balance;
    if member_balance is null then raise exception 'Member balance cannot support this reversal'; end if;
  end if;
  insert into collect_hybrid.momo_balance_snapshots(
    journal_entry_id, payment_id, collection_id, member_record_id,
    event_type, delta_rwf, member_balance_after_rwf, group_balance_after_rwf
  ) values (
    reversal_id, payment_row.id, payment_row.collection_id, payment_row.member_record_id,
    'reversal', -payment_row.amount_rwf, member_balance, group_balance
  );
  update public.payments set status = 'reversed' where id = payment_row.id;
  response := jsonb_build_object(
    'ok', true,
    'payment_id', payment_row.id,
    'reversal_journal_entry_id', reversal_id,
    'member_balance_after_rwf', member_balance,
    'group_balance_after_rwf', group_balance,
    'replay', false
  );
  insert into collect_hybrid.momo_reversal_requests(request_id, payment_id, actor_id, input_hash, result)
  values (p_request_id, payment_row.id, actor_id, input_hash, response);
  perform public.create_audit_log(
    'payment.reversed.momo', 'payment', payment_row.id,
    jsonb_build_object(
      'reason', clean_reason,
      'request_id', p_request_id,
      'reversal_journal_entry_id', reversal_id
    )
  );
  return response;
end;
$$;


--
-- Name: admin_review_bank_allocation(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_review_bank_allocation(p_request_id uuid, p_approve boolean, p_review_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  request public.bank_allocation_change_requests%rowtype;
  transaction_row public.bank_transactions%rowtype;
  intent public.bank_transfer_intents%rowtype;
  allocation public.bank_transaction_allocations%rowtype;
begin
  perform public.assert_admin_permission('bank_allocations.approve');
  if char_length(btrim(coalesce(p_review_note, ''))) < 8 then
    raise exception 'Review note must be at least 8 characters';
  end if;
  select * into request
  from public.bank_allocation_change_requests
  where id = p_request_id
  for update;
  if request.id is null or request.status <> 'pending' then
    raise exception 'Pending allocation request was not found';
  end if;
  if request.proposed_by = auth.uid() then
    raise exception 'Maker-checker control prohibits approving your own allocation';
  end if;
  if not p_approve then
    update public.bank_allocation_change_requests
    set status = 'rejected', reviewed_by = auth.uid(),
        review_note = btrim(p_review_note), reviewed_at = now()
    where id = request.id
    returning * into request;
    perform public.create_audit_log(
      'bank_allocation.rejected', 'bank_allocation_change_request', request.id,
      jsonb_build_object('review_note', request.review_note)
    );
    return to_jsonb(request);
  end if;

  select * into transaction_row
  from public.bank_transactions
  where id = request.bank_transaction_id
  for update;
  select * into intent
  from public.bank_transfer_intents
  where id = request.bank_transfer_intent_id
  for update;
  if transaction_row.currency <> intent.currency
     or transaction_row.amount_minor <> intent.amount_minor
     or transaction_row.status in ('reconciled', 'returned')
     or intent.status in ('reconciled', 'returned', 'cancelled', 'expired') then
    raise exception 'The proposed allocation is no longer valid';
  end if;

  insert into public.bank_transaction_allocations (
    bank_transaction_id, bank_transfer_intent_id, collection_id,
    contributor_user_id, allocation_method, confidence, reason, allocated_by
  ) values (
    transaction_row.id, intent.id, intent.collection_id,
    intent.contributor_user_id, 'manual_maker_checker', 1,
    request.reason || ' | Checker: ' || btrim(p_review_note), auth.uid()
  ) returning * into allocation;

  update public.bank_transactions
  set destination_id = intent.destination_id,
      status = 'received', updated_at = now()
  where id = transaction_row.id;
  update public.bank_transfer_intents
  set status = 'received_unreconciled',
      evidence_received_at = coalesce(evidence_received_at, transaction_row.evidence_received_at),
      exception_reason = null, updated_at = now()
  where id = intent.id;
  update public.bank_evidence_events event
  set allocation_status = 'allocated',
      review_reason = 'Approved manual maker-checker allocation'
  from public.payment_evidence_links link
  where link.bank_transaction_id = transaction_row.id
    and link.evidence_event_id = event.id;
  update public.reconciliation_exceptions
  set status = 'resolved', resolved_by = auth.uid(),
      resolution_note = btrim(p_review_note), resolved_at = now()
  where bank_transaction_id = transaction_row.id
    and status in ('open', 'reviewing')
    and exception_type in ('missing_reference', 'no_exact_intent', 'ambiguous_intent');
  update public.bank_allocation_change_requests
  set status = 'approved', reviewed_by = auth.uid(),
      review_note = btrim(p_review_note), reviewed_at = now()
  where id = request.id
  returning * into request;
  perform public.create_audit_log(
    'bank_allocation.approved', 'bank_transaction_allocation', allocation.id,
    jsonb_build_object(
      'request_id', request.id,
      'bank_transaction_id', transaction_row.id,
      'bank_transfer_intent_id', intent.id,
      'review_note', request.review_note
    )
  );
  return to_jsonb(request) || jsonb_build_object('allocation_id', allocation.id);
end;
$$;


--
-- Name: admin_review_bank_destination_change(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_review_bank_destination_change(p_request_id uuid, p_approve boolean, p_review_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  request public.bank_destination_change_requests%rowtype;
  destination public.bank_transfer_destinations%rowtype;
  next_version integer;
begin
  perform public.assert_admin_permission('bank_details.approve');
  if char_length(btrim(coalesce(p_review_note, ''))) < 8 then
    raise exception 'Review note must be at least 8 characters';
  end if;
  select * into request
  from public.bank_destination_change_requests
  where id = p_request_id
  for update;
  if request.id is null or request.status <> 'pending' then
    raise exception 'Pending bank destination change was not found';
  end if;
  if request.proposed_by = auth.uid() then
    raise exception 'Maker-checker control prohibits approving your own bank destination proposal';
  end if;

  if not p_approve then
    update public.bank_destination_change_requests
    set status = 'rejected',
        reviewed_by = auth.uid(),
        review_note = btrim(p_review_note),
        reviewed_at = now()
    where id = request.id
    returning * into request;
    perform public.create_audit_log(
      'bank_destination.change_rejected',
      'bank_destination_change_request',
      request.id,
      jsonb_build_object('review_note', request.review_note)
    );
    return to_jsonb(request) - 'iban' || jsonb_build_object('iban_masked', public.mask_iban(request.iban));
  end if;

  perform pg_advisory_xact_lock(hashtextextended('bank-destination:EUR', 0));
  select coalesce(max(version), 0) + 1 into next_version
  from public.bank_transfer_destinations
  where currency = 'EUR';

  update public.bank_transfer_destinations
  set status = 'retired', retired_at = now(), updated_at = now()
  where currency = 'EUR' and status = 'active';

  insert into public.bank_transfer_destinations (
    version,
    beneficiary_name,
    iban,
    bic,
    bank_name,
    currency,
    supports_instant,
    status,
    is_placeholder,
    change_reason,
    created_by,
    approved_by,
    approved_at,
    activated_at
  ) values (
    next_version,
    request.beneficiary_name,
    request.iban,
    request.bic,
    request.bank_name,
    'EUR',
    request.supports_instant,
    'active',
    false,
    request.reason,
    request.proposed_by,
    auth.uid(),
    now(),
    now()
  ) returning * into destination;

  update public.bank_destination_change_requests
  set status = 'approved',
      reviewed_by = auth.uid(),
      review_note = btrim(p_review_note),
      reviewed_at = now(),
      destination_id = destination.id
  where id = request.id
  returning * into request;

  update public.feature_flags
  set enabled = true,
      updated_by = auth.uid(),
      updated_reason = 'Maker-checker approved bank destination version ' || destination.version::text,
      updated_at = now()
  where key = 'bank_transfer_v1';

  perform public.create_audit_log(
    'bank_destination.change_approved',
    'bank_transfer_destination',
    destination.id,
    jsonb_build_object(
      'request_id', request.id,
      'version', destination.version,
      'beneficiary_name', destination.beneficiary_name,
      'iban_masked', public.mask_iban(destination.iban),
      'bic', destination.bic,
      'bank_name', destination.bank_name,
      'review_note', request.review_note
    )
  );
  return public.bank_transfer_destination_json(destination);
end;
$$;


