   begin perform collect_hybrid.guard_roster_service_recovery((select id from collect_hybrid.roster_import_sources where request_id=p_request_id)); return collect_hybrid.create_roster_import_source_guarded_149(p_actor_id,p_session_id,p_request_id,p_source_kind,p_original_sha256,p_original_size,p_client_filename,p_declared_mime,p_detected_type,p_derived_sha256,p_derived_size,p_ai_consent,p_consent_version,p_ai_metadata); end $$;


