--
-- Name: disable_invalid_notification_device(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.disable_invalid_notification_device() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.error_code in (
    'BadDeviceToken', 'DeviceTokenNotForTopic', 'Unregistered', 'UNREGISTERED'
  ) then
    update notification_device_tokens device
    set enabled = false,
        disabled_at = now(),
        disabled_reason = new.error_code,
        updated_at = now()
    from notification_deliveries delivery
    where delivery.id = new.delivery_id
      and device.id = delivery.device_id;
  end if;
  return new;
end;
$$;


