-- Name: emit_app_realtime_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_app_realtime_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into app_realtime_events (area)
  values (tg_argv[0]);

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: enforce_active_contributor_membership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_active_contributor_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.contributor_user_id is null then
    raise exception 'Authenticated contributor is required';
  end if;
  if not exists (
    select 1
    from public.collections collection
    where collection.id = new.collection_id
      and collection.archived_at is null
      and (
        collection.public_status = 'public_approved'
        or collection.creator_user_id = new.contributor_user_id
        or exists (
          select 1
          from public.collection_members member_check
          where member_check.collection_id = collection.id
            and member_check.user_id = new.contributor_user_id
            and member_check.status = 'active'
        )
      )
  ) then
    raise exception 'Join this group before creating a contribution request';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_official_payee_route_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_official_payee_route_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if exists (
    select 1
    from public.collections collection
    where collection.id = old.collection_id
      and collection.is_platform_sponsored
  ) and (
    new.momo_number is distinct from old.momo_number
    or new.momo_number_hash is distinct from old.momo_number_hash
    or new.network is distinct from old.network
  ) then
    raise exception 'Official payee MoMo number or code and provider are immutable; deactivate the route instead';
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION enforce_official_payee_route_immutable(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_official_payee_route_immutable() IS 'Rejects attempts to change the MoMo number, code hash, or provider of a platform-sponsored official payee.';


--
-- Name: enqueue_contribution_confirmation_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_contribution_confirmation_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  group_title text;
begin
  if new.status <> 'posted'
     or new.contributor_user_id is null
     or (tg_op = 'UPDATE' and old.status = 'posted') then
    return new;
  end if;
  select title
  into group_title
  from public.collections
  where id = new.collection_id;
  perform public.enqueue_notification_template_event(
    new.contributor_user_id,
    'contribution.confirmed.default',
    jsonb_build_object(
      'amount', 'RWF ' || new.amount_rwf::text,
      'group', coalesce(group_title, 'your group')
    ),
    new.collection_id,
    '/groups/' || new.collection_id::text || '/ledger',
    'en'
  );
  return new;
end;
$$;


--
-- Name: enqueue_notification_event(uuid, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_notification_event(p_user_id uuid, p_type text, p_title text, p_body text, p_collection_id uuid DEFAULT NULL::uuid, p_deep_link text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  inserted_id uuid;
  preference_enabled boolean;
begin
  if p_type = 'contribution_confirmed' then
    select coalesce(contribution_confirmations, true)
    into preference_enabled
    from notification_preferences
    where user_id = p_user_id;
  elsif p_type = 'payment_reminder' then
    select coalesce(payment_reminders, true)
    into preference_enabled
    from notification_preferences
    where user_id = p_user_id;
  elsif p_type = 'group_update' then
    select coalesce(group_updates, true)
    into preference_enabled
    from notification_preferences
    where user_id = p_user_id;
  elsif p_type = 'security_notice' then
    select coalesce(security_notices, true)
    into preference_enabled
    from notification_preferences
    where user_id = p_user_id;
  else
    raise exception 'invalid_notification_type';
  end if;

  if coalesce(preference_enabled, true) = false then
    return null;
  end if;

  insert into notification_events (
    user_id,
    collection_id,
    type,
    title,
    body,
    deep_link
  )
  values (
    p_user_id,
    p_collection_id,
    p_type,
    p_title,
    p_body,
    p_deep_link
  )
  returning id into inserted_id;

  return inserted_id;
end;
$$;


--
-- Name: enqueue_notification_template_event(uuid, text, jsonb, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_notification_template_event(p_user_id uuid, p_template_key text, p_context jsonb DEFAULT '{}'::jsonb, p_collection_id uuid DEFAULT NULL::uuid, p_deep_link text DEFAULT NULL::text, p_locale text DEFAULT 'en'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  template_row record;
  inserted_id uuid;
  preference_enabled boolean := true;
begin
  select
    nt.key,
    net.key as event_type,
    net.preference_key,
    ntv.title_template,
    ntv.body_template
  into template_row
  from notification_templates nt
  join notification_event_types net on net.key = nt.event_type_key
  join notification_template_versions ntv on ntv.template_key = nt.key
  where nt.key = trim(p_template_key)
    and nt.locale in (coalesce(nullif(trim(p_locale), ''), 'en'), 'en')
    and nt.enabled
    and net.enabled
    and ntv.status = 'published'
    and ntv.effective_at <= now()
  order by
    case when nt.locale = coalesce(nullif(trim(p_locale), ''), 'en') then 0 else 1 end,
    ntv.effective_at desc,
    ntv.version desc
  limit 1;

  if template_row.key is null then
    raise exception 'notification_template_not_found';
  end if;

  select case template_row.preference_key
    when 'contribution_confirmations' then coalesce(contribution_confirmations, true)
    when 'payment_reminders' then coalesce(payment_reminders, true)
    when 'group_updates' then coalesce(group_updates, true)
    when 'security_notices' then coalesce(security_notices, true)
    else true
  end
  into preference_enabled
  from notification_preferences
  where user_id = p_user_id;

  if coalesce(preference_enabled, true) is false then
    return null;
  end if;

  insert into notification_events (
    user_id,
    collection_id,
    type,
    title,
    body,
    deep_link
  )
  values (
    p_user_id,
    p_collection_id,
    template_row.event_type,
    render_notification_template(template_row.title_template, p_context),
    render_notification_template(template_row.body_template, p_context),
    p_deep_link
  )
  returning id into inserted_id;

  return inserted_id;
end;
$$;


--
-- Name: ensure_current_member_profile(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_current_member_profile(p_whatsapp_phone text, p_country_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare profile_row public.profiles%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if p_country_code is not null and upper(btrim(p_country_code)) <> 'RW' then
    raise exception 'Collect supports Rwanda profiles only';
  end if;
  profile_row := public.ensure_current_profile(p_whatsapp_phone, 'RW');
  if coalesce((
    select flag.enabled from public.feature_flags flag
    where flag.key = 'hybrid_verified_account_claim'
  ), false) then
    perform collect_hybrid.claim_verified_current_account();
  end if;
  return public._member_profile_payload(profile_row);
end;
$$;


--
-- Name: ensure_current_profile(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_current_profile(p_whatsapp_phone text DEFAULT NULL::text, p_country_code text DEFAULT NULL::text) RETURNS public.profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  profile_row public.profiles%rowtype;
  country_rule public.profile_country_rules%rowtype;
  requested_phone text := nullif(btrim(coalesce(p_whatsapp_phone, '')), '');
  verified_phone text;
  clean_phone text;
  clean_country text := upper(nullif(btrim(coalesce(p_country_code, '')), ''));
  resolved_country text;
  default_momo text;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;

  select nullif(btrim(phone), '') into verified_phone
  from auth.users where id = auth.uid();
  clean_phone := coalesce(verified_phone, requested_phone);

  if clean_country is not null then
    select * into country_rule from public.profile_country_rules
    where country_code = clean_country and enabled;
    if country_rule.country_code is null then
      raise exception 'Unsupported profile country';
    end if;
  end if;

  select * into profile_row from public.profiles where id = auth.uid();
  resolved_country := coalesce(profile_row.country_code, clean_country);
  if resolved_country is not null
     and country_rule.country_code is distinct from resolved_country then
    select * into country_rule from public.profile_country_rules
    where country_code = resolved_country and enabled;
  end if;
  default_momo := case
    when resolved_country = 'RW' then public._rwanda_momo_local(clean_phone)
    else null
  end;

  if profile_row.id is null then
    insert into public.profiles (
      id, public_id, whatsapp_phone, country_code, currency_code,
      momo_provider, momo_number, momo_number_hash, momo_number_verified_at
    ) values (
      auth.uid(), public.generate_public_id(), clean_phone, resolved_country,
      country_rule.currency_code,
      case
        when resolved_country <> 'RW' then null
        when default_momo ~ '^07[23]' then 'airtel_money'
        else 'mtn_momo'
      end,
      default_momo,
      case when default_momo is null then null else
        encode(extensions.digest('+250' || substr(default_momo, 2), 'sha256'), 'hex')
      end,
      case when default_momo is null then null else now() end
    ) returning * into profile_row;
  else
    update public.profiles
    set whatsapp_phone = case
          when verified_phone is not null then verified_phone
          when coalesce(profile_row.whatsapp_phone, '') = '' then clean_phone
          else profile_row.whatsapp_phone
        end,
        country_code = resolved_country,
        currency_code = coalesce(profile_row.currency_code, country_rule.currency_code),
        momo_provider = case
          when resolved_country <> 'RW' then null
          when profile_row.momo_provider is not null then profile_row.momo_provider
          when coalesce(profile_row.momo_number, default_momo) ~ '^07[23]'
            then 'airtel_money'
          else 'mtn_momo'
        end,
        momo_number = case
          when resolved_country = 'RW' then coalesce(profile_row.momo_number, default_momo)
          else null
        end,
        momo_number_hash = case
          when resolved_country <> 'RW' then null
          when profile_row.momo_number_hash is not null then profile_row.momo_number_hash
          when default_momo is not null then
            encode(extensions.digest('+250' || substr(default_momo, 2), 'sha256'), 'hex')
          else null
        end,
        momo_number_verified_at = case
          when resolved_country <> 'RW' then null
          when profile_row.momo_number_verified_at is not null
            then profile_row.momo_number_verified_at
          when default_momo is not null then now()
          else null
        end,
        revolut_name = case when resolved_country = 'RW' then null else profile_row.revolut_name end,
        revolut_link = case when resolved_country = 'RW' then null else profile_row.revolut_link end,
        revolut_account = case when resolved_country = 'RW' then null else profile_row.revolut_account end,
        updated_at = now()
    where id = auth.uid()
    returning * into profile_row;
  end if;
  return profile_row;
end;
$$;


--
-- Name: ensure_public_contributor_membership(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_public_contributor_membership(p_collection_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  group_row public.collections%rowtype;
  prior_status text;
  changed_rows integer := 0;
begin
  if p_user_id is null then
    raise exception 'Authenticated contributor is required';
  end if;

  select collection.* into group_row
  from public.collections collection
  where collection.id = p_collection_id
    and collection.archived_at is null
    and collection.public_status = 'public_approved'
  for update;

  if group_row.id is null or group_row.creator_user_id = p_user_id then
    return false;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'public-contributor-membership:' || p_user_id::text || ':' || p_collection_id::text,
    0
  ));

  select member.status::text into prior_status
  from public.collection_members member
  where member.collection_id = p_collection_id
    and member.user_id = p_user_id
    and member.role = 'member'
  for update;

  if prior_status = 'removed' then
    raise exception 'Membership was removed by a group administrator';
  end if;
  if prior_status = 'active' then
    return false;
  end if;

  insert into public.collection_members (collection_id, user_id, role, status)
  values (p_collection_id, p_user_id, 'member', 'active')
  on conflict on constraint collection_members_collection_id_user_id_role_key
  do update set status = 'active'
  where collection_members.status <> 'active';
  get diagnostics changed_rows = row_count;

  if changed_rows > 0 then
    perform public.create_audit_log(
      'group.joined',
      'collection',
      p_collection_id,
      jsonb_build_object('join_method', 'initial_contribution')
    );
    perform public.enqueue_notification_template_event(
      group_row.creator_user_id,
      'group.update.default',
      jsonb_build_object('group', group_row.title),
      p_collection_id,
      '/groups/' || p_collection_id::text || '/members',
      'en'
    );
    return true;
  end if;

  return false;
end;
$$;


