--
-- Name: generate_contribution_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_contribution_code() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  candidate text;
begin
  loop
    candidate := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));
    exit when not exists (select 1 from payment_intents where contribution_code = candidate);
  end loop;
  return candidate;
end;
$$;


--
-- Name: generate_public_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_public_id() RETURNS character
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare candidate char(6); attempts integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('collect-numeric-member-id', 0));
  loop
    candidate := lpad(floor(random() * 1000000)::int::text, 6, '0')::char(6);
    if not exists(select 1 from public.profiles where public_id = candidate)
       and not exists(select 1 from collect_hybrid.member_records where collect_id = candidate) then
      return candidate;
    end if;
    attempts := attempts + 1;
    if attempts >= 1000 then raise exception 'Collect ID allocation requires review'; end if;
  end loop;
end; $$;


--
-- Name: get_active_policy_document(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_policy_document(p_kind text, p_locale text DEFAULT 'en'::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with selected_document as (
    select pd.*
    from policy_documents pd
    where pd.kind = lower(trim(p_kind))
      and pd.locale in (coalesce(nullif(trim(p_locale), ''), 'en'), 'en')
      and pd.status = 'published'
      and pd.effective_at <= now()
    order by
      case when pd.locale = coalesce(nullif(trim(p_locale), ''), 'en') then 0 else 1 end,
      pd.effective_at desc,
      pd.version desc
    limit 1
  )
  select coalesce(
    (
      select jsonb_build_object(
        'id', sd.id,
        'kind', sd.kind,
        'locale', sd.locale,
        'version', sd.version,
        'title', sd.title,
        'summary', sd.summary,
        'effective_at', sd.effective_at,
        'sections', coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'key', pds.section_key,
              'title', pds.title,
              'body', pds.body,
              'display_order', pds.display_order
            )
            order by pds.display_order, pds.section_key
          )
          from policy_document_sections pds
          where pds.policy_document_id = sd.id
        ), '[]'::jsonb)
      )
      from selected_document sd
    ),
    '{}'::jsonb
  );
$$;


--
-- Name: get_bank_transfer_destination(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_bank_transfer_destination() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  destination public.bank_transfer_destinations%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select * into destination
  from public.bank_transfer_destinations
  where currency = 'EUR'
  order by (status = 'active') desc, version desc
  limit 1;

  if destination.id is null then
    return '{}'::jsonb;
  end if;
  return public.bank_transfer_destination_json(destination);
end;
$$;


