-- Name: get_bank_transfer_intent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_bank_transfer_intent(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;
  select to_jsonb(intent) || jsonb_build_object(
    'destination', intent.destination_snapshot,
    'collection_title', collection.title
  ) into result
  from public.bank_transfer_intents intent
  join public.collections collection on collection.id = intent.collection_id
  where intent.id = p_id
    and intent.contributor_user_id = auth.uid();
  return coalesce(result, '{}'::jsonb);
end;
$$;


--
-- Name: get_collect_shadow_run_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_collect_shadow_run_v1(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
declare r collect_security.shadow_supervisor_runs;
begin
  perform collect_security.require_shadow_actor();
  if p_request_id is null then raise exception 'shadow_request_invalid' using errcode='22023';end if;
  -- Read-only reconciliation after normal reauthentication never resumes the
  -- previous session's lease. Only the original actor sees this request lookup.
  select * into r from collect_security.shadow_supervisor_runs
    where request_id=p_request_id and actor_id=auth.uid();
  return jsonb_build_object('contract_version',1,'mode','shadow','scope','collect_platform',
    'found',r.id is not null,'run',collect_security.shadow_run_json(r.id));
end $$;


--
-- Name: get_collection_type_catalog(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_collection_type_catalog(p_country_code text DEFAULT 'RW'::text, p_locale text DEFAULT 'en'::text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'country_code', upper(coalesce(nullif(trim(p_country_code), ''), 'RW')),
    'locale', coalesce(nullif(trim(p_locale), ''), 'en'),
    'types', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'key', ctc.key,
          'label', ctc.label,
          'short_purpose', ctc.short_purpose,
          'icon_key', ctc.icon_key,
          'default_category_subtype', ctc.default_category_subtype,
          'default_purpose_template_key', ctc.default_purpose_template_key,
          'display_order', ctc.display_order,
          'subtypes', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'key', ccs.key,
                'label', ccs.label,
                'display_order', ccs.display_order
              )
              order by ccs.display_order, ccs.key
            )
            from collection_category_subtypes ccs
            where ccs.collection_type_key = ctc.key
              and ccs.enabled
          ), '[]'::jsonb),
          'purpose_templates', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'key', cpt.key,
                'label', cpt.label,
                'display_order', cpt.display_order
              )
              order by cpt.display_order, cpt.key
            )
            from collection_purpose_templates cpt
            where cpt.collection_type_key = ctc.key
              and cpt.enabled
          ), '[]'::jsonb)
        )
        order by ctc.display_order, ctc.key
      )
      from collection_type_catalog ctc
      where ctc.enabled
        and exists (
          select 1
          from collection_type_country_rules ctcr
          where ctcr.collection_type_key = ctc.key
            and ctcr.enabled
            and ctcr.country_code = upper(coalesce(nullif(trim(p_country_code), ''), 'RW'))
        )
    ), '[]'::jsonb)
  );
$$;


