--
-- Name: list_current_user_bank_collection_summaries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_current_user_bank_collection_summaries() RETURNS TABLE(collection_id uuid, amount_raised_rwf bigint, amount_raised_minor bigint, supporter_count bigint, current_user_balance_rwf bigint, current_user_balance_minor bigint, currency text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    collection.id,
    coalesce(sum(transaction.amount_minor) filter (where transaction.status = 'reconciled'), 0)::bigint,
    coalesce(sum(transaction.amount_minor) filter (where transaction.status = 'reconciled'), 0)::bigint,
    count(distinct allocation.contributor_user_id) filter (where transaction.status = 'reconciled')::bigint,
    coalesce(sum(transaction.amount_minor) filter (
      where transaction.status = 'reconciled'
        and allocation.contributor_user_id = auth.uid()
    ), 0)::bigint,
    coalesce(sum(transaction.amount_minor) filter (
      where transaction.status = 'reconciled'
        and allocation.contributor_user_id = auth.uid()
    ), 0)::bigint,
    'EUR'::text
  from public.collections collection
  left join public.bank_transaction_allocations allocation
    on allocation.collection_id = collection.id
  left join public.bank_transactions transaction
    on transaction.id = allocation.bank_transaction_id
  where public.user_can_read_collection(collection.id, auth.uid())
  group by collection.id
  order by collection.id;
$$;


--
-- Name: list_current_user_bank_contributions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_current_user_bank_contributions() RETURNS TABLE(payment_id uuid, collection_id uuid, amount_rwf bigint, amount_minor bigint, currency text, posted_at timestamp with time zone, transaction_id text, supporter_label text, is_current_user_contribution boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select t.id, a.collection_id, t.amount_minor, t.amount_minor, t.currency, t.reconciled_at,
    case when a.contributor_user_id = auth.uid() then coalesce(t.bank_transaction_id, t.end_to_end_id) end,
    case when a.contributor_user_id = auth.uid() then 'Your contribution' else 'Collect member' end,
    a.contributor_user_id = auth.uid()
  from public.bank_transactions t
  join public.bank_transaction_allocations a on a.bank_transaction_id = t.id
  where auth.uid() is not null and t.status = 'reconciled' and
    (a.contributor_user_id = auth.uid() or public.user_can_read_collection(a.collection_id, auth.uid()))
  order by t.reconciled_at desc, t.id;
$$;


--
-- Name: list_current_user_bank_transfer_intents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_current_user_bank_transfer_intents() RETURNS TABLE(id uuid, collection_id uuid, collection_title text, contributor_user_id uuid, destination_id uuid, destination jsonb, transfer_reference text, amount_minor bigint, currency text, status text, handoff_opened_at timestamp with time zone, evidence_received_at timestamp with time zone, reconciled_at timestamp with time zone, exception_reason text, created_at timestamp with time zone, updated_at timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    intent.id,
    intent.collection_id,
    collection.title,
    intent.contributor_user_id,
    intent.destination_id,
    intent.destination_snapshot,
    intent.transfer_reference,
    intent.amount_minor,
    intent.currency,
    case
      when intent.status in ('awaiting_transfer', 'handoff_opened', 'awaiting_bank_evidence')
        and intent.expires_at <= now() then 'expired'
      else intent.status
    end,
    intent.handoff_opened_at,
    intent.evidence_received_at,
    intent.reconciled_at,
    intent.exception_reason,
    intent.created_at,
    intent.updated_at,
    intent.expires_at
  from public.bank_transfer_intents intent
  join public.collections collection on collection.id = intent.collection_id
  where intent.contributor_user_id = auth.uid()
  order by intent.created_at desc;
$$;


--
-- Name: list_current_user_collection_summaries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_current_user_collection_summaries() RETURNS TABLE(collection_id uuid, amount_raised_rwf bigint, supporter_count bigint, current_user_balance_rwf bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select collection.id,
    coalesce(balance.confirmed_rwf, 0)::bigint,
    coalesce((
      select count(distinct coalesce(
        payment.contributor_user_id::text,
        payment.transaction_id,
        payment.id::text
      ))
      from public.payments payment
      where payment.collection_id = collection.id
        and payment.status = 'posted'
    ), 0)::bigint,
    coalesce((
      select sum(member_balance.confirmed_rwf)
      from collect_hybrid.member_balances member_balance
      where member_balance.collection_id = collection.id
        and collect_hybrid.member_record_belongs_to_user(
          member_balance.member_record_id, auth.uid()
        )
    ), 0)::bigint
  from public.collections collection
  left join collect_hybrid.collection_balances balance
    on balance.collection_id = collection.id
  where auth.uid() is not null
    and collection.archived_at is null
    and public.user_can_read_collection(collection.id, auth.uid());
$$;


--
-- Name: list_current_user_collections(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_current_user_collections(p_collection_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  select coalesce(jsonb_agg(
    (to_jsonb(collection) - 'diaspora_enabled' - 'diaspora_regions')
      || jsonb_strip_nulls(jsonb_build_object(
        'payment_rail', route.payment_rail,
        'settlement_currency', route.settlement_currency,
        'receiver_momo_number', route.receiver_momo_number,
        'receiver_display_label', route.receiver_display_label,
        'receiver_network', route.receiver_network
      )) order by collection.created_at desc, collection.id
  ), '[]'::jsonb)
  into result
  from public.member_collections_view collection
  left join lateral public.public_collection_payment_route(collection.id) route on true
  where (p_collection_id is null or collection.id = p_collection_id)
    and public.user_can_read_collection(collection.id, auth.uid());
  return result;
end;
$$;


--
-- Name: FUNCTION list_current_user_collections(p_collection_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_current_user_collections(p_collection_id uuid) IS 'Authenticated member catalogue. Retains collection authorization and private receiver masking; adds only the approved public payment route. Does not grant receiver-table access.';


--
-- Name: user_can_read_collection(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_can_read_collection(collection uuid, user_uuid uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when auth.role() = 'service_role'
      or user_uuid is not distinct from auth.uid() then
      exists (
        select 1
        from public.collections item
        where item.id = collection
          and (
            item.public_status = 'public_approved'
            or item.creator_user_id = user_uuid
            or public.is_platform_admin(user_uuid)
            or exists (
              select 1
              from public.collection_members membership
              where membership.collection_id = item.id
                and membership.status = 'active'
                and (
                  membership.user_id = user_uuid
                  or collect_hybrid.member_record_belongs_to_user(
                    membership.member_record_id, user_uuid
                  )
                )
            )
          )
      )
    else false
  end;
$$;


--
-- Name: FUNCTION user_can_read_collection(collection uuid, user_uuid uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.user_can_read_collection(collection uuid, user_uuid uuid) IS 'Browser callers may evaluate only auth.uid(); anon may evaluate the null default for public discovery; service_role may evaluate arbitrary users.';


--
-- Name: user_is_collection_admin(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_is_collection_admin(collection uuid, user_uuid uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when auth.role() = 'service_role'
      or user_uuid is not distinct from auth.uid() then
      public.is_platform_admin(user_uuid)
      or exists (
        select 1 from public.collections item
        where item.id = collection and item.creator_user_id = user_uuid
      )
      or exists (
        select 1
        from public.collection_members membership
        where membership.collection_id = collection
          and membership.status = 'active'
          and membership.role in ('owner', 'admin', 'receiver')
          and (
            membership.user_id = user_uuid
            or collect_hybrid.member_record_belongs_to_user(
              membership.member_record_id, user_uuid
            )
          )
      )
    else false
  end;
$$;


--
-- Name: FUNCTION user_is_collection_admin(collection uuid, user_uuid uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.user_is_collection_admin(collection uuid, user_uuid uuid) IS 'Browser callers may evaluate only auth.uid(); anon may evaluate the null default for public RLS; service_role may evaluate arbitrary users.';


--
-- Name: member_contributions_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.member_contributions_view WITH (security_invoker='true') AS
 SELECT collection_id,
    id AS payment_id,
    amount_rwf,
    currency,
    status,
    source,
        CASE
            WHEN ((contributor_user_id = auth.uid()) OR public.user_is_collection_admin(collection_id, auth.uid())) THEN transaction_id
            ELSE NULL::text
        END AS transaction_id,
    posted_at,
    created_at,
    (contributor_user_id = auth.uid()) AS is_current_user_contribution,
        CASE
            WHEN (contributor_user_id = auth.uid()) THEN 'You'::text
            WHEN ((anonymity_choice = 'public_id'::text) AND (contributor_public_id IS NOT NULL)) THEN ('Collect ID '::text || (contributor_public_id)::text)
            ELSE 'Anonymous supporter'::text
        END AS supporter_label
   FROM public.payments payment
  WHERE ((status = 'posted'::text) AND public.user_can_read_collection(collection_id, auth.uid()));


--
-- Name: list_current_user_contributions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_current_user_contributions() RETURNS SETOF public.member_contributions_view
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  return query
    select contribution.*
    from public.member_contributions_view contribution
    where public.user_can_read_collection(contribution.collection_id, auth.uid())
    order by contribution.posted_at desc, contribution.payment_id;
end;
$$;


--
-- Name: list_current_user_payment_intents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_current_user_payment_intents() RETURNS TABLE(id uuid, collection_id uuid, expected_amount_rwf bigint, receiver_momo_number text, receiver_momo_number_hash text, receiver_label text, network text, sender_phone_hash text, status public.payment_intent_status, contributor_public_id character, created_at timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  update public.payment_intents intent
  set status = 'expired'
  where intent.contributor_user_id = auth.uid()
    and intent.status = 'pending'
    and intent.expires_at <= now();
  return query
  select
    intent.id,
    intent.collection_id,
    intent.expected_amount_rwf,
    receiver.momo_number,
    intent.receiver_momo_number_hash,
    receiver.label,
    receiver.network,
    intent.sender_phone_hash,
    intent.status,
    intent.contributor_public_id,
    intent.created_at,
    intent.expires_at
  from public.payment_intents intent
  join lateral (
    select route.momo_number, route.label, route.network
    from public.collection_receivers route
    where route.collection_id = intent.collection_id
      and route.momo_number_hash = intent.receiver_momo_number_hash
    order by route.created_at desc
    limit 1
  ) receiver on true
  where intent.contributor_user_id = auth.uid()
  order by intent.created_at desc
  limit 100;
end;
$$;


--
-- Name: list_payment_reconciliations_v2(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_payment_reconciliations_v2(p_payment_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
 perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
 if not coalesce(public.has_admin_permission('payments.read'),false) then
  raise exception 'reconciliation_permission_required' using errcode='42501'; end if;
 if p_limit is null or p_limit not between 1 and 100 or p_offset is null or p_offset<0 or p_offset>100000 then
  raise exception 'reconciliation_invalid_page' using errcode='22023'; end if;
 select jsonb_build_object('total',(select count(*) from collect_security.reconciliation_reviews where p_payment_id is null or payment_id=p_payment_id),
  'rows',coalesce((select jsonb_agg(rowdata order by proposed_at desc,id) from (
   select r.id,r.proposed_at,jsonb_build_object('id',r.id,'payment_id',r.payment_id,'source_reference',r.source_reference,
    'evidence_sha256',r.evidence_sha256,'occurred_at',r.occurred_at,'proposed_by',r.proposed_by,
    'proposed_at',r.proposed_at,'approved_by',r.approved_by,'approved_at',r.approved_at,'consumed_at',r.consumed_at,
    'status',case when r.consumed_at is not null then 'finalized'
      when r.proposed_session_id is null or (r.approved_by is not null and r.approved_session_id is null) then 'legacy_review_required'
      when r.proposed_at<clock_timestamp()-interval '24 hours' or r.approved_at<clock_timestamp()-interval '15 minutes' then 'expired'
      when r.approved_by is not null then 'approved' else 'proposed' end,
    'payment_status',p.status,'amount_rwf',p.amount_rwf,'currency',p.currency) rowdata
   from collect_security.reconciliation_reviews r join public.payments p on p.id=r.payment_id
   where p_payment_id is null or r.payment_id=p_payment_id
   order by r.proposed_at desc,r.id limit p_limit offset p_offset
  ) page),'[]'::jsonb)) into result;
 return result;
end $$;


--
-- Name: lock_notification_auth_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_notification_auth_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public._lock_notification_session_gate();
  return null;
end $$;


--
-- Name: lock_notification_auth_revocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_notification_auth_revocation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- A multi-statement Auth transaction may already hold a shared activity
  -- gate. Never wait while upgrading that lock: another shared reader could
  -- be waiting for this transaction's Auth row. Abort atomically for a whole
  -- transaction retry instead of forming an upgrade deadlock.
  if exists(select 1 from pg_catalog.pg_locks where locktype='advisory'
      and pid=pg_catalog.pg_backend_pid() and classid=193517 and objid=141
      and objsubid=2 and mode='ShareLock' and granted)
    and not exists(select 1 from pg_catalog.pg_locks where locktype='advisory'
      and pid=pg_catalog.pg_backend_pid() and classid=193517 and objid=141
      and objsubid=2 and mode='ExclusiveLock' and granted) then
    if not pg_catalog.pg_try_advisory_xact_lock(193517,141) then
      raise exception 'notification_auth_revocation_retry' using errcode='40001';
    end if;
  else
    perform pg_catalog.pg_advisory_xact_lock(193517,141);
  end if;
  return null;
end $$;


--
-- Name: mark_bank_transfer_handoff_opened(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_bank_transfer_handoff_opened(p_intent_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  intent public.bank_transfer_intents%rowtype;
begin
  update public.bank_transfer_intents
  set status = case when status = 'awaiting_transfer' then 'handoff_opened' else status end,
      handoff_opened_at = coalesce(handoff_opened_at, now()),
      updated_at = now()
  where id = p_intent_id
    and contributor_user_id = auth.uid()
    and status in ('awaiting_transfer', 'handoff_opened', 'awaiting_bank_evidence')
    and expires_at > now()
  returning * into intent;
  if intent.id is null then
    raise exception 'Active bank transfer request not found';
  end if;
  return to_jsonb(intent);
end;
$$;


--
-- Name: mark_notification_event_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_notification_event_read(p_event_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update notification_events
  set status = 'read',
      read_at = now()
  where id = p_event_id
    and user_id = auth.uid();
$$;


--
-- Name: mask_iban(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mask_iban(p_iban text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when char_length(public.normalize_iban(p_iban)) < 8 then 'Unavailable'
    else left(public.normalize_iban(p_iban), 4)
      || repeat('•', greatest(char_length(public.normalize_iban(p_iban)) - 8, 4))
      || right(public.normalize_iban(p_iban), 4)
  end;
$$;


--
-- Name: mask_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mask_phone(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when value is null or length(regexp_replace(value, '\D', '', 'g')) < 6 then null
    else '+***' || right(regexp_replace(value, '\D', '', 'g'), 4)
  end;
$$;


--
-- Name: mint_native_action_capability(uuid, text, text, jsonb, text, text, text, text[], timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mint_native_action_capability(capability_user_id uuid, capability_action text, capability_request_hash text, capability_request_payload jsonb, capability_receiver_hash text, capability_package_name text, capability_app_verdict text, capability_device_verdicts text[], capability_verified_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  capability_id uuid;
  clean_action text := btrim(coalesce(capability_action, ''));
  clean_request_hash text := lower(btrim(coalesce(capability_request_hash, '')));
  clean_receiver_hash text := lower(btrim(coalesce(capability_receiver_hash, '')));
  clean_package_name text := btrim(coalesce(capability_package_name, ''));
  clean_app_verdict text := btrim(coalesce(capability_app_verdict, ''));
  verified_at_value timestamptz := coalesce(capability_verified_at, now());
  latest_consent public.receiver_mode_consents;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Service role required';
  end if;
  if capability_user_id is null
     or clean_action not in ('group.create', 'sms.ingest') then
    raise exception 'Invalid native capability subject or action';
  end if;
  if clean_request_hash !~ '^[0-9a-f]{64}$'
     or clean_receiver_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'Invalid native capability binding';
  end if;
  if jsonb_typeof(capability_request_payload) <> 'object'
     or capability_request_payload ->> 'receiver_momo_number_hash'
       <> clean_receiver_hash then
    raise exception 'Invalid native capability request payload';
  end if;
  if clean_action = 'sms.ingest' and not (
    capability_request_payload ? 'client_envelope_id'
    and capability_request_payload ? 'raw_sender'
    and capability_request_payload ? 'raw_body_sha256'
    and capability_request_payload ->> 'raw_body_sha256' ~ '^[0-9a-f]{64}$'
  ) then
    raise exception 'Invalid attested SMS request payload';
  end if;
  if clean_package_name <> 'app.cool.mobile'
     or clean_app_verdict <> 'PLAY_RECOGNIZED'
     or not (
       'MEETS_DEVICE_INTEGRITY' = any(coalesce(capability_device_verdicts, '{}'))
       or 'MEETS_STRONG_INTEGRITY' = any(coalesce(capability_device_verdicts, '{}'))
     ) then
    raise exception 'Play Integrity verdict is not eligible';
  end if;
  if abs(extract(epoch from (now() - verified_at_value))) > 300 then
    raise exception 'Play Integrity verdict is stale';
  end if;

  select consent.* into latest_consent
  from public.receiver_mode_consents consent
  where consent.user_id = capability_user_id
  order by consent.created_at desc, consent.id desc
  limit 1;
  if latest_consent.id is null
     or not latest_consent.enabled
     or lower(coalesce(latest_consent.momo_number_hash, '')) <> clean_receiver_hash
     or (clean_action = 'sms.ingest'
       and latest_consent.created_at < now() - interval '10 minutes') then
    raise exception 'Current MoMo SMS consent is required';
  end if;

  update public.native_action_capabilities
  set expires_at = least(expires_at, now())
  where user_id = capability_user_id
    and action = clean_action
    and consumed_at is null
    and expires_at > now();

  insert into public.native_action_capabilities(
    user_id, action, request_hash, request_payload,
    receiver_momo_number_hash, package_name, app_verdict,
    device_verdicts, verified_at, expires_at
  ) values (
    capability_user_id, clean_action, clean_request_hash,
    capability_request_payload, clean_receiver_hash, clean_package_name,
    clean_app_verdict, coalesce(capability_device_verdicts, '{}'),
    verified_at_value,
    least(verified_at_value + interval '5 minutes', now() + interval '5 minutes')
  ) returning id into capability_id;
  return capability_id;
end;
$_$;


--
-- Name: normalize_iban(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_iban(p_iban text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select upper(regexp_replace(coalesce(p_iban, ''), '[^A-Za-z0-9]', '', 'g'));
$$;


--
-- Name: normalize_slug(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_slug(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select trim(both '-' from regexp_replace(lower(coalesce(value, 'collection')), '[^a-z0-9]+', '-', 'g'));
$$;


--
-- Name: notification_delivery_is_current(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notification_delivery_is_current(p_delivery_id uuid, p_claim_token uuid, p_attempt_number integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare session_id uuid; begin
  perform public._lock_notification_session_gate();
  select device.registration_session_id into session_id from public.notification_device_tokens device
    join public.notification_deliveries d on d.device_id=device.id where d.id=p_delivery_id;
  if session_id is null then return false; end if;
  perform 1 from auth.sessions s where s.id=session_id
    and (s.not_after is null or s.not_after>clock_timestamp()+interval '30 seconds') for share;
  if not found then return false; end if;
  return exists(select 1 from public.notification_deliveries d
    join public.notification_events event on event.id=d.event_id
    join public.notification_device_tokens device on device.id=d.device_id
    where d.id=p_delivery_id and d.status='processing' and d.claim_token=p_claim_token
      and d.attempt_count=p_attempt_number and d.claim_expires_at>clock_timestamp()+interval '30 seconds'
      and d.claim_user_id=event.user_id and event.user_id=device.user_id
      and device.enabled and device.token is not null and device.provider in ('apns','fcm')
      and device.registration_session_id=session_id
      and public._notification_session_is_live(session_id,device.user_id));
end $$;


--
-- Name: post_payment_from_event(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_payment_from_event(event_id uuid, intent_id uuid, target_collection_id uuid, allocation_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  event_row public.parsed_payment_events;
  intent_row public.payment_intents;
  raw_row public.raw_payment_sms;
  receiver_id uuid;
  candidate_payment_id uuid;
begin
  select event.* into event_row
  from public.parsed_payment_events event
  where event.id = event_id
  for update;
  if event_row.id is null then raise exception 'Parsed event not found'; end if;

  select payment.id into candidate_payment_id
  from public.payments payment
  where payment.parsed_event_id = event_id;
  if candidate_payment_id is not null then return candidate_payment_id; end if;

  if not event_row.is_mobile_money_payment
     or event_row.direction <> 'incoming'
     or event_row.currency <> 'RWF'
     or event_row.amount_rwf is null
     or event_row.amount_rwf <= 0
     or event_row.transaction_id is null
     or event_row.receiver_phone_hash is null
     or event_row.confidence < 0.90 then
    raise exception 'SMS payment evidence is incomplete or below the review threshold';
  end if;

  select intent.* into intent_row
  from public.payment_intents intent
  where intent.id = intent_id
  for update;
  if intent_row.id is null then raise exception 'Payment intent not found'; end if;
  if intent_row.status <> 'pending' or intent_row.expires_at <= now() then
    raise exception 'Payment intent is not active';
  end if;
  if intent_row.collection_id <> target_collection_id
     or intent_row.receiver_momo_number_hash <> event_row.receiver_phone_hash
     or intent_row.expected_amount_rwf <> event_row.amount_rwf then
    raise exception 'Payment intent does not match the SMS evidence';
  end if;
  if event_row.sender_phone_hash is null
     or intent_row.sender_phone_hash is distinct from event_row.sender_phone_hash
     or intent_row.sender_phone_hash is distinct from
       public._authenticated_momo_phone_hash(intent_row.contributor_user_id)
     or (event_row.detected_user_public_id is not null
       and intent_row.contributor_public_id is distinct from
         event_row.detected_user_public_id) then
    raise exception 'Payer identity does not match the payment intent';
  end if;

  select raw.* into raw_row
  from public.raw_payment_sms raw
  where raw.id = event_row.raw_sms_id;
  if raw_row.id is null
     or raw_row.native_action_capability_id is null
     or raw_row.attestation_request_hash is null
     or raw_row.device_attested_at is null
     or coalesce(raw_row.received_at_device, raw_row.ingested_at)
       not between intent_row.created_at - interval '15 minutes'
         and intent_row.expires_at + interval '2 hours' then
    raise exception 'Device-attested SMS evidence is required within the payment intent window';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    event_row.network || ':' || upper(btrim(event_row.transaction_id)), 0
  ));
  select payment.id into candidate_payment_id
  from public.payments payment
  where payment.provider_network = event_row.network
    and upper(btrim(payment.transaction_id)) = upper(btrim(event_row.transaction_id))
  order by payment.created_at
  limit 1;
  if candidate_payment_id is not null then
    update public.parsed_payment_events
    set allocation_status = 'ignored',
        review_reason = 'Duplicate provider transaction evidence'
    where id = event_id;
    return candidate_payment_id;
  end if;

  select receiver.receiver_user_id into receiver_id
  from public.collection_receivers receiver
  where receiver.collection_id = target_collection_id
    and receiver.momo_number_hash = event_row.receiver_phone_hash
    and receiver.is_active
  order by receiver.created_at desc
  limit 1;
  if receiver_id is null or receiver_id <> event_row.receiver_user_id then
    raise exception 'SMS receiver is not configured for the target group';
  end if;

  insert into public.payments(
    parsed_event_id, payment_intent_id, collection_id,
    contributor_user_id, contributor_public_id, receiver_user_id,
    receiver_momo_number_hash, amount_rwf, transaction_id,
    provider_network, source, status, anonymity_choice, posted_at
  ) values (
    event_id, intent_id, target_collection_id,
    intent_row.contributor_user_id, intent_row.contributor_public_id, receiver_id,
    event_row.receiver_phone_hash, event_row.amount_rwf, event_row.transaction_id,
    event_row.network, 'sms_auto', 'review', intent_row.anonymity_choice, null
  ) returning id into candidate_payment_id;

  insert into public.payment_allocations(
    payment_id, parsed_event_id, collection_id, payment_intent_id,
    allocated_by, allocation_method, confidence, reason
  ) values (
    candidate_payment_id, event_id, target_collection_id, intent_id,
    null, 'auto_native_sms', event_row.confidence,
    allocation_reason || '; awaiting independent provider confirmation'
  );
  update public.parsed_payment_events
  set allocation_status = 'needs_review',
      review_reason = 'Matched to one payer-verified intent; awaiting independent provider confirmation'
  where id = event_id;
  update public.payment_intents set status = 'matched' where id = intent_id;
  perform collect_hybrid.record_momo_exception(
    event_id, 'provider_confirmation_pending',
    jsonb_build_object('payment_id', candidate_payment_id, 'payment_intent_id', intent_id)
  );
  perform public.create_audit_log(
    'payment.awaiting_provider_confirmation', 'payment', candidate_payment_id,
    jsonb_build_object(
      'parsed_event_id', event_id,
      'payment_intent_id', intent_id,
      'method', 'native_sms_candidate',
      'ledger_posted', false
    ),
    null
  );
  return candidate_payment_id;
end;
$$;


--
-- Name: FUNCTION post_payment_from_event(event_id uuid, intent_id uuid, target_collection_id uuid, allocation_reason text); Type: COMMENT; Schema: public; Owner: -
