--
-- Name: render_notification_template(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.render_notification_template(p_template text, p_context jsonb DEFAULT '{}'::jsonb) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  rendered text := coalesce(p_template, '');
  context_entry record;
begin
  for context_entry in
    select key, value
    from jsonb_each_text(coalesce(p_context, '{}'::jsonb))
  loop
    rendered := replace(rendered, '{{' || context_entry.key || '}}', context_entry.value);
  end loop;
  return rendered;
end;
$$;


