CREATE FUNCTION public.reserve_roster_resources(p_actor_id uuid, p_session_id uuid, p_request_id uuid, p_source_sha256 text, p_source_kind text, p_source_bytes bigint, p_derived_sha256 text) RETURNS jsonb
