    AS $$
   begin perform collect_hybrid.guard_roster_service_recovery((select id from collect_hybrid.roster_import_sources where request_id=p_request_id)); return collect_hybrid.reserve_roster_resources_guarded_149(p_actor_id,p_session_id,p_request_id,p_source_sha256,p_source_kind,p_source_bytes,p_derived_sha256); end $$;


--
-- Name: reserve_signed_otp_v2(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_signed_otp_v2(p_hook_id text, p_payload_hash text, p_phone_hash text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r jsonb;
begin
 r:=public.reserve_signed_otp_v3(p_hook_id,p_payload_hash,p_phone_hash);
 if r=to_jsonb('throttled'::text) then return 'throttled'; end if;
 return case when r->>'state' in ('accepted','delivered') then 'already_sent' else 'unresolved' end;
end $$;


--
-- Name: reserve_signed_otp_v3(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_signed_otp_v3(p_hook_id text, p_payload_hash text, p_phone_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare p collect_security.otp_policy; r collect_security.signed_otp_requests; t timestamptz;
begin
 perform collect_security.require_otp_service_v3();
 if p_hook_id is null or char_length(p_hook_id) not between 1 and 256
   or p_hook_id !~ '^[A-Za-z0-9_:.-]+$' or p_payload_hash is null
   or p_payload_hash !~ '^[a-f0-9]{64}$' or p_phone_hash is null or p_phone_hash !~ '^[a-f0-9]{64}$' then
   raise exception 'OTP identity unavailable' using errcode='22023';
 end if;
 -- Consistent policy->request->phone order fences simultaneous quota decisions.
 update collect_security.otp_policy set enabled=enabled where singleton returning * into p;
 if p.singleton is null then raise exception 'OTP policy unavailable' using errcode='55000'; end if;
 select * into r from collect_security.signed_otp_requests where hook_id=p_hook_id for update;
 if r.hook_id is not null then
   if r.payload_hash<>p_payload_hash or r.phone_hash<>p_phone_hash then
     raise exception 'OTP identity conflict' using errcode='22023';
   end if;
   perform collect_security.otp_expire_v3(r.hook_id);
   select * into r from collect_security.signed_otp_requests where hook_id=p_hook_id;
   return collect_security.otp_receipt_v3(r);
 end if;
 if not p.enabled then raise exception 'OTP policy unavailable' using errcode='55000'; end if;
 t:=clock_timestamp();
 if (select count(*) from collect_security.signed_otp_requests where requested_at>=t-interval '1 hour')>=p.global_hourly_limit
   or (select count(*) from collect_security.signed_otp_requests where requested_at>=t-interval '24 hours')>=p.global_daily_limit then
   return to_jsonb('throttled'::text);
 end if;
 if not public.reserve_otp_request(p_phone_hash,null) then return to_jsonb('throttled'::text); end if;
 insert into collect_security.signed_otp_requests(hook_id,payload_hash,phone_hash,requested_at)
 values(p_hook_id,p_payload_hash,p_phone_hash,t) returning * into r;
 return collect_security.otp_receipt_v3(r);
end $_$;


--
-- Name: resolve_collection_catalog_choice(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_collection_catalog_choice(p_collection_type text DEFAULT 'ikimina'::text, p_category_subtype text DEFAULT NULL::text, p_purpose_label text DEFAULT NULL::text, p_country_code text DEFAULT 'RW'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  clean_type text := coalesce(nullif(trim(p_collection_type), ''), 'ikimina');
  clean_subtype text := nullif(trim(p_category_subtype), '');
  clean_purpose text := nullif(trim(p_purpose_label), '');
  clean_country text := upper(coalesce(nullif(trim(p_country_code), ''), 'RW'));
  catalog_row collection_type_catalog%rowtype;
  subtype_row collection_category_subtypes%rowtype;
  purpose_row collection_purpose_templates%rowtype;
begin
  select *
  into catalog_row
  from collection_type_catalog ctc
  where ctc.key = clean_type
    and ctc.enabled
    and exists (
      select 1
      from collection_type_country_rules ctcr
      where ctcr.collection_type_key = ctc.key
        and ctcr.country_code = clean_country
        and ctcr.enabled
    );

  if catalog_row.key is null then
    raise exception 'Unsupported collection type';
  end if;

  clean_subtype := coalesce(clean_subtype, catalog_row.default_category_subtype);
  select *
  into subtype_row
  from collection_category_subtypes ccs
  where ccs.collection_type_key = clean_type
    and ccs.key = clean_subtype
    and ccs.enabled;

  if subtype_row.key is null then
    raise exception 'Unsupported collection subtype';
  end if;

  if clean_purpose is null then
    select *
    into purpose_row
    from collection_purpose_templates cpt
    where cpt.collection_type_key = clean_type
      and cpt.key = catalog_row.default_purpose_template_key
      and cpt.enabled;
  else
    select *
    into purpose_row
    from collection_purpose_templates cpt
    where cpt.collection_type_key = clean_type
      and cpt.label = clean_purpose
      and cpt.enabled;
  end if;

  if purpose_row.key is null then
    raise exception 'Unsupported collection purpose';
  end if;

  return jsonb_build_object(
    'collection_type', clean_type,
    'category_subtype', subtype_row.key,
    'purpose_label', purpose_row.label
  );
end;
$$;


--
-- Name: revoke_notification_session_devices(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_notification_session_devices() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare device_id uuid; begin
  if tg_op='UPDATE' and new.id=old.id and new.user_id=old.user_id
    and new.created_at is not distinct from old.created_at
    and new.aal::text in ('aal1','aal2')
    and (new.not_after is null or new.not_after>clock_timestamp()) then return new; end if;
  -- The Auth row is already locked by DELETE/UPDATE. Stable device order matches
  -- worker and registration session -> device -> delivery/event locking.
  for device_id in select device.id from public.notification_device_tokens device
      where device.registration_session_id=old.id order by device.id for update loop
    update public.notification_device_tokens set enabled=false, disabled_at=clock_timestamp(),
      disabled_reason='registration_session_revoked', updated_at=clock_timestamp()
    where id=device_id and registration_session_id=old.id;
  end loop;
  if tg_op='DELETE' then return old; else return new; end if;
end $$;


--
-- Name: revoke_notification_user_devices(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_notification_user_devices() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare device_id uuid;
begin
  if new.id=old.id and new.deleted_at is null and not coalesce(new.is_anonymous,false)
    and (new.phone_confirmed_at is not null or new.email_confirmed_at is not null)
    and (new.banned_until is null or new.banned_until<=clock_timestamp()) then return new; end if;
  for device_id in select device.id from public.notification_device_tokens device
      where device.user_id=old.id and device.enabled order by device.id for update loop
    update public.notification_device_tokens set enabled=false,disabled_at=clock_timestamp(),
      disabled_reason='registration_user_revoked',updated_at=clock_timestamp()
      where id=device_id and user_id=old.id and enabled;
  end loop;
  return new;
end $$;


--
-- Name: rotate_group_share_code(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rotate_group_share_code(p_collection_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  code uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;
  if not public.user_is_collection_admin(p_collection_id, auth.uid()) then
    raise exception 'Only group admins can rotate the share link';
  end if;
  if exists (
    select 1 from public.collections c
    where c.id = p_collection_id and c.archived_at is not null
  ) then
    raise exception 'Archived groups cannot be shared';
  end if;

  insert into public.collection_share_secrets (
    collection_id,
    share_code,
    rotated_at,
    rotated_by
  )
  values (p_collection_id, gen_random_uuid(), now(), auth.uid())
  on conflict (collection_id) do update
  set share_code = gen_random_uuid(),
      rotated_at = now(),
      rotated_by = auth.uid()
  returning share_code into code;

  perform public.create_audit_log(
    'group.share_link_rotated',
    'collection',
    p_collection_id,
    jsonb_build_object('rotated_at', now())
  );
  return code::text;
end;
$$;


--
-- Name: run_daily_bank_reconciliation(date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_daily_bank_reconciliation(p_run_date date DEFAULT CURRENT_DATE, p_reason text DEFAULT 'scheduled daily reconciliation'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  run_row public.reconciliation_runs%rowtype;
  v_statement_count integer := 0;
  v_matched_count integer := 0;
  v_exception_count integer := 0;
  v_statement_total bigint := 0;
  v_matched_total bigint := 0;
  transitioned record;
begin
  if p_run_date is null or p_run_date > current_date then
    raise exception 'Reconciliation date must not be in the future';
  end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'Reconciliation reason is required';
  end if;
  if auth.role() <> 'service_role'
     and session_user not in ('postgres', 'supabase_admin')
     and not public.has_admin_permission('bank_reconciliation.manage', auth.uid()) then
    raise exception 'Bank reconciliation permission required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('bank-reconciliation:EUR:' || p_run_date::text, 0));

  insert into public.reconciliation_runs (
    run_date, currency, status, reason, started_by, started_at, completed_at
  ) values (
    p_run_date,
    'EUR',
    'running',
    btrim(p_reason),
    case when auth.uid() is null then null else auth.uid() end,
    now(),
    null
  )
  on conflict (run_date, currency) do update set
    status = 'running',
    reason = excluded.reason,
    started_by = excluded.started_by,
    started_at = now(),
    completed_at = null
  returning * into run_row;

  insert into public.reconciliation_matches (
    run_id, statement_line_id, bank_transaction_id, match_method
  )
  select
    run_row.id,
    line.id,
    candidate.id,
    case
      when line.bank_transaction_id is not null
        and upper(line.bank_transaction_id) = upper(candidate.bank_transaction_id)
        then 'bank_transaction_id'
      when line.end_to_end_id is not null
        and upper(line.end_to_end_id) = upper(candidate.end_to_end_id)
        then 'end_to_end_id'
      else 'reference_amount'
    end
  from public.bank_statement_lines line
  join lateral (
    select transaction.*
    from public.bank_transactions transaction
    where transaction.currency = line.currency
      and transaction.amount_minor = line.amount_minor
      and (
        (line.bank_transaction_id is not null
          and transaction.bank_transaction_id is not null
          and upper(line.bank_transaction_id) = upper(transaction.bank_transaction_id))
        or (line.end_to_end_id is not null
          and transaction.end_to_end_id is not null
          and upper(line.end_to_end_id) = upper(transaction.end_to_end_id))
        or (line.transfer_reference is not null
          and transaction.transfer_reference is not null
          and upper(line.transfer_reference) = upper(transaction.transfer_reference)
          and abs(line.value_date - coalesce(transaction.value_date, transaction.occurred_at::date)) <= 2)
      )
    order by
      (line.bank_transaction_id is not null
        and transaction.bank_transaction_id is not null
        and upper(line.bank_transaction_id) = upper(transaction.bank_transaction_id)) desc,
      (line.end_to_end_id is not null
        and transaction.end_to_end_id is not null
        and upper(line.end_to_end_id) = upper(transaction.end_to_end_id)) desc,
      transaction.created_at
    limit 1
  ) candidate on true
  where line.currency = 'EUR'
    and line.value_date = p_run_date
  on conflict (statement_line_id) do nothing;

  update public.bank_statement_lines line
  set match_status = 'matched'
  from public.reconciliation_matches match
  where match.run_id = run_row.id
    and match.statement_line_id = line.id;

  for transitioned in
    select
      transaction.id as transaction_id,
      transaction.amount_minor,
      transaction.currency,
      transaction.transfer_reference,
      allocation.collection_id,
      allocation.contributor_user_id,
      allocation.bank_transfer_intent_id,
      intent.status as prior_intent_status
    from public.reconciliation_matches match
    join public.bank_transactions transaction on transaction.id = match.bank_transaction_id
    join public.bank_transaction_allocations allocation on allocation.bank_transaction_id = transaction.id
    join public.bank_transfer_intents intent on intent.id = allocation.bank_transfer_intent_id
    where match.run_id = run_row.id
    order by transaction.id
  loop
    update public.bank_transactions
    set status = 'reconciled',
        reconciled_at = coalesce(reconciled_at, now()),
        updated_at = now()
    where id = transitioned.transaction_id;

    update public.bank_transfer_intents
    set status = 'reconciled',
        reconciled_at = coalesce(reconciled_at, now()),
        updated_at = now()
    where id = transitioned.bank_transfer_intent_id;

    insert into public.journal_entries (
      bank_transaction_id,
      collection_id,
      entry_type,
      currency,
      external_reference,
      description,
      created_by
    ) values (
      transitioned.transaction_id,
      transitioned.collection_id,
      'bank_receipt',
      transitioned.currency,
      coalesce(transitioned.transfer_reference, transitioned.transaction_id::text),
      'Reconciled SEPA bank transfer receipt',
      case when auth.uid() is null then null else auth.uid() end
    )
    on conflict (bank_transaction_id, entry_type) do nothing;

    insert into public.journal_lines (
      journal_entry_id,
      account_code,
      collection_id,
      contributor_user_id,
      direction,
      amount_minor,
      currency,
      metadata
    )
    select
      entry.id,
      line.account_code,
      transitioned.collection_id,
      transitioned.contributor_user_id,
      line.direction,
      transitioned.amount_minor,
      transitioned.currency,
      jsonb_build_object(
        'bank_transaction_id', transitioned.transaction_id,
        'bank_transfer_intent_id', transitioned.bank_transfer_intent_id,
        'reconciliation_run_id', run_row.id
      )
    from public.journal_entries entry
    cross join (
      values
        ('bank_cash:EUR'::text, 'debit'::text),
        ('collection_liability'::text, 'credit'::text)
    ) as line(account_code, direction)
    where entry.bank_transaction_id = transitioned.transaction_id
      and entry.entry_type = 'bank_receipt'
    on conflict (journal_entry_id, account_code, direction) do nothing;

    if transitioned.prior_intent_status <> 'reconciled' then
      insert into public.notification_events (
        user_id,
        collection_id,
        bank_transfer_intent_id,
        type,
        title,
        body,
        deep_link
      ) values (
        transitioned.contributor_user_id,
        transitioned.collection_id,
        transitioned.bank_transfer_intent_id,
        'contribution_confirmed',
        'Bank transfer reconciled',
        'Your SEPA bank transfer has been reconciled and added to the confirmed group ledger.',
        '/groups/' || transitioned.collection_id::text || '/ledger'
      ) on conflict (bank_transfer_intent_id, type)
        where bank_transfer_intent_id is not null and type = 'contribution_confirmed'
        do nothing;
    end if;
  end loop;

  insert into public.reconciliation_exceptions (
    run_id, statement_line_id, exception_type, details
  )
  select
    run_row.id,
    line.id,
    'unmatched_statement_line',
    jsonb_build_object(
      'amount_minor', line.amount_minor,
      'currency', line.currency,
      'transfer_reference', line.transfer_reference,
      'value_date', line.value_date
    )
  from public.bank_statement_lines line
  where line.currency = 'EUR'
    and line.value_date = p_run_date
    and line.match_status = 'unmatched'
    and not exists (
      select 1 from public.reconciliation_exceptions exception
      where exception.statement_line_id = line.id
        and exception.exception_type = 'unmatched_statement_line'
        and exception.status in ('open', 'reviewing')
    );

  insert into public.reconciliation_exceptions (
    run_id, bank_transaction_id, bank_transfer_intent_id,
    exception_type, details
  )
  select
    run_row.id,
    transaction.id,
    allocation.bank_transfer_intent_id,
    'missing_statement_confirmation',
    jsonb_build_object(
      'amount_minor', transaction.amount_minor,
      'currency', transaction.currency,
      'transfer_reference', transaction.transfer_reference,
      'occurred_at', transaction.occurred_at
    )
  from public.bank_transactions transaction
  join public.bank_transaction_allocations allocation
    on allocation.bank_transaction_id = transaction.id
  where transaction.currency = 'EUR'
    and coalesce(transaction.value_date, transaction.occurred_at::date) <= p_run_date
    and transaction.status = 'received'
    and not exists (
      select 1 from public.reconciliation_matches match
      where match.bank_transaction_id = transaction.id
    )
    and not exists (
      select 1 from public.reconciliation_exceptions exception
      where exception.bank_transaction_id = transaction.id
        and exception.exception_type = 'missing_statement_confirmation'
        and exception.status in ('open', 'reviewing')
    );

  update public.bank_statement_imports import
  set status = case
        when exists (
          select 1 from public.bank_statement_lines line
          where line.import_id = import.id and line.match_status in ('unmatched', 'exception')
        ) then 'processed'
        else 'reconciled'
      end,
      completed_at = now()
  where import.currency = 'EUR'
    and import.period_start <= p_run_date
    and import.period_end >= p_run_date;

  select count(*), coalesce(sum(amount_minor), 0)
  into v_statement_count, v_statement_total
  from public.bank_statement_lines
  where currency = 'EUR' and value_date = p_run_date;

  select count(*), coalesce(sum(line.amount_minor), 0)
  into v_matched_count, v_matched_total
  from public.reconciliation_matches match
  join public.bank_statement_lines line on line.id = match.statement_line_id
  where match.run_id = run_row.id;

  select count(*) into v_exception_count
  from public.reconciliation_exceptions
  where run_id = run_row.id and status in ('open', 'reviewing');

  update public.reconciliation_runs
  set status = case when v_exception_count = 0 then 'completed' else 'completed_with_exceptions' end,
      statement_line_count = v_statement_count,
      matched_count = v_matched_count,
      exception_count = v_exception_count,
      statement_total_minor = v_statement_total,
      matched_total_minor = v_matched_total,
      completed_at = now()
  where id = run_row.id
  returning * into run_row;

  insert into public.daily_bank_closes (
    close_date,
    currency,
    statement_total_minor,
    reconciled_total_minor,
    variance_minor,
    transaction_count,
    exception_count,
    status,
    reconciliation_run_id,
    closed_at,
    closed_by
  ) values (
    p_run_date,
    'EUR',
    v_statement_total,
    v_matched_total,
    v_statement_total - v_matched_total,
    v_matched_count,
    v_exception_count,
    case
      when v_exception_count = 0 and v_statement_total = v_matched_total then 'balanced'
      else 'exception'
    end,
    run_row.id,
    case
      when v_exception_count = 0 and v_statement_total = v_matched_total then now()
      else null
    end,
    case
      when v_exception_count = 0 and v_statement_total = v_matched_total then auth.uid()
      else null
    end
  ) on conflict (close_date, currency) do update set
    statement_total_minor = excluded.statement_total_minor,
    reconciled_total_minor = excluded.reconciled_total_minor,
    variance_minor = excluded.variance_minor,
    transaction_count = excluded.transaction_count,
    exception_count = excluded.exception_count,
    status = excluded.status,
    reconciliation_run_id = excluded.reconciliation_run_id,
    closed_at = excluded.closed_at,
    closed_by = excluded.closed_by,
    updated_at = now();

  perform public.create_audit_log(
    'bank_reconciliation.completed',
    'reconciliation_run',
    run_row.id,
    jsonb_build_object(
      'run_date', p_run_date,
      'currency', 'EUR',
      'statement_line_count', v_statement_count,
      'matched_count', v_matched_count,
      'exception_count', v_exception_count,
      'statement_total_minor', v_statement_total,
      'matched_total_minor', v_matched_total
    ),
    auth.uid()
  );

  return to_jsonb(run_row) || jsonb_build_object(
    'variance_minor', v_statement_total - v_matched_total
  );
exception
  when others then
    if run_row.id is not null then
      update public.reconciliation_runs
      set status = 'failed', completed_at = now()
      where id = run_row.id;
    end if;
    raise;
end;
$$;


--
-- Name: run_notification_dispatch_schedule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_notification_dispatch_schedule() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare config jsonb; request_id bigint; begin
  -- Prevent duplicate wake-ups inside one scheduler transaction. Claims remain
  -- independently fenced across overlapping Edge invocations.
  if not pg_try_advisory_xact_lock(193517, 139) then return null; end if;
  config := public._notification_dispatch_configuration();
  if not exists (select 1 from public.notification_deliveries d
    where (d.status = 'queued' and d.next_attempt_at <= clock_timestamp())
       or (d.status = 'processing' and d.claim_expires_at <= clock_timestamp())) then return null; end if;
  select net.http_post(url := config->>'url', headers := config->'headers',
    body := '{"limit":100}'::jsonb, timeout_milliseconds := 65000) into request_id;
  return request_id;
end $$;


--
-- Name: sample_collect_shadow_run_v1(uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sample_collect_shadow_run_v1(p_run_id uuid, p_fence_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
declare sid uuid; l collect_security.shadow_supervisor_lease;
  r collect_security.shadow_supervisor_runs; s collect_security.shadow_supervisor_samples;
  t timestamptz; health jsonb; sms jsonb; counts jsonb; summary jsonb; body jsonb;
begin
  sid:=collect_security.require_shadow_actor();
  if p_run_id is null or p_fence_version is null or p_fence_version not between 1 and 1000000000 then
    raise exception 'shadow_request_invalid' using errcode='22023';end if;
  -- A manual health sample must use current statement snapshots, not an older
  -- caller-created Repeatable Read view presented with a fresh checked_at.
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception 'shadow_snapshot_retry' using errcode='40001';end if;
  select * into l from collect_security.shadow_supervisor_lease where id for update;
  select * into r from collect_security.shadow_supervisor_runs where id=p_run_id for update;
  if r.id is null or r.actor_id is distinct from auth.uid() or r.session_id is distinct from sid then
    raise exception 'shadow_run_unavailable' using errcode='42501';end if;
  if r.fence_version<>p_fence_version or l.active_run_id is distinct from r.id
    or l.fence_version<>p_fence_version or r.status<>'running' then
    raise exception 'shadow_fence_lost' using errcode='40001';end if;
  if r.lease_expires_at<=clock_timestamp() or l.lease_expires_at<=clock_timestamp() then
    raise exception 'shadow_lease_expired' using errcode='55000';end if;
  select * into s from collect_security.shadow_supervisor_samples where run_id=r.id;
  if s.id is not null then
    perform collect_security.shadow_run_json(r.id);
    perform collect_security.require_shadow_health(s.body->'system_health',r.started_at,clock_timestamp());
    return jsonb_build_object('contract_version',1,'mode','shadow','scope','collect_platform',
      'ok',true,'outcome','sampled','replayed',true,'run_id',r.id,'fence_version',r.fence_version,
      'sample',s.body||jsonb_build_object('sample_id',s.id,'content_sha256',s.content_sha256));
  end if;
  health:=public.admin_system_health('system');
  t:=clock_timestamp();
  perform collect_security.require_shadow_health(health,r.started_at,t);
  -- Same aggregate semantics as the assisted operator's health, without its
  -- service-only identity wrapper, full destinations, bodies or receipt IDs.
  select jsonb_build_object('enabled',coalesce((select enabled from public.feature_flags
    where key='hybrid_sms_notifications'),false),
    'queued',count(*) filter(where state='queued'),
    'awaiting_confirmation',count(*) filter(where state='awaiting_confirmation'),
    'send_started',count(*) filter(where state='send_started'),
    'uncertain',count(*) filter(where state='uncertain'),
    'suppressed',count(*) filter(where state='suppressed'),
    'oldest_queued_at',min(created_at) filter(where state='queued'),
    'active_workers',(select count(*) from collect_hybrid.sms_operator_heartbeats
      where observed_at>t-interval '3 minutes'),'observed_at',t)
  into sms from collect_hybrid.sms_notification_outbox;
  select jsonb_build_object('ok',count(*) filter(where a->>'state'='ok'),
    'unknown',count(*) filter(where a->>'state'='unknown'),
    'attention',count(*) filter(where a->>'state'='attention'),
    'not_applicable',count(*) filter(where a->>'state'='not_applicable'))
  into counts from jsonb_array_elements(health->'alerts') a;
  summary:=jsonb_build_object('health_status',case when health->>'health_status'='attention'
    or (sms->>'uncertain')::bigint>0 or (sms->>'send_started')::bigint>0 then 'attention'
    else health->>'health_status' end,'alert_counts',counts,
    'sms_queue',sms-array['oldest_queued_at','observed_at'],
    'checks_recorded',13,'samples_recorded',1,'business_mutations',0,'provider_sends',0);
  t:=clock_timestamp();
  if r.lease_expires_at<=t or l.lease_expires_at<=t then
    raise exception 'shadow_lease_expired' using errcode='55000';end if;
  perform collect_security.require_shadow_health(health,r.started_at,t);
  body:=jsonb_build_object('checked_at',t,'system_health',health,'sms_queue',sms,'summary',summary);
  insert into collect_security.shadow_supervisor_samples(run_id,checked_at,body,content_sha256)
  values(r.id,t,body,encode(extensions.digest(convert_to(body::text,'UTF8'),'sha256'),'hex'))
  returning * into s;
  return jsonb_build_object('contract_version',1,'mode','shadow','scope','collect_platform',
    'ok',true,'outcome','sampled','replayed',false,'run_id',r.id,'fence_version',r.fence_version,
    'sample',s.body||jsonb_build_object('sample_id',s.id,'content_sha256',s.content_sha256));
end $$;


--
-- Name: FUNCTION sample_collect_shadow_run_v1(p_run_id uuid, p_fence_version bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sample_collect_shadow_run_v1(p_run_id uuid, p_fence_version bigint) IS 'Stores one immutable server-derived redacted health and assisted-SMS aggregate sample; never mutates business or sending state.';


--
-- Name: set_notification_preferences_v2(jsonb, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_notification_preferences_v2(p_preferences jsonb, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare receipt jsonb;begin
 perform collect_security.runtime_control_actor('notification_preferences');
 if p_preferences is null or jsonb_typeof(p_preferences)<>'object' then raise exception 'runtime_control_patch_invalid' using errcode='22023';end if;
 if (select array_agg(key order by key) from jsonb_object_keys(p_preferences) key) is distinct from
  array['contribution_confirmations','group_updates','payment_reminders','security_notices']::text[] then raise exception 'runtime_control_patch_invalid' using errcode='22023';end if;
 receipt:=public.admin_update_runtime_control_v1('notification_preferences',jsonb_build_object('user_id',auth.uid()),p_preferences,p_expected_revision,'User notification preferences update');
 return (receipt-array['family','identity','content_sha256'])||jsonb_build_object('contract_version',2,'user_id',auth.uid());
end $$;


--
-- Name: touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: transfer_group_ownership(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_group_ownership(collection uuid, new_owner_public_id text) RETURNS void
    LANGUAGE sql
    SET search_path TO ''
    AS $$ select collect_member_actions.transfer_owned_group(collection,new_owner_public_id); $$;


--
-- Name: unregister_notification_device(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unregister_notification_device(p_provider text, p_token text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  current_user_id uuid := (select auth.uid());
  current_session_id uuid;
  clean_provider text := lower(trim(coalesce(p_provider, '')));
  token_digest text := encode(
    extensions.digest(trim(coalesce(p_token, '')), 'sha256'),
    'hex'
  );
begin
  current_session_id := public._lock_notification_registration_session();
  update notification_device_tokens
  set enabled = false,
      disabled_at = now(),
      disabled_reason = 'user_signed_out',
      updated_at = now()
  where user_id = current_user_id
    and registration_session_id = current_session_id
    and provider = clean_provider
    and token_hash = token_digest;
end;
$$;


--
-- Name: update_bank_transfer_group_profile(uuid, text, text, text, text, boolean, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_bank_transfer_group_profile(p_collection_id uuid, p_group_name text, p_group_description text, p_group_image_url text DEFAULT NULL::text, p_group_accent_color_hex text DEFAULT NULL::text, p_group_is_public boolean DEFAULT false, p_group_recurring_cadence text DEFAULT 'monthly'::text, p_group_collection_type text DEFAULT NULL::text, p_group_category_subtype text DEFAULT NULL::text, p_group_purpose_label text DEFAULT NULL::text, p_group_is_recurring boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  preserve_platform_public boolean;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not exists (
    select 1 from public.collections collection
    where collection.id = p_collection_id
      and collection.creator_user_id = auth.uid()
      and collection.archived_at is null
  ) then raise exception 'Only the current group owner can update group settings'; end if;
  select collection.public_status = 'public_approved'
  into preserve_platform_public
  from public.collections collection
  where collection.id = p_collection_id;
  perform public.update_collection_profile(
    p_collection_id, p_group_name, p_group_description,
    p_group_image_url, p_group_accent_color_hex,
    preserve_platform_public, p_group_recurring_cadence, p_group_collection_type,
    p_group_category_subtype, p_group_purpose_label, p_group_is_recurring
  );
end;
$$;


--
-- Name: update_collection_profile(uuid, text, text, text, text, boolean, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_collection_profile(collection uuid, group_name text, group_description text, group_image_url text DEFAULT NULL::text, group_accent_color_hex text DEFAULT NULL::text, group_is_public boolean DEFAULT false, group_recurring_cadence text DEFAULT 'monthly'::text, group_collection_type text DEFAULT NULL::text, group_category_subtype text DEFAULT NULL::text, group_purpose_label text DEFAULT NULL::text, group_is_recurring boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  clean_name text := trim(coalesce(group_name, ''));
  clean_description text := trim(coalesce(group_description, ''));
  clean_cadence text := coalesce(nullif(trim(group_recurring_cadence), ''), 'monthly');
  clean_type text;
  clean_subtype text;
  clean_purpose_label text;
  catalog_choice jsonb;
  current_row public.collections;
  next_public_status public.collection_visibility;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not public.user_is_collection_admin(collection, auth.uid()) then
    raise exception 'Only collection admins can update the group profile';
  end if;
  if char_length(clean_name) not between 3 and 120 then
    raise exception 'Group name must be between 3 and 120 characters';
  end if;
  if char_length(clean_description) > 1000 then
    raise exception 'Group description must be 1000 characters or fewer';
  end if;
  if clean_cadence not in ('daily', 'weekly', 'monthly') then
    raise exception 'Unsupported recurring cadence';
  end if;

  select c.* into current_row from public.collections c where c.id = collection;
  if current_row.id is null then raise exception 'Group not found'; end if;
  if current_row.archived_at is not null then raise exception 'Archived groups cannot be updated'; end if;

  next_public_status := case
    when not coalesce(group_is_public, false) then 'private'::public.collection_visibility
    when current_row.public_status = 'public_approved' then 'public_approved'::public.collection_visibility
    else 'public_requested'::public.collection_visibility
  end;

  catalog_choice := public.resolve_collection_catalog_choice(
    coalesce(nullif(trim(group_collection_type), ''), current_row.collection_type),
    coalesce(nullif(trim(group_category_subtype), ''), current_row.category_subtype),
    coalesce(nullif(trim(group_purpose_label), ''), current_row.purpose_label),
    'RW'
  );
  clean_type := catalog_choice->>'collection_type';
  clean_subtype := catalog_choice->>'category_subtype';
  clean_purpose_label := catalog_choice->>'purpose_label';

  update public.collections
  set title = clean_name,
      description = clean_description,
      cover_image_url = nullif(trim(group_image_url), ''),
      accent_color_hex = nullif(trim(group_accent_color_hex), ''),
      public_status = next_public_status,
      visibility = case
        when next_public_status = 'public_approved' then 'public_approved'::public.collection_visibility
        else 'private'::public.collection_visibility
      end,
      is_recurring = coalesce(group_is_recurring, false),
      recurring_cadence = clean_cadence,
      recurring_rule = case
        when coalesce(group_is_recurring, false)
          then jsonb_build_object('cadence', clean_cadence)
        else null
      end,
      collection_type = clean_type,
      category_subtype = clean_subtype,
      purpose_label = clean_purpose_label,
      updated_at = now()
  where id = collection;

  perform public.create_audit_log(
    'collection.profile_updated',
    'collection',
    collection,
    jsonb_build_object(
      'public_status', next_public_status::text,
      'is_recurring', coalesce(group_is_recurring, false),
      'recurring_cadence', clean_cadence,
      'collection_type', clean_type,
      'category_subtype', clean_subtype,
      'purpose_label', clean_purpose_label
    )
  );
end;
$$;


--
-- Name: update_collection_profile_and_receiver(uuid, text, text, text, text, boolean, text, text, text, text, boolean, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_collection_profile_and_receiver(collection uuid, group_name text, group_description text, group_image_url text, group_accent_color_hex text, group_is_public boolean, group_recurring_cadence text, group_collection_type text, group_category_subtype text, group_purpose_label text, group_is_recurring boolean, receiver_momo_number text, receiver_momo_number_hash text, receiver_label text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;
  if not exists (
    select 1
    from public.collections collection_row
    where collection_row.id = collection
      and collection_row.creator_user_id = auth.uid()
      and collection_row.archived_at is null
  ) then
    raise exception 'Only the current group owner can update group settings';
  end if;

  perform public.update_collection_profile(
    collection,
    group_name,
    group_description,
    group_image_url,
    group_accent_color_hex,
    group_is_public,
    group_recurring_cadence,
    group_collection_type,
    group_category_subtype,
    group_purpose_label,
    group_is_recurring
  );
  perform public.update_collection_receiver(
    collection,
    receiver_momo_number,
    receiver_momo_number_hash,
    receiver_label
  );
end;
$$;


--
-- Name: update_collection_receiver(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_collection_receiver(collection uuid, receiver_momo_number text, receiver_momo_number_hash text, receiver_label text DEFAULT 'Primary MOMO receiver'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  collection_row public.collections;
  clean_label text := coalesce(
    nullif(trim(receiver_label), ''),
    'Primary MOMO receiver'
  );
  submitted_digits text := regexp_replace(
    coalesce(receiver_momo_number, ''),
    '[^0-9]',
    '',
    'g'
  );
  profile_digits text;
  canonical_receiver text;
  computed_receiver_hash text;
  previous_receiver_hash text;
  previous_receiver_user_id uuid;
  receiver_is_code boolean;
  member_user_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select collection_row_value.*
  into collection_row
  from public.collections collection_row_value
  where collection_row_value.id = collection
  for update;

  if collection_row.id is null or collection_row.creator_user_id <> auth.uid() then
    raise exception 'Only the group owner can update the receiver';
  end if;

  receiver_is_code := lower(clean_label) like '%code%';
  if receiver_is_code then
    select regexp_replace(coalesce(profile.momo_pay_code, ''), '[^0-9]', '', 'g')
    into profile_digits
    from public.profiles profile
    where profile.id = auth.uid();
    if profile_digits !~ '^[0-9]{4,9}$' then
      raise exception 'Link a valid MoMo code to your profile first';
    end if;
    canonical_receiver := '+' || profile_digits;
  else
    select regexp_replace(coalesce(profile.momo_number, ''), '[^0-9]', '', 'g')
    into profile_digits
    from public.profiles profile
    where profile.id = auth.uid();
    if profile_digits ~ '^250[0-9]{9}$' then
      canonical_receiver := '+' || profile_digits;
    elsif profile_digits ~ '^0[0-9]{9}$' then
      canonical_receiver := '+250' || substr(profile_digits, 2);
    else
      raise exception 'Link a valid Rwanda MoMo number to your profile first';
    end if;
  end if;

  if submitted_digits <> regexp_replace(canonical_receiver, '[^0-9]', '', 'g')
     and not (
       not receiver_is_code
       and submitted_digits ~ '^0[0-9]{9}$'
       and substr(submitted_digits, 2) = substr(
         regexp_replace(canonical_receiver, '[^0-9]', '', 'g'),
         4
       )
     ) then
    raise exception 'Receiver must match the MoMo receiver linked to your profile';
  end if;

  computed_receiver_hash := encode(digest(canonical_receiver, 'sha256'), 'hex');
  if lower(trim(coalesce(receiver_momo_number_hash, ''))) <> computed_receiver_hash then
    raise exception 'Receiver verification failed';
  end if;

  select route.momo_number_hash, route.receiver_user_id
  into previous_receiver_hash, previous_receiver_user_id
  from public.collection_receivers route
  where route.collection_id = collection
    and route.is_active
  order by route.created_at desc
  limit 1;

  -- A profile-only save must not rotate an unchanged financial route or be
  -- blocked by pending intents. Label changes are non-financial metadata.
  if previous_receiver_hash = computed_receiver_hash
     and previous_receiver_user_id = auth.uid() then
    update public.collection_receivers
    set label = clean_label
    where collection_id = collection
      and is_active;
    update public.collections
    set receiver_display_label = clean_label,
        updated_at = now()
    where id = collection;
    return;
  end if;

  update public.payment_intents
  set status = 'expired'
  where collection_id = collection
    and status = 'pending'
    and expires_at <= now();
  if exists (
    select 1
    from public.payment_intents intent
    where intent.collection_id = collection
      and intent.status = 'pending'
  ) then
    raise exception 'Receiver cannot change while contribution requests are pending';
  end if;

  update public.collection_receivers
  set is_active = false
  where collection_id = collection
    and is_active;

  insert into public.collection_receivers (
    collection_id,
    receiver_user_id,
    momo_number,
    momo_number_hash,
    label,
    is_active
  ) values (
    collection,
    auth.uid(),
    canonical_receiver,
    computed_receiver_hash,
    clean_label,
    true
  );

  update public.collections
  set receiver_display_label = clean_label,
      updated_at = now()
  where id = collection;

  insert into public.audit_logs (
    actor_user_id,
    action,
    entity_type,
    entity_id,
    metadata
  ) values (
    auth.uid(),
    'collection.receiver_updated',
    'collection',
    collection,
    jsonb_build_object(
      'receiver_label', clean_label,
      'previous_receiver_hash', previous_receiver_hash,
      'new_receiver_hash', computed_receiver_hash,
      'profile_derived', true,
      'owner_only', true
    )
  );

  for member_user_id in
    select distinct member.user_id
    from public.collection_members member
    where member.collection_id = collection
      and member.status = 'active'
      and member.user_id <> auth.uid()
  loop
    perform public.enqueue_notification_template_event(
      member_user_id,
      'group.update.default',
      jsonb_build_object('group', collection_row.title),
      collection,
      '/groups/' || collection::text,
      'en'
    );
  end loop;
end;
$_$;


--
-- Name: update_current_member_profile(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_current_member_profile(p_country_code text, p_momo_provider text, p_momo_number text, p_momo_pay_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  profile_row public.profiles%rowtype;
  clean_provider text := lower(btrim(coalesce(p_momo_provider, '')));
  clean_momo text := public._rwanda_momo_local(p_momo_number);
  clean_code text := nullif(btrim(coalesce(p_momo_pay_code, '')), '');
  auth_phone text;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if upper(btrim(coalesce(p_country_code, ''))) <> 'RW' then
    raise exception 'Collect supports Rwanda profiles only';
  end if;
  if clean_provider not in ('mtn_momo', 'airtel_money') or clean_momo is null
     or (clean_provider = 'mtn_momo' and clean_momo !~ '^07[89][0-9]{7}$')
     or (clean_provider = 'airtel_money' and clean_momo !~ '^07[23][0-9]{7}$') then
    raise exception 'Choose a valid Rwanda MoMo provider and number';
  end if;
  if clean_code is not null and clean_code !~ '^[0-9]{4,9}$' then
    raise exception 'Enter a MoMo code with 4 to 9 digits';
  end if;
  select phone into auth_phone from auth.users where id = auth.uid();
  update public.profiles
  set country_code = 'RW',
      currency_code = 'RWF',
      momo_provider = clean_provider,
      momo_number = clean_momo,
      momo_number_hash = encode(
        extensions.digest('+250' || substr(clean_momo, 2), 'sha256'), 'hex'
      ),
      momo_number_verified_at = case
        when clean_momo = public._rwanda_momo_local(auth_phone)
          then coalesce(momo_number_verified_at, now())
        else null end,
      momo_pay_code = clean_code,
      revolut_link = null,
      revolut_account = null,
      updated_at = now()
  where id = auth.uid()
  returning * into profile_row;
  if profile_row.id is null then raise exception 'Collect profile not found'; end if;
  insert into public.audit_logs(actor_user_id, action, entity_type, entity_id, metadata)
  values (
    auth.uid(), 'profile.rwanda_momo.updated', 'profile', auth.uid(),
    jsonb_build_object(
      'country_code', 'RW', 'currency_code', 'RWF',
      'momo_provider', clean_provider,
      'momo_number_matches_whatsapp', profile_row.momo_number_verified_at is not null,
      'has_momo_code', clean_code is not null
    )
  );
  return public._member_profile_payload(profile_row);
end;
$_$;


--
-- Name: update_current_profile(text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_current_profile(p_display_name text, p_country_code text, p_momo_provider text DEFAULT NULL::text, p_momo_number text DEFAULT NULL::text, p_revolut_name text DEFAULT NULL::text, p_revolut_link text DEFAULT NULL::text, p_revolut_account text DEFAULT NULL::text) RETURNS public.profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  profile_row public.profiles%rowtype;
  country_rule public.profile_country_rules%rowtype;
  auth_phone text;
  clean_auth_momo text;
  clean_display text := btrim(coalesce(p_display_name, ''));
  clean_country text := upper(btrim(coalesce(p_country_code, '')));
  clean_provider text := lower(nullif(btrim(coalesce(p_momo_provider, '')), ''));
  clean_momo text := public._rwanda_momo_local(p_momo_number);
  clean_revolut_name text := nullif(btrim(coalesce(p_revolut_name, '')), '');
  clean_revolut_link text := nullif(btrim(coalesce(p_revolut_link, '')), '');
  clean_revolut_account text := nullif(btrim(coalesce(p_revolut_account, '')), '');
  previous_country text;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if char_length(clean_display) not between 2 and 80 then
    raise exception 'Display name must be between 2 and 80 characters';
  end if;
  select * into country_rule from public.profile_country_rules
  where country_code = clean_country and enabled;
  if country_rule.country_code is null then raise exception 'Unsupported profile country'; end if;

  if clean_country = 'RW' then
    if clean_provider not in ('mtn_momo', 'airtel_money') then
      raise exception 'Choose MTN MoMo or Airtel Money';
    end if;
    if clean_momo is null then
      raise exception 'Use a Rwanda MoMo number such as 078XXXXXXX';
    end if;
    if (clean_provider = 'mtn_momo' and clean_momo !~ '^07[89][0-9]{7}$')
       or (clean_provider = 'airtel_money' and clean_momo !~ '^07[23][0-9]{7}$') then
      raise exception 'MoMo provider does not match the Rwanda mobile number';
    end if;
  elsif clean_revolut_name is null
     or char_length(clean_revolut_name) not between 2 and 100
     or clean_revolut_link is null
     or clean_revolut_link !~ '^https://([a-z0-9-]+\.)?revolut\.me/[A-Za-z0-9._~-]+/?$'
     or clean_revolut_account is null
     or char_length(clean_revolut_account) not between 4 and 120 then
    raise exception 'Diaspora profiles require a Revolut name, Revolut.me link, and account details';
  end if;

  select country_code into previous_country from public.profiles where id = auth.uid();
  select phone into auth_phone from auth.users where id = auth.uid();
  clean_auth_momo := public._rwanda_momo_local(auth_phone);

  update public.profiles
  set display_name = clean_display,
      country_code = country_rule.country_code,
      currency_code = country_rule.currency_code,
      momo_provider = case when clean_country = 'RW' then clean_provider else null end,
      momo_number = case when clean_country = 'RW' then clean_momo else null end,
      momo_number_hash = case when clean_country = 'RW' then
        encode(extensions.digest('+250' || substr(clean_momo, 2), 'sha256'), 'hex')
        else null end,
      momo_number_verified_at = case
        when clean_country = 'RW' and clean_momo = clean_auth_momo
          then coalesce(momo_number_verified_at, now())
        else null
      end,
      revolut_name = case when clean_country <> 'RW' then clean_revolut_name else null end,
      revolut_link = case when clean_country <> 'RW' then clean_revolut_link else null end,
      revolut_account = case when clean_country <> 'RW' then clean_revolut_account else null end,
      updated_at = now()
  where id = auth.uid()
  returning * into profile_row;
  if profile_row.id is null then raise exception 'Collect profile not found'; end if;

  insert into public.audit_logs (actor_user_id, action, entity_type, entity_id, metadata)
  values (
    auth.uid(), 'profile.payment_route.updated', 'profile', auth.uid(),
    jsonb_build_object(
      'previous_country_code', previous_country,
      'country_code', profile_row.country_code,
      'currency_code', profile_row.currency_code,
      'payment_rail', case when clean_country = 'RW' then 'momo_ussd_sms' else 'diaspora_bank_revolut' end,
      'momo_provider', profile_row.momo_provider,
      'momo_number_matches_whatsapp', profile_row.momo_number_verified_at is not null,
      'has_revolut_link', profile_row.revolut_link is not null,
      'has_revolut_account', profile_row.revolut_account is not null
    )
  );
  return profile_row;
end;
$_$;


--
-- Name: update_rwanda_momo_group_profile(uuid, text, text, text, text, boolean, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_rwanda_momo_group_profile(p_collection_id uuid, p_group_name text, p_group_description text, p_group_image_url text DEFAULT NULL::text, p_group_accent_color_hex text DEFAULT NULL::text, p_group_is_public boolean DEFAULT false, p_group_recurring_cadence text DEFAULT 'monthly'::text, p_group_collection_type text DEFAULT NULL::text, p_group_category_subtype text DEFAULT NULL::text, p_group_purpose_label text DEFAULT NULL::text, p_group_is_recurring boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform collect_profile_access.assert_ready('rwanda');
  if not exists (
    select 1 from public.collections collection
    where collection.id = p_collection_id
      and collection.creator_user_id = auth.uid()
      and collection.archived_at is null
      and collection.currency = 'RWF'
      and not collection.diaspora_enabled
  ) then
    raise exception 'Only the current Rwanda group owner can update group settings';
  end if;
  perform public.update_collection_profile(
    p_collection_id, p_group_name, p_group_description,
    p_group_image_url, p_group_accent_color_hex,
    (select public_status = 'public_approved' from public.collections where id = p_collection_id),
    p_group_recurring_cadence, p_group_collection_type,
    p_group_category_subtype, p_group_purpose_label, p_group_is_recurring
  );
end;
$$;


--
-- Name: user_can_ingest_receiver_sms(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_can_ingest_receiver_sms(receiver_hash text DEFAULT NULL::text, collection uuid DEFAULT NULL::uuid, user_uuid uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select user_uuid is not null
    and coalesce((
      select consent.enabled
      from receiver_mode_consents consent
      where consent.user_id = user_uuid
      order by consent.created_at desc, consent.id desc
      limit 1
    ), false)
    and exists (
      select 1
      from collection_receivers receiver
      where receiver.is_active
        and (
          nullif(trim(receiver_hash), '') is null
          or receiver.momo_number_hash = receiver_hash
        )
        and (collection is null or receiver.collection_id = collection)
        and receiver.receiver_user_id = user_uuid
    );
$$;


--
-- Name: validate_collect_group_cover_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_collect_group_cover_reference() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.cover_image_url is null or new.cover_image_url not like 'collect-cover:%' then
    return new;
  end if;
  if new.cover_image_url <> all(array[
    'collect-cover:rw-01-neighbourhood-ikimina:v1',
    'collect-cover:rw-02-women-savings-circle:v1',
    'collect-cover:rw-03-young-professionals-goal:v1',
    'collect-cover:rw-04-market-traders-stock:v1',
    'collect-cover:rw-05-moto-riders-shared-goal:v1',
    'collect-cover:rw-06-farmers-season-inputs:v1',
    'collect-cover:rw-07-family-home-goal:v1',
    'collect-cover:rw-08-craft-cooperative-tools:v1',
    'collect-cover:rw-09-wedding-committee:v2',
    'collect-cover:rw-10-gusaba-gukwa-gathering:v2',
    'collect-cover:rw-11-wedding-attire-preparation:v2',
    'collect-cover:rw-12-wedding-reception-table:v2',
    'collect-cover:rw-13-new-home-wedding-gift:v2',
    'collect-cover:rw-14-wedding-day-family:v2',
    'collect-cover:rw-15-church-community-offering:v1',
    'collect-cover:rw-16-church-building-project:v1',
    'collect-cover:rw-17-choir-shared-equipment:v1',
    'collect-cover:rw-18-muslim-community-giving:v1',
    'collect-cover:rw-19-ramadan-community-meal:v1',
    'collect-cover:rw-20-community-giving-parcels:v1',
    'collect-cover:rw-21-bereavement-support:v1',
    'collect-cover:rw-22-medical-care-support:v1',
    'collect-cover:rw-23-health-cover-contribution:v1',
    'collect-cover:rw-24-neighbours-recovery-support:v1',
    'collect-cover:rw-25-family-everyday-support:v1',
    'collect-cover:rw-26-welcoming-new-baby:v1',
    'collect-cover:rw-27-school-supplies:v1',
    'collect-cover:rw-28-school-meal-support:v1',
    'collect-cover:rw-29-higher-study-support:v1',
    'collect-cover:rw-30-youth-skills-training:v1',
    'collect-cover:rw-31-umuganda-project-tools:v1',
    'collect-cover:rw-32-shared-water-point:v1',
    'collect-cover:rw-33-community-hall-improvement:v1',
    'collect-cover:rw-34-tree-planting-neighbours:v1',
    'collect-cover:rw-35-football-fan-community:v1',
    'collect-cover:rw-36-local-team-equipment:v1',
    'collect-cover:rw-37-away-match-travel:v1',
    'collect-cover:rw-38-cultural-troupe-rehearsal:v1',
    'collect-cover:rw-39-diaspora-family-connection:v1',
    'collect-cover:rw-40-diaspora-community-project:v1',
    'collect-cover:rw-41-buri-munsi:v1',
    'collect-cover:rw-42-gikundiro:v1',
    'collect-cover:rw-43-church-congregation:v1',
    'collect-cover:rw-44-football-fans-matchday:v1'
  ]::text[]) then
    raise exception 'Unknown group cover or version' using errcode = '22023';
  end if;
  if new.cover_image_url in ('collect-cover:rw-41-buri-munsi:v1', 'collect-cover:rw-42-gikundiro:v1')
     and not (coalesce(new.is_platform_sponsored, false)
       and coalesce(new.public_status::text, '') = 'public_approved'
       and ((new.slug = 'buri-munsi' and new.cover_image_url = 'collect-cover:rw-41-buri-munsi:v1')
         or (new.slug = 'gikundiro' and new.cover_image_url = 'collect-cover:rw-42-gikundiro:v1'))) then
    raise exception 'This cover is reserved for its approved public group' using errcode = '22023';
  end if;
  return new;
end;
$$;


--
-- Name: verify_roster_source_integrity(uuid, uuid, uuid, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_roster_source_integrity(p_reservation_id uuid, p_actor_id uuid, p_session_id uuid, p_decoder_receipt_sha256 text, p_decoder_build_sha256 text, p_policy_version text, p_toolchain jsonb, p_summary jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
   begin perform collect_hybrid.guard_roster_service_recovery((select s.id from collect_hybrid.roster_import_sources s join collect_hybrid.roster_resource_reservations r on r.request_id=s.request_id where r.id=p_reservation_id)); return collect_hybrid.verify_roster_source_integrity_guarded_149(p_reservation_id,p_actor_id,p_session_id,p_decoder_receipt_sha256,p_decoder_build_sha256,p_policy_version,p_toolchain,p_summary); end $$;


--
-- Name: http_request(); Type: FUNCTION; Schema: supabase_functions; Owner: -
--

CREATE FUNCTION supabase_functions.http_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'supabase_functions'
    AS $$
  DECLARE
    request_id bigint;
    payload jsonb;
    url text := TG_ARGV[0]::text;
    method text := TG_ARGV[1]::text;
    headers jsonb DEFAULT '{}'::jsonb;
    params jsonb DEFAULT '{}'::jsonb;
    timeout_ms integer DEFAULT 1000;
  BEGIN
    IF url IS NULL OR url = 'null' THEN
      RAISE EXCEPTION 'url argument is missing';
    END IF;

    IF method IS NULL OR method = 'null' THEN
      RAISE EXCEPTION 'method argument is missing';
    END IF;

    IF TG_ARGV[2] IS NULL OR TG_ARGV[2] = 'null' THEN
      headers = '{"Content-Type": "application/json"}'::jsonb;
    ELSE
      headers = TG_ARGV[2]::jsonb;
    END IF;

    IF TG_ARGV[3] IS NULL OR TG_ARGV[3] = 'null' THEN
      params = '{}'::jsonb;
    ELSE
      params = TG_ARGV[3]::jsonb;
    END IF;

    IF TG_ARGV[4] IS NULL OR TG_ARGV[4] = 'null' THEN
      timeout_ms = 1000;
    ELSE
      timeout_ms = TG_ARGV[4]::integer;
    END IF;

    CASE
      WHEN method = 'GET' THEN
        SELECT http_get INTO request_id FROM net.http_get(
          url,
          params,
          headers,
          timeout_ms
        );
      WHEN method = 'POST' THEN
        payload = jsonb_build_object(
          'old_record', OLD,
          'record', NEW,
          'type', TG_OP,
          'table', TG_TABLE_NAME,
          'schema', TG_TABLE_SCHEMA
        );

        SELECT http_post INTO request_id FROM net.http_post(
          url,
          payload,
          params,
          headers,
          timeout_ms
        );
      ELSE
        RAISE EXCEPTION 'method argument % is invalid', method;
    END CASE;

    INSERT INTO supabase_functions.hooks
      (hook_table_id, hook_name, request_id)
    VALUES
      (TG_RELID, TG_NAME, request_id);

    RETURN NEW;
  END
$$;


