    request_id uuid NOT NULL,
    event_type text NOT NULL,
    payload_sha256 text NOT NULL,
    payment_id uuid NOT NULL,
    provider_network text,
    provider_reference text,
    status text DEFAULT 'processing'::text NOT NULL,
    result_payment_id uuid,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_at timestamp with time zone,
    input_sha256 text,
    CONSTRAINT provider_finality_requests_check CHECK (((result_payment_id IS NULL) OR (result_payment_id = payment_id))),
    CONSTRAINT provider_finality_requests_check1 CHECK ((((status = 'processing'::text) AND (result_payment_id IS NULL) AND (processed_at IS NULL)) OR ((status = 'processed'::text) AND (result_payment_id IS NOT NULL) AND (processed_at IS NOT NULL)))),
    CONSTRAINT provider_finality_requests_event_type_check CHECK ((event_type = ANY (ARRAY['payment.confirmed'::text, 'payment.rejected'::text]))),
    CONSTRAINT provider_finality_requests_input_sha256_check CHECK ((input_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT provider_finality_requests_payload_sha256_check CHECK ((payload_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT provider_finality_requests_provider_network_check CHECK (((provider_network IS NULL) OR (((char_length(provider_network) >= 2) AND (char_length(provider_network) <= 32)) AND (provider_network ~ '^[a-z0-9_]+$'::text)))),
    CONSTRAINT provider_finality_requests_provider_reference_check CHECK (((provider_reference IS NULL) OR ((char_length(provider_reference) >= 1) AND (char_length(provider_reference) <= 128)))),
    CONSTRAINT provider_finality_requests_status_check CHECK ((status = ANY (ARRAY['processing'::text, 'processed'::text])))
);


--
-- Name: COLUMN provider_finality_requests.input_sha256; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.provider_finality_requests.input_sha256 IS 'Server-computed normalized RPC-input digest. NULL marks legacy requests whose full input identity is unverified; replay requires reconciliation.';


--
-- Name: public_collections_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.public_collections_view WITH (security_invoker='true', security_barrier='true') AS
 SELECT collection.id,
    collection.slug,
    collection.title,
    collection.description,
    collection.category,
    collection.cover_image_url,
    collection.target_amount_rwf,
    collection.deadline_at,
    collection.is_recurring,
    collection.created_at,
    collection.collection_type,
    collection.category_subtype,
    collection.purpose_label,
    collection.suggested_amount_rwf,
    collection.accent_color_hex,
    collection.recurring_cadence,
    collection.is_platform_sponsored,
    false AS diaspora_enabled,
    '{}'::text[] AS diaspora_regions,
    COALESCE(route.payment_rail, 'unavailable'::text) AS payment_rail,
    COALESCE(route.settlement_currency, collection.currency) AS settlement_currency,
    route.receiver_momo_number,
    route.receiver_display_label,
    route.receiver_network
   FROM (public.collections collection
     LEFT JOIN LATERAL public.public_collection_payment_route(collection.id) route(payment_rail, settlement_currency, receiver_momo_number, receiver_display_label, receiver_network) ON (true))
  WHERE ((collection.public_status = 'public_approved'::public.collection_visibility) AND collection.is_platform_sponsored AND (collection.archived_at IS NULL) AND (collection.currency = 'RWF'::text) AND (NOT collection.diaspora_enabled));


--
-- Name: VIEW public_collections_view; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.public_collections_view IS 'Signed-out-safe platform group directory with the minimum contribution route; private receiver ownership and hashes are excluded.';


--
-- Name: public_contributions_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.public_contributions_view WITH (security_invoker='true') AS
 SELECT id AS payment_id,
    collection_id,
    amount_rwf,
    posted_at,
        CASE
            WHEN (contributor_public_id IS NOT NULL) THEN ('Collect ID '::text || (contributor_public_id)::text)
            ELSE 'Collect member'::text
        END AS supporter_label
   FROM public.payments p
  WHERE (status = 'posted'::text);


--
-- Name: public_profiles_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.public_profiles_view WITH (security_invoker='true') AS
 SELECT id,
    ('Collect ID '::text || (public_id)::text) AS public_label,
    NULL::text AS avatar_url,
    created_at
   FROM public.profiles;


